INSERT IGNORE INTO `park_info` VALUES (14, 'PK00014', '柳州东城海阳颐养中心', '柳州东城海阳颐养中心', 'SP00004', '东城海阳', NULL, NULL, NULL, NULL, '<p style=\"text-indent: 2em;\"><strong>海阳大健康产业集团</strong></p><p style=\"text-indent: 2em;\">海阳大健康产业集团隶属于海阳集团，是全国领先的养老服务综合供应商。借助物联网、大数据、“互联网＋”等技术手段，在线上建立智慧平台，线下组建由智能设备、服务人员、供应商等全方位立体型养老服务网络。</p><p style=\"text-indent: 2em;\"><strong>海阳医疗集团</strong></p><p style=\"text-indent: 2em;\">集团2006年开始关注大健康领域，成立了海阳健康管理（上海）有限公司，由集团全资控股。是集健康咨询、健康管理、健康干预及远程诊断于一体的高科技信息服务公司，也是三甲医院分级诊疗机构。</p>', NULL, NULL, NULL, 2, NULL, 'care,sojourn', NULL, '{\"banners\":[\"park/migration/2026/08/08/pk00014_000.jpg\",\"park/migration/2026/08/08/pk00014_001.jpg\",\"park/migration/2026/08/08/pk00014_002.jpg\",\"park/migration/2026/08/08/pk00014_room_019.png\",\"park/migration/2026/08/08/pk00014_room_021.png\",\"park/migration/2026/08/08/pk00014_food_198.png\",\"park/migration/2026/08/08/pk00014_cat_205.png\",\"park/migration/2026/08/08/pk00014_ent_000.jpg\"],\"thumbnail\":\"park/migration/2026/08/08/pk00014_000.jpg\"}', '{\"banners\":[\"park/migration/2026/08/08/pk00014_000.jpg\",\"park/migration/2026/08/08/pk00014_001.jpg\",\"park/migration/2026/08/08/pk00014_002.jpg\",\"park/migration/2026/08/08/pk00014_room_019.png\",\"park/migration/2026/08/08/pk00014_room_021.png\",\"park/migration/2026/08/08/pk00014_food_198.png\",\"park/migration/2026/08/08/pk00014_cat_205.png\",\"park/migration/2026/08/08/pk00014_ent_000.jpg\"],\"thumbnail\":\"park/migration/2026/08/08/pk00014_000.jpg\"}', 2, NULL, NULL, 5, '广西壮族自治区', '450000', '柳州市', '450200', '鱼峰区', '450203', '花岭路31号', 109.449416, 24.318522, NULL, NULL, NULL, '9727.22', '17250.55', '35', 372, NULL, NULL, NULL, NULL, NULL, 5000, NULL, '元/月', NULL, NULL, NULL, NULL, NULL, NULL, 0, 2, NULL, 1, '2023-04-18 00:00:00', NULL, NULL, NULL, 1, 0, 0, NULL, 0, '2026-08-09 09:49:59', '2026-08-12 19:46:52', 'system', 'system', 0, NULL);
