INSERT IGNORE INTO `scene_info` VALUES (10, 'SC00001', '泰康社区参观体验', 1, 'PK00001', '110000', '110100', '110105', '北京市朝阳区建国路88号', '深入体验泰康高品质养老社区，感受医养结合的创新生活方式。参观样板间、活动中心、医疗站，与在住长辈交流。', '', NULL, NULL, 20, 3.0, '有养老需求的家庭', '[\"一对一管家陪同参观\",\"免费健康检测\",\"营养午餐体验\",\"精美伴手礼\"]', '请提前预约，活动当天请携带身份证', 2, 20, 199.00, 99.00, '元/人', 0, 1, 156, 38, 1, 1, NULL, '2026-08-11 12:52:41', '2026-08-11 12:52:41', 'system', 'system', 0, NULL);
INSERT IGNORE INTO `scene_info` VALUES (11, 'SC00002', '老年健康知识讲座', 2, 'PK00001', '110000', '110100', '110105', '北京市朝阳区建国路88号', '权威专家主讲，涵盖慢性病管理、营养饮食、心理健康等主题，帮助长辈科学养老。', '', NULL, NULL, 50, 2.0, '50岁以上长者及家属', '[\"三甲医院专家主讲\",\"免费血压血糖检测\",\"一对一健康咨询\",\"健康手册赠阅\"]', '讲座免费，座位有限请提前预约', 5, 50, 0.00, 0.00, '元/人', 1, 2, 89, 52, 1, 1, NULL, '2026-08-11 12:52:41', '2026-08-11 12:52:41', 'system', 'system', 0, NULL);
INSERT IGNORE INTO `scene_info` VALUES (12, 'SC00003', '中秋敬老文化节', 4, 'PK00001', '110000', '110100', '110105', '北京市朝阳区建国路88号', '中秋佳节主题活动，包含月饼制作、文艺演出、亲子互动等环节，共度温馨团圆时光。', '', NULL, NULL, 100, 4.0, '全年龄段家庭', '[\"手工月饼制作\",\"文艺演出欣赏\",\"亲子互动游戏\",\"团圆晚宴\"]', '节假日活动，建议家庭参与（2-4人）', 3, 30, 299.00, 199.00, '元/家庭', 0, 3, 203, 67, 1, 1, NULL, '2026-08-11 12:52:41', '2026-08-11 12:52:41', 'system', 'system', 0, NULL);
