INSERT IGNORE INTO `system_log_agent` VALUES (682, '505eecdb5e5f4c9884cdbf66c314cafd', 'agent', 'AG60785666', 'agent01', 'auth', '验证码登录', '登录成功', 'account', 'AG60785666', NULL, '/agent-api/auth/sms/login', 'POST', '{\"loginType\":\"sms\",\"identity\":\"139****0001\"}', NULL, NULL, '0:0:0:0:0:0:0:1', NULL, 'Mozilla/5.0 (iPhone; CPU iPhone OS 18_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.5 Mobile/15E148 Safari/604.1', 'mobile', 'macOS', 'Safari', 1, NULL, NULL, '2026-08-21 14:35:34', '2026-08-21 14:35:34', 'system', 'system', 0, NULL);
INSERT IGNORE INTO `system_log_agent` VALUES (683, '50972f139f594e80b6b0dc87c7e76ffb', 'agent', 'AG60785666', 'agent01', '文章转写', '抓取URL内容', NULL, NULL, NULL, NULL, '/agent-api/tools/article-rewrite/fetch-url', 'POST', '{\"dto\":{\"toolCode\":\"TL90008\",\"url\":\"https://mp.weixin.qq.com/s/yDKjIUPr1oHtinRR5JQM-w\"}}', '{\"code\":0,\"message\":\"success\",\"data\":{\"id\":5,\"toolCode\":\"TL90008\",\"agentCode\":\"AG60785666\",\"channelCode\":\"CH00001\",\"status\":\"CREATED\",\"contentFetch\":\"{\\\"sourceType\\\":\\\"url\\\",\\\"sourceUrl\\\":\\\"https://mp.weixin.qq.com/s/yDKjIUPr1oHtinRR5JQM-w\\\",\\\"originalTitle\\\":\\\"该死的银狐病毒，让我失业又社死\\\",\\\"originalSource\\\":\\\"微信公众平台\\\",\\\"originalContent\\\":\\\"该死的银狐病毒，让我失业又社死 原创 buliqidun1 buliqidun1 是Fennie呀 在小说阅读器读本章 去阅读 在小说阅读器中沉浸阅读 电脑中毒微信被盗的24小时 我是怎样度过的 建议： 1.电脑一定要装杀毒软件，360和火绒，360还有银狐专门解决方案。 2.下载软件认准官网，一定要注意前后缀还有拼写错误，不确定就问一下AI 3.电脑不用一定要关机，一定要退出微信。 4.除了自己的手机，其他设备都不要记住微信账号。 5.不要点击别人发送的任何可疑的链接和信息，比如红包，扫码进群等等，即使对方是亲近的家人朋友同事，有可能是犯罪分子发的，尤其是通过群聊发送的。 6.转账一定要视频确认是本人，不管金额再小时间再晚 7.天上不会掉馅饼！任何轻易可以赚到钱的都有坑🕳️在等你！ 经此一遭，我再也不认为网络安全和黑客离我很遥远了，时时刻刻都得注意。 08.14周五 事情经过： 正在电脑前工作，突然朋友发消息问我微信是不是被盗了。 我吓了一跳，Ta给我发过来两个截图（14：27），“我”在国际会议群里发诈骗信息，赶紧给弟弟打电话然后电脑紧急断网。 现在黑产诈骗分子也太猖獗了吧，我的电脑疑似中了银狐病毒，我甚至连怎么感染的都不知道。 诈骗分子把我微信所有有几百个人的大群聊折叠然后免打扰，在群里发诈骗信息用红包引导人进诈骗群，我怀疑他们把人拉进群里会让他们的电脑也中病毒。 我昨天去重装完系统，今天打开手机微信的折叠群聊才发现，好家伙一个没落，通通发了诈骗信息。好多群主都把我踢出去了！ 我只好一个一个群解释。然后不重要的群赶紧退了。 然后在CSC群里还发现了另外一个中招的同学，他是下载Deepseek客户端时进了假的网址，下载了带病毒的软件导致的。他遇到软件打不开，后台运行程序莫名很多的情况。我不记得最近我下载什么了。 还有个群里的姐妹打电话给我询问我的情况，然后说现在警察在保护她，她不能细说，还说她有抑郁症刚去医院回来，让我去报警，一通话把我搞得如临大敌。 失业是因为我的工作很多需要微信沟通，那两个国际大会群对我来说也很重要，差点失业。社死是发这种诈骗信息到各个工作群里，你说社死不社死😭 结果装完系统，我拿火绒一扫，又发现一个病毒。我想哭，我想换一台电脑了5555 只好再查杀一遍。 然后又发现个新问题，我的微信好友看不到我的朋友圈了，只有我自己能看到，其他人点进我的主页也看不到😭小redbook上还有好多人都这样，实在不知道为什么(｡•́︿•̀｡)微信客户也找不到人5555 周游世界回来 我还是买不起农村老家的衣服 只能来电脑店备份资料后重装系统。趁着这个时间和爸爸去吃了个饭，然后去逛商场。菜色很不错，山药炖腊猪脚😍，炒白杨豆干，炒萝卜缨子，凉拌豌豆粉和的黄瓜，炸洋芋片，合渣，玉米糊糊，包谷饭，人均80元。 尤其是炖腊猪脚里面的山药，炒豆干也太好吃了！ 吃完饭，爸爸去台球厅打台球，我去逛商场，衣服动辄500-600，800-900也是屡见不鲜，在东京逛惯了二手市场的我，真的也是买不起。 扪心自问，我的工资也不算特别低的了，面对故乡这个十八线小县城的衣服价格，我还是望而却步。 我老家很多人的收入还比不上我，真的不知道到底是谁在消费这些。 最后我买了一套温柔的紫色套装，因为最近爱上了紫色不可自拔！ 电脑重装好了，回家和爸爸打了几盘台球，他又没赢到钱哈哈哈洗澡睡觉💤 预览时标签不可点 微信扫一扫 关注该公众号 知道了 微信扫一扫 使用小程序 取消 允许 取消 允许 取消 允许 × 分析 微信扫一扫可打开此内容， 使用完整服务 ： ， ， ， ， ， ， ， ， ， ， ， ， 。 视频 小程序 赞 ，轻点两下取消赞 在看 ，轻点两下取消在看 分享 留言 收藏 听过\\\",\\\"fetchTime\\\":\\\"2026-08-21T14:36:34.2802219\\\",\\\"fetchStatus\\\":\\\"success\\\"}\",\"summaryAnalysis\":null,\"rewriteResult\":null,\"auditResult\":null,\"imageResult\":null,\"publishInfo\":null,\"createdAt\":\"2026-08-21T14:36:34.3520412\",\"updatedAt\":\"2026-08-21T14:36:34.3520412\"},\"timestamp\":1787294194408,\"traceId\":\"50972f139f594e80b6b0dc87c7e76ffb\"}', 0, '0:0:0:0:0:0:0:1', NULL, 'Mozilla/5.0 (iPhone; CPU iPhone OS 18_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.5 Mobile/15E148 Safari/604.1', 'mobile', 'macOS', 'Safari', 1, NULL, 5957, '2026-08-21 14:36:34', '2026-08-21 14:36:34', 'system', 'system', 0, NULL);
INSERT IGNORE INTO `system_log_agent` VALUES (684, '7d7c4c86d45c4b5bb126f996378f216f', 'agent', 'AG60785666', 'agent01', '文章转写', '抓取URL内容', NULL, NULL, NULL, NULL, '/agent-api/tools/article-rewrite/fetch-url', 'POST', '{\"dto\":{\"toolCode\":\"TL90008\",\"url\":\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\"}}', '{\"code\":0,\"message\":\"success\",\"data\":{\"id\":6,\"toolCode\":\"TL90008\",\"agentCode\":\"AG60785666\",\"channelCode\":\"CH00001\",\"status\":\"CREATED\",\"contentFetch\":\"{\\\"sourceType\\\":\\\"url\\\",\\\"sourceUrl\\\":\\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\",\\\"originalTitle\\\":\\\"扎实做好“五篇大文章” 推动金融高质量发展\\\",\\\"originalSource\\\":\\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\",\\\"originalContent\\\":\\\"扎实做好“五篇大文章” 推动金融高质量发展 （信贷市场司党支部） “为了提供高质量金融服务，金融系统要着力做好科技金融、绿色金融、普惠金融、养老金融、数字金融五篇大文章”。在中央金融工作会议上，习近平总书记对做好“五篇大文章”作出重要部署，擘画了以金融高质量发展助力国家重大战略实施和强国建设的宏伟蓝图，指明了金融支持经济高质量发展的发力点和经济金融结构优化的基本方向，是新时代新征程金融服务实体经济高质量发展的根本遵循和行动指南。“五篇大文章”各领域情况不同，金融服务方向各有侧重，需要坚持需求导向和问题导向，以深化金融供给侧结构性改革为主线，加强金融政策与产业政策协同配合，分类施策、系统推进，不断增强金融支持的力度、可持续性和专业化水平。 一、科技金融迎难而上、聚焦重点，加大对实现科技自立自强和科技强国建设的金融支持力度 习近平总书记多次强调，要“坚持创新在我国现代化建设全局中的核心地位，坚持把科技自立自强作为国家发展的战略支撑”“加快发展新质生产力”。金融与科技、产业形成良性循环，是推动科技创新和产业创新的重要力量。科技创新复杂多元，不同科创主体和活动、科技型企业成长生命周期不同阶段，金融需求差异较大，需要统筹运用好股权、债权、保险等手段为科技型企业提供全链条、全生命周期金融服务。 近年来，中国人民银行持续加强科技金融服务工作，牵头制定《加大力度支持科技型企业融资行动方案》，设立支持科技创新的结构性货币政策工具，稳妥推动科创金融改革试验区建设，持续提升金融服务科技创新的能力和水平。截至2024年3月末，高技术制造业中长期贷款、科技型中小企业贷款、“专精特新”企业贷款分别同比增长27.3%、20.4%、17.9%，明显高于各项贷款增速；科技型中小企业获贷率达到46.5%，较2017年末提升2倍；科创票据累计发行达5600亿元。下一步，中国人民银行将深入落实加大力度支持科技型企业融资行动方案，聚焦国家重大科技任务、科技型中小企业等重点领域及科技要素密集地区，完善金融支持政策体系和配套机制，丰富金融支持工具，全面提升金融机构和金融市场服务科技创新能力，建成与高水平科技自立自强目标高度适配的金融服务体系。 二、绿色金融乘势而上、先立后破，为推动全社会绿色发展和服务美丽中国建设提供高质量金融供给 党的十八大以来，以习近平同志为核心的党中央高度重视生态文明建设，将发展绿色金融作为推动实现碳达峰碳中和、建设美丽中国的重要举措，多次作出重要部署。推动全社会绿色低碳发展涉及行业多、投资周期长、资金需求大，需要充分发挥绿色金融的资源优化配置作用。绿色金融也提供了新的业务增长点，有利于金融机构有序调整资产配置，助力实现金融高质量发展。 中国人民银行始终将发展绿色金融作为重点工作，持续强化顶层设计和政策引领。截至2024年3月末，绿色贷款余额33.8万亿元，同比增长35.1%，连续三年保持30%以上增速；绿色债券累计发行超过3.6万亿元，余额超过1.9万亿元，市场规模位居世界前列，为保障国家能源安全、助力碳达峰碳中和提供有力支持。2024年4月，中国人民银行牵头出台《关于进一步强化金融支持绿色低碳发展的指导意见》，创设碳减排支持工具，创新碳中和债、可持续发展挂钩债券等产品，开展绿色金融国际合作交流，进一步推动绿色信贷、绿色债券等绿色融资较快增长。下一步，中国人民银行将统筹好对绿色发展和低碳转型的支持，发挥好碳减排支持工具的示范引领作用，不断完善绿色金融标准体系，稳步推进绿色金融产品和市场高质量发展，提升绿色金融服务质效和可持续性。 三、普惠金融雪中送炭、服务民生，构建多层次、广覆盖、可持续的普惠金融体系 习近平总书记就发展普惠金融多次作出部署，要求“始终坚持以人民为中心的发展思想，推进普惠金融高质量发展”。小微企业是发展的生力军、就业的主渠道，“三农”是经济社会发展的“压舱石”，民生领域是促进共同富裕的关键一环。发展普惠金融，让社会不同群体都平等享受基础金融服务，是金融工作政治性、人民性的重要体现，也是金融助力实现共同富裕的重要路径。 近年来，中国人民银行多措并举，持续加强民营小微、乡村振兴、民生等领域金融服务工作。牵头印发金融支持民营经济“25条举措”、《关于金融支持全面推进乡村振兴 加快建设农业强国的指导意见》等文件，用好用足支农支小再贷款，延续实施普惠小微贷款支持工具，持续开展中小微企业金融服务能力提升工程，调整优化创业担保贷款政策、助学贷款政策，提升普惠领域金融服务可得性和便利性，相关贷款实现“量增、面扩、价降”。截至2024年3月末，普惠小微贷款、涉农贷款、助学贷款分别同比增长20.3%、13.5%、22.5%，高于各项贷款增速；普惠小微授信户数超过6000万户，已覆盖三分之一的经营主体；2024年3月新发放普惠小微贷款加权平均利率4.36%，处于历史较低水平。下一步，中国人民银行将统筹兼顾增量扩面和商业可持续，落实落细相关政策，优化普惠重点领域产品和服务供给，健全多层次普惠金融机构组织体系，加快构建激励相容的普惠金融发展长效机制。 四、养老金融健全体系、增进福祉，助力积极应对人口老龄化国家战略实施 我国人口总量庞大，近年来人口老龄化程度加深。有效应对人口老龄化，事关国家发展全局，事关亿万百姓福祉。习近平总书记在中央金融工作会议上强调，要“加大对健康产业、养老产业、银发经济的财税金融政策支持，有针对性地丰富养老金融产品供给，积极发展第三支柱养老保险，更好满足日益多元化的养老金融需求”。近年来，中国人民银行多措并举加大金融对养老领域和银发经济的支持力度，牵头出台《关于金融支持养老服务业加快发展的指导意见》，推动普惠养老专项再贷款试点全面扩围，引导金融机构积极开展养老理财和特定养老储蓄试点工作，推动银行网点和线上服务亲老适老化改造，针对老年人等群体支付习惯提升支付便利化水平，相关工作取得成效。 下一步，中国人民银行将完善养老金融相关政策、业务、产品体系，推动多层次、多支柱养老保险体系建设，用好用足普惠养老专项再贷款工具，提升养老金融供求适配性和养老产业发展的资金供给水平，实现中国特色金融和养老事业高质量发展良性循环。 五、数字金融把握机遇、重视安全，构建与支撑金融强国建设和数字经济发展相适应的数字金融服务体系 习近平总书记指出“当今时代，数字技术、数字经济是世界科技革命和产业变革的先机，是新一轮国际竞争重点领域”。中央金融工作会议把数字金融提高到国家发展战略的新高度，作出明确部署。金融是数据密集型行业，数字技术历来是金融业发展的重要推动力。顺应数字经济时代变革，借助大数据、人工智能、云计算等数字技术，加快金融业数字化转型，有助于推动金融机构和金融市场提升服务效率，降低运行成本，增强服务实体经济和防范金融风险的能力。 近年来，中国人民银行加强数字金融顶层制度设计，实施金融数字化转型提升工程，深化实施金融科技创新监管工具，扎实推进数字人民币试点，实施金融科技赋能乡村振兴示范工程，有力推动了数字金融发展。下一步，中国人民银行将统筹发展和安全，发挥数据要素和数字技术双轮驱动作用，系统推进金融数字化转型，加强数字技术在科技金融、普惠金融、绿色金融、养老金融的赋能运用，稳妥推进数字人民币研发和应用，完善数字金融治理体系，提升金融服务的便利性和竞争力，助力金融强国建设和巩固拓展数字经济优势。 中国人民银行将与相关部门密切协作，全力做好“五篇大文章”，以高质量金融服务推动经济高质量发展，为奋力实现中国式现代化宏伟目标提供坚实有力的金融支撑。 法律声明 | 联系我们 | 设为首页 | 加入收藏 | 网站地图 京ICP备05073439号 网站标识码：bm25000001 京公网安备 11010202000016号 网站主办单位：中国人民银行办公厅　最佳分辨率：1024*768\\\",\\\"fetchTime\\\":\\\"2026-08-21T14:52:27.8045561\\\",\\\"fetchStatus\\\":\\\"success\\\"}\",\"summaryAnalysis\":null,\"rewriteResult\":null,\"auditResult\":null,\"imageResult\":null,\"publishInfo\":null,\"createdAt\":\"2026-08-21T14:52:27.8055558\",\"updatedAt\":\"2026-08-21T14:52:27.8055558\"},\"timestamp\":1787295147849,\"traceId\":\"7d7c4c86d45c4b5bb126f996378f216f\"}', 0, '0:0:0:0:0:0:0:1', NULL, 'Mozilla/5.0 (iPhone; CPU iPhone OS 18_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.5 Mobile/15E148 Safari/604.1', 'mobile', 'macOS', 'Safari', 1, NULL, 503, '2026-08-21 14:52:28', '2026-08-21 14:52:28', 'system', 'system', 0, NULL);
INSERT IGNORE INTO `system_log_agent` VALUES (685, 'efed04845a524424b4ec02faef59fd92', 'agent', 'AG60785666', 'agent01', '文章转写', '生成总结', NULL, NULL, NULL, NULL, '/agent-api/tools/article-rewrite/6/summary', 'POST', '{\"id\":6}', '{\"code\":0,\"message\":\"success\",\"data\":{\"id\":6,\"toolCode\":\"TL90008\",\"agentCode\":\"AG60785666\",\"channelCode\":\"CH00001\",\"status\":\"SUMMARY_DONE\",\"contentFetch\":\"{\\\"fetchTime\\\": \\\"2026-08-21T14:52:27.8045561\\\", \\\"sourceUrl\\\": \\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\", \\\"sourceType\\\": \\\"url\\\", \\\"fetchStatus\\\": \\\"success\\\", \\\"originalTitle\\\": \\\"扎实做好“五篇大文章” 推动金融高质量发展\\\", \\\"originalSource\\\": \\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\", \\\"originalContent\\\": \\\"扎实做好“五篇大文章” 推动金融高质量发展 （信贷市场司党支部） “为了提供高质量金融服务，金融系统要着力做好科技金融、绿色金融、普惠金融、养老金融、数字金融五篇大文章”。在中央金融工作会议上，习近平总书记对做好“五篇大文章”作出重要部署，擘画了以金融高质量发展助力国家重大战略实施和强国建设的宏伟蓝图，指明了金融支持经济高质量发展的发力点和经济金融结构优化的基本方向，是新时代新征程金融服务实体经济高质量发展的根本遵循和行动指南。“五篇大文章”各领域情况不同，金融服务方向各有侧重，需要坚持需求导向和问题导向，以深化金融供给侧结构性改革为主线，加强金融政策与产业政策协同配合，分类施策、系统推进，不断增强金融支持的力度、可持续性和专业化水平。 一、科技金融迎难而上、聚焦重点，加大对实现科技自立自强和科技强国建设的金融支持力度 习近平总书记多次强调，要“坚持创新在我国现代化建设全局中的核心地位，坚持把科技自立自强作为国家发展的战略支撑”“加快发展新质生产力”。金融与科技、产业形成良性循环，是推动科技创新和产业创新的重要力量。科技创新复杂多元，不同科创主体和活动、科技型企业成长生命周期不同阶段，金融需求差异较大，需要统筹运用好股权、债权、保险等手段为科技型企业提供全链条、全生命周期金融服务。 近年来，中国人民银行持续加强科技金融服务工作，牵头制定《加大力度支持科技型企业融资行动方案》，设立支持科技创新的结构性货币政策工具，稳妥推动科创金融改革试验区建设，持续提升金融服务科技创新的能力和水平。截至2024年3月末，高技术制造业中长期贷款、科技型中小企业贷款、“专精特新”企业贷款分别同比增长27.3%、20.4%、17.9%，明显高于各项贷款增速；科技型中小企业获贷率达到46.5%，较2017年末提升2倍；科创票据累计发行达5600亿元。下一步，中国人民银行将深入落实加大力度支持科技型企业融资行动方案，聚焦国家重大科技任务、科技型中小企业等重点领域及科技要素密集地区，完善金融支持政策体系和配套机制，丰富金融支持工具，全面提升金融机构和金融市场服务科技创新能力，建成与高水平科技自立自强目标高度适配的金融服务体系。 二、绿色金融乘势而上、先立后破，为推动全社会绿色发展和服务美丽中国建设提供高质量金融供给 党的十八大以来，以习近平同志为核心的党中央高度重视生态文明建设，将发展绿色金融作为推动实现碳达峰碳中和、建设美丽中国的重要举措，多次作出重要部署。推动全社会绿色低碳发展涉及行业多、投资周期长、资金需求大，需要充分发挥绿色金融的资源优化配置作用。绿色金融也提供了新的业务增长点，有利于金融机构有序调整资产配置，助力实现金融高质量发展。 中国人民银行始终将发展绿色金融作为重点工作，持续强化顶层设计和政策引领。截至2024年3月末，绿色贷款余额33.8万亿元，同比增长35.1%，连续三年保持30%以上增速；绿色债券累计发行超过3.6万亿元，余额超过1.9万亿元，市场规模位居世界前列，为保障国家能源安全、助力碳达峰碳中和提供有力支持。2024年4月，中国人民银行牵头出台《关于进一步强化金融支持绿色低碳发展的指导意见》，创设碳减排支持工具，创新碳中和债、可持续发展挂钩债券等产品，开展绿色金融国际合作交流，进一步推动绿色信贷、绿色债券等绿色融资较快增长。下一步，中国人民银行将统筹好对绿色发展和低碳转型的支持，发挥好碳减排支持工具的示范引领作用，不断完善绿色金融标准体系，稳步推进绿色金融产品和市场高质量发展，提升绿色金融服务质效和可持续性。 三、普惠金融雪中送炭、服务民生，构建多层次、广覆盖、可持续的普惠金融体系 习近平总书记就发展普惠金融多次作出部署，要求“始终坚持以人民为中心的发展思想，推进普惠金融高质量发展”。小微企业是发展的生力军、就业的主渠道，“三农”是经济社会发展的“压舱石”，民生领域是促进共同富裕的关键一环。发展普惠金融，让社会不同群体都平等享受基础金融服务，是金融工作政治性、人民性的重要体现，也是金融助力实现共同富裕的重要路径。 近年来，中国人民银行多措并举，持续加强民营小微、乡村振兴、民生等领域金融服务工作。牵头印发金融支持民营经济“25条举措”、《关于金融支持全面推进乡村振兴 加快建设农业强国的指导意见》等文件，用好用足支农支小再贷款，延续实施普惠小微贷款支持工具，持续开展中小微企业金融服务能力提升工程，调整优化创业担保贷款政策、助学贷款政策，提升普惠领域金融服务可得性和便利性，相关贷款实现“量增、面扩、价降”。截至2024年3月末，普惠小微贷款、涉农贷款、助学贷款分别同比增长20.3%、13.5%、22.5%，高于各项贷款增速；普惠小微授信户数超过6000万户，已覆盖三分之一的经营主体；2024年3月新发放普惠小微贷款加权平均利率4.36%，处于历史较低水平。下一步，中国人民银行将统筹兼顾增量扩面和商业可持续，落实落细相关政策，优化普惠重点领域产品和服务供给，健全多层次普惠金融机构组织体系，加快构建激励相容的普惠金融发展长效机制。 四、养老金融健全体系、增进福祉，助力积极应对人口老龄化国家战略实施 我国人口总量庞大，近年来人口老龄化程度加深。有效应对人口老龄化，事关国家发展全局，事关亿万百姓福祉。习近平总书记在中央金融工作会议上强调，要“加大对健康产业、养老产业、银发经济的财税金融政策支持，有针对性地丰富养老金融产品供给，积极发展第三支柱养老保险，更好满足日益多元化的养老金融需求”。近年来，中国人民银行多措并举加大金融对养老领域和银发经济的支持力度，牵头出台《关于金融支持养老服务业加快发展的指导意见》，推动普惠养老专项再贷款试点全面扩围，引导金融机构积极开展养老理财和特定养老储蓄试点工作，推动银行网点和线上服务亲老适老化改造，针对老年人等群体支付习惯提升支付便利化水平，相关工作取得成效。 下一步，中国人民银行将完善养老金融相关政策、业务、产品体系，推动多层次、多支柱养老保险体系建设，用好用足普惠养老专项再贷款工具，提升养老金融供求适配性和养老产业发展的资金供给水平，实现中国特色金融和养老事业高质量发展良性循环。 五、数字金融把握机遇、重视安全，构建与支撑金融强国建设和数字经济发展相适应的数字金融服务体系 习近平总书记指出“当今时代，数字技术、数字经济是世界科技革命和产业变革的先机，是新一轮国际竞争重点领域”。中央金融工作会议把数字金融提高到国家发展战略的新高度，作出明确部署。金融是数据密集型行业，数字技术历来是金融业发展的重要推动力。顺应数字经济时代变革，借助大数据、人工智能、云计算等数字技术，加快金融业数字化转型，有助于推动金融机构和金融市场提升服务效率，降低运行成本，增强服务实体经济和防范金融风险的能力。 近年来，中国人民银行加强数字金融顶层制度设计，实施金融数字化转型提升工程，深化实施金融科技创新监管工具，扎实推进数字人民币试点，实施金融科技赋能乡村振兴示范工程，有力推动了数字金融发展。下一步，中国人民银行将统筹发展和安全，发挥数据要素和数字技术双轮驱动作用，系统推进金融数字化转型，加强数字技术在科技金融、普惠金融、绿色金融、养老金融的赋能运用，稳妥推进数字人民币研发和应用，完善数字金融治理体系，提升金融服务的便利性和竞争力，助力金融强国建设和巩固拓展数字经济优势。 中国人民银行将与相关部门密切协作，全力做好“五篇大文章”，以高质量金融服务推动经济高质量发展，为奋力实现中国式现代化宏伟目标提供坚实有力的金融支撑。 法律声明 | 联系我们 | 设为首页 | 加入收藏 | 网站地图 京ICP备05073439号 网站标识码：bm25000001 京公网安备 11010202000016号 网站主办单位：中国人民银行办公厅　最佳分辨率：1024*768\\\"}\",\"summaryAnalysis\":\"{\\\"contentSummary\\\":\\\"文章系统阐释中央金融工作会议部署的‘五篇大文章’——科技金融、绿色金融、普惠金融、养老金融、数字金融，强调以深化金融供给侧结构性改革为主线，分类施策、协同推进。中国人民银行围绕五大领域已出台多项政策工具并取得显著成效（如养老专项再贷款扩围、绿色贷款增速35.1%、普惠小微授信超6000万户等），下一步将强化政策适配性、工具丰富性与服务可持续性，全面支撑中国式现代化和金融强国建设。\\\",\\\"viralValue\\\"', 0, '0:0:0:0:0:0:0:1', NULL, 'Mozilla/5.0 (iPhone; CPU iPhone OS 18_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.5 Mobile/15E148 Safari/604.1', 'mobile', 'macOS', 'Safari', 1, NULL, 26934, '2026-08-21 15:00:48', '2026-08-21 15:00:48', 'system', 'system', 0, NULL);
INSERT IGNORE INTO `system_log_agent` VALUES (686, '49d6634a0a114bba845aab365bbc533e', 'agent', 'AG60785666', 'agent01', '文章转写', '选择方案', NULL, NULL, NULL, NULL, '/agent-api/tools/article-rewrite/6/plan/select', 'POST', '{\"id\":6,\"dto\":{\"planIds\":[\"plan_c\"]}}', '{\"code\":0,\"message\":\"success\",\"data\":{\"id\":6,\"toolCode\":\"TL90008\",\"agentCode\":\"AG60785666\",\"channelCode\":\"CH00001\",\"status\":\"SUMMARY_DONE\",\"contentFetch\":\"{\\\"fetchTime\\\": \\\"2026-08-21T14:52:27.8045561\\\", \\\"sourceUrl\\\": \\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\", \\\"sourceType\\\": \\\"url\\\", \\\"fetchStatus\\\": \\\"success\\\", \\\"originalTitle\\\": \\\"扎实做好“五篇大文章” 推动金融高质量发展\\\", \\\"originalSource\\\": \\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\", \\\"originalContent\\\": \\\"扎实做好“五篇大文章” 推动金融高质量发展 （信贷市场司党支部） “为了提供高质量金融服务，金融系统要着力做好科技金融、绿色金融、普惠金融、养老金融、数字金融五篇大文章”。在中央金融工作会议上，习近平总书记对做好“五篇大文章”作出重要部署，擘画了以金融高质量发展助力国家重大战略实施和强国建设的宏伟蓝图，指明了金融支持经济高质量发展的发力点和经济金融结构优化的基本方向，是新时代新征程金融服务实体经济高质量发展的根本遵循和行动指南。“五篇大文章”各领域情况不同，金融服务方向各有侧重，需要坚持需求导向和问题导向，以深化金融供给侧结构性改革为主线，加强金融政策与产业政策协同配合，分类施策、系统推进，不断增强金融支持的力度、可持续性和专业化水平。 一、科技金融迎难而上、聚焦重点，加大对实现科技自立自强和科技强国建设的金融支持力度 习近平总书记多次强调，要“坚持创新在我国现代化建设全局中的核心地位，坚持把科技自立自强作为国家发展的战略支撑”“加快发展新质生产力”。金融与科技、产业形成良性循环，是推动科技创新和产业创新的重要力量。科技创新复杂多元，不同科创主体和活动、科技型企业成长生命周期不同阶段，金融需求差异较大，需要统筹运用好股权、债权、保险等手段为科技型企业提供全链条、全生命周期金融服务。 近年来，中国人民银行持续加强科技金融服务工作，牵头制定《加大力度支持科技型企业融资行动方案》，设立支持科技创新的结构性货币政策工具，稳妥推动科创金融改革试验区建设，持续提升金融服务科技创新的能力和水平。截至2024年3月末，高技术制造业中长期贷款、科技型中小企业贷款、“专精特新”企业贷款分别同比增长27.3%、20.4%、17.9%，明显高于各项贷款增速；科技型中小企业获贷率达到46.5%，较2017年末提升2倍；科创票据累计发行达5600亿元。下一步，中国人民银行将深入落实加大力度支持科技型企业融资行动方案，聚焦国家重大科技任务、科技型中小企业等重点领域及科技要素密集地区，完善金融支持政策体系和配套机制，丰富金融支持工具，全面提升金融机构和金融市场服务科技创新能力，建成与高水平科技自立自强目标高度适配的金融服务体系。 二、绿色金融乘势而上、先立后破，为推动全社会绿色发展和服务美丽中国建设提供高质量金融供给 党的十八大以来，以习近平同志为核心的党中央高度重视生态文明建设，将发展绿色金融作为推动实现碳达峰碳中和、建设美丽中国的重要举措，多次作出重要部署。推动全社会绿色低碳发展涉及行业多、投资周期长、资金需求大，需要充分发挥绿色金融的资源优化配置作用。绿色金融也提供了新的业务增长点，有利于金融机构有序调整资产配置，助力实现金融高质量发展。 中国人民银行始终将发展绿色金融作为重点工作，持续强化顶层设计和政策引领。截至2024年3月末，绿色贷款余额33.8万亿元，同比增长35.1%，连续三年保持30%以上增速；绿色债券累计发行超过3.6万亿元，余额超过1.9万亿元，市场规模位居世界前列，为保障国家能源安全、助力碳达峰碳中和提供有力支持。2024年4月，中国人民银行牵头出台《关于进一步强化金融支持绿色低碳发展的指导意见》，创设碳减排支持工具，创新碳中和债、可持续发展挂钩债券等产品，开展绿色金融国际合作交流，进一步推动绿色信贷、绿色债券等绿色融资较快增长。下一步，中国人民银行将统筹好对绿色发展和低碳转型的支持，发挥好碳减排支持工具的示范引领作用，不断完善绿色金融标准体系，稳步推进绿色金融产品和市场高质量发展，提升绿色金融服务质效和可持续性。 三、普惠金融雪中送炭、服务民生，构建多层次、广覆盖、可持续的普惠金融体系 习近平总书记就发展普惠金融多次作出部署，要求“始终坚持以人民为中心的发展思想，推进普惠金融高质量发展”。小微企业是发展的生力军、就业的主渠道，“三农”是经济社会发展的“压舱石”，民生领域是促进共同富裕的关键一环。发展普惠金融，让社会不同群体都平等享受基础金融服务，是金融工作政治性、人民性的重要体现，也是金融助力实现共同富裕的重要路径。 近年来，中国人民银行多措并举，持续加强民营小微、乡村振兴、民生等领域金融服务工作。牵头印发金融支持民营经济“25条举措”、《关于金融支持全面推进乡村振兴 加快建设农业强国的指导意见》等文件，用好用足支农支小再贷款，延续实施普惠小微贷款支持工具，持续开展中小微企业金融服务能力提升工程，调整优化创业担保贷款政策、助学贷款政策，提升普惠领域金融服务可得性和便利性，相关贷款实现“量增、面扩、价降”。截至2024年3月末，普惠小微贷款、涉农贷款、助学贷款分别同比增长20.3%、13.5%、22.5%，高于各项贷款增速；普惠小微授信户数超过6000万户，已覆盖三分之一的经营主体；2024年3月新发放普惠小微贷款加权平均利率4.36%，处于历史较低水平。下一步，中国人民银行将统筹兼顾增量扩面和商业可持续，落实落细相关政策，优化普惠重点领域产品和服务供给，健全多层次普惠金融机构组织体系，加快构建激励相容的普惠金融发展长效机制。 四、养老金融健全体系、增进福祉，助力积极应对人口老龄化国家战略实施 我国人口总量庞大，近年来人口老龄化程度加深。有效应对人口老龄化，事关国家发展全局，事关亿万百姓福祉。习近平总书记在中央金融工作会议上强调，要“加大对健康产业、养老产业、银发经济的财税金融政策支持，有针对性地丰富养老金融产品供给，积极发展第三支柱养老保险，更好满足日益多元化的养老金融需求”。近年来，中国人民银行多措并举加大金融对养老领域和银发经济的支持力度，牵头出台《关于金融支持养老服务业加快发展的指导意见》，推动普惠养老专项再贷款试点全面扩围，引导金融机构积极开展养老理财和特定养老储蓄试点工作，推动银行网点和线上服务亲老适老化改造，针对老年人等群体支付习惯提升支付便利化水平，相关工作取得成效。 下一步，中国人民银行将完善养老金融相关政策、业务、产品体系，推动多层次、多支柱养老保险体系建设，用好用足普惠养老专项再贷款工具，提升养老金融供求适配性和养老产业发展的资金供给水平，实现中国特色金融和养老事业高质量发展良性循环。 五、数字金融把握机遇、重视安全，构建与支撑金融强国建设和数字经济发展相适应的数字金融服务体系 习近平总书记指出“当今时代，数字技术、数字经济是世界科技革命和产业变革的先机，是新一轮国际竞争重点领域”。中央金融工作会议把数字金融提高到国家发展战略的新高度，作出明确部署。金融是数据密集型行业，数字技术历来是金融业发展的重要推动力。顺应数字经济时代变革，借助大数据、人工智能、云计算等数字技术，加快金融业数字化转型，有助于推动金融机构和金融市场提升服务效率，降低运行成本，增强服务实体经济和防范金融风险的能力。 近年来，中国人民银行加强数字金融顶层制度设计，实施金融数字化转型提升工程，深化实施金融科技创新监管工具，扎实推进数字人民币试点，实施金融科技赋能乡村振兴示范工程，有力推动了数字金融发展。下一步，中国人民银行将统筹发展和安全，发挥数据要素和数字技术双轮驱动作用，系统推进金融数字化转型，加强数字技术在科技金融、普惠金融、绿色金融、养老金融的赋能运用，稳妥推进数字人民币研发和应用，完善数字金融治理体系，提升金融服务的便利性和竞争力，助力金融强国建设和巩固拓展数字经济优势。 中国人民银行将与相关部门密切协作，全力做好“五篇大文章”，以高质量金融服务推动经济高质量发展，为奋力实现中国式现代化宏伟目标提供坚实有力的金融支撑。 法律声明 | 联系我们 | 设为首页 | 加入收藏 | 网站地图 京ICP备05073439号 网站标识码：bm25000001 京公网安备 11010202000016号 网站主办单位：中国人民银行办公厅　最佳分辨率：1024*768\\\"}\",\"summaryAnalysis\":\"{\\\"relevance\\\":{\\\"level\\\":\\\"strong\\\",\\\"detail\\\":\\\"养老金融单列成章，明确要求‘丰富养老金融产品供给’‘积极发展第三支柱养老保险’‘推动养老理财和特定养老储蓄试点’‘适老化网点与支付改造’，直接关联保险机构的产品设计（如税延型/个人养老金保险）、渠道服务（银保协同、社区养老金融驿站）、精算定价（长寿风险建模）及监管合规（养老金融标准体系建设）；同时普惠金融与养老结合（如农村留守老人金融服务）、数字金融赋能（适', 0, '0:0:0:0:0:0:0:1', NULL, 'Mozilla/5.0 (iPhone; CPU iPhone OS 18_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.5 Mobile/15E148 Safari/604.1', 'mobile', 'macOS', 'Safari', 1, NULL, 68, '2026-08-21 15:00:59', '2026-08-21 15:00:59', 'system', 'system', 0, NULL);
INSERT IGNORE INTO `system_log_agent` VALUES (687, '0723d7466bbb4279a7845a3cce490240', 'agent', 'AG60785666', 'agent01', '文章转写', '执行转写', NULL, NULL, NULL, NULL, '/agent-api/tools/article-rewrite/6/rewrite', 'POST', '{\"id\":6}', '{\"code\":0,\"message\":\"success\",\"data\":{\"id\":6,\"toolCode\":\"TL90008\",\"agentCode\":\"AG60785666\",\"channelCode\":\"CH00001\",\"status\":\"REWRITTEN\",\"contentFetch\":\"{\\\"fetchTime\\\": \\\"2026-08-21T14:52:27.8045561\\\", \\\"sourceUrl\\\": \\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\", \\\"sourceType\\\": \\\"url\\\", \\\"fetchStatus\\\": \\\"success\\\", \\\"originalTitle\\\": \\\"扎实做好“五篇大文章” 推动金融高质量发展\\\", \\\"originalSource\\\": \\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\", \\\"originalContent\\\": \\\"扎实做好“五篇大文章” 推动金融高质量发展 （信贷市场司党支部） “为了提供高质量金融服务，金融系统要着力做好科技金融、绿色金融、普惠金融、养老金融、数字金融五篇大文章”。在中央金融工作会议上，习近平总书记对做好“五篇大文章”作出重要部署，擘画了以金融高质量发展助力国家重大战略实施和强国建设的宏伟蓝图，指明了金融支持经济高质量发展的发力点和经济金融结构优化的基本方向，是新时代新征程金融服务实体经济高质量发展的根本遵循和行动指南。“五篇大文章”各领域情况不同，金融服务方向各有侧重，需要坚持需求导向和问题导向，以深化金融供给侧结构性改革为主线，加强金融政策与产业政策协同配合，分类施策、系统推进，不断增强金融支持的力度、可持续性和专业化水平。 一、科技金融迎难而上、聚焦重点，加大对实现科技自立自强和科技强国建设的金融支持力度 习近平总书记多次强调，要“坚持创新在我国现代化建设全局中的核心地位，坚持把科技自立自强作为国家发展的战略支撑”“加快发展新质生产力”。金融与科技、产业形成良性循环，是推动科技创新和产业创新的重要力量。科技创新复杂多元，不同科创主体和活动、科技型企业成长生命周期不同阶段，金融需求差异较大，需要统筹运用好股权、债权、保险等手段为科技型企业提供全链条、全生命周期金融服务。 近年来，中国人民银行持续加强科技金融服务工作，牵头制定《加大力度支持科技型企业融资行动方案》，设立支持科技创新的结构性货币政策工具，稳妥推动科创金融改革试验区建设，持续提升金融服务科技创新的能力和水平。截至2024年3月末，高技术制造业中长期贷款、科技型中小企业贷款、“专精特新”企业贷款分别同比增长27.3%、20.4%、17.9%，明显高于各项贷款增速；科技型中小企业获贷率达到46.5%，较2017年末提升2倍；科创票据累计发行达5600亿元。下一步，中国人民银行将深入落实加大力度支持科技型企业融资行动方案，聚焦国家重大科技任务、科技型中小企业等重点领域及科技要素密集地区，完善金融支持政策体系和配套机制，丰富金融支持工具，全面提升金融机构和金融市场服务科技创新能力，建成与高水平科技自立自强目标高度适配的金融服务体系。 二、绿色金融乘势而上、先立后破，为推动全社会绿色发展和服务美丽中国建设提供高质量金融供给 党的十八大以来，以习近平同志为核心的党中央高度重视生态文明建设，将发展绿色金融作为推动实现碳达峰碳中和、建设美丽中国的重要举措，多次作出重要部署。推动全社会绿色低碳发展涉及行业多、投资周期长、资金需求大，需要充分发挥绿色金融的资源优化配置作用。绿色金融也提供了新的业务增长点，有利于金融机构有序调整资产配置，助力实现金融高质量发展。 中国人民银行始终将发展绿色金融作为重点工作，持续强化顶层设计和政策引领。截至2024年3月末，绿色贷款余额33.8万亿元，同比增长35.1%，连续三年保持30%以上增速；绿色债券累计发行超过3.6万亿元，余额超过1.9万亿元，市场规模位居世界前列，为保障国家能源安全、助力碳达峰碳中和提供有力支持。2024年4月，中国人民银行牵头出台《关于进一步强化金融支持绿色低碳发展的指导意见》，创设碳减排支持工具，创新碳中和债、可持续发展挂钩债券等产品，开展绿色金融国际合作交流，进一步推动绿色信贷、绿色债券等绿色融资较快增长。下一步，中国人民银行将统筹好对绿色发展和低碳转型的支持，发挥好碳减排支持工具的示范引领作用，不断完善绿色金融标准体系，稳步推进绿色金融产品和市场高质量发展，提升绿色金融服务质效和可持续性。 三、普惠金融雪中送炭、服务民生，构建多层次、广覆盖、可持续的普惠金融体系 习近平总书记就发展普惠金融多次作出部署，要求“始终坚持以人民为中心的发展思想，推进普惠金融高质量发展”。小微企业是发展的生力军、就业的主渠道，“三农”是经济社会发展的“压舱石”，民生领域是促进共同富裕的关键一环。发展普惠金融，让社会不同群体都平等享受基础金融服务，是金融工作政治性、人民性的重要体现，也是金融助力实现共同富裕的重要路径。 近年来，中国人民银行多措并举，持续加强民营小微、乡村振兴、民生等领域金融服务工作。牵头印发金融支持民营经济“25条举措”、《关于金融支持全面推进乡村振兴 加快建设农业强国的指导意见》等文件，用好用足支农支小再贷款，延续实施普惠小微贷款支持工具，持续开展中小微企业金融服务能力提升工程，调整优化创业担保贷款政策、助学贷款政策，提升普惠领域金融服务可得性和便利性，相关贷款实现“量增、面扩、价降”。截至2024年3月末，普惠小微贷款、涉农贷款、助学贷款分别同比增长20.3%、13.5%、22.5%，高于各项贷款增速；普惠小微授信户数超过6000万户，已覆盖三分之一的经营主体；2024年3月新发放普惠小微贷款加权平均利率4.36%，处于历史较低水平。下一步，中国人民银行将统筹兼顾增量扩面和商业可持续，落实落细相关政策，优化普惠重点领域产品和服务供给，健全多层次普惠金融机构组织体系，加快构建激励相容的普惠金融发展长效机制。 四、养老金融健全体系、增进福祉，助力积极应对人口老龄化国家战略实施 我国人口总量庞大，近年来人口老龄化程度加深。有效应对人口老龄化，事关国家发展全局，事关亿万百姓福祉。习近平总书记在中央金融工作会议上强调，要“加大对健康产业、养老产业、银发经济的财税金融政策支持，有针对性地丰富养老金融产品供给，积极发展第三支柱养老保险，更好满足日益多元化的养老金融需求”。近年来，中国人民银行多措并举加大金融对养老领域和银发经济的支持力度，牵头出台《关于金融支持养老服务业加快发展的指导意见》，推动普惠养老专项再贷款试点全面扩围，引导金融机构积极开展养老理财和特定养老储蓄试点工作，推动银行网点和线上服务亲老适老化改造，针对老年人等群体支付习惯提升支付便利化水平，相关工作取得成效。 下一步，中国人民银行将完善养老金融相关政策、业务、产品体系，推动多层次、多支柱养老保险体系建设，用好用足普惠养老专项再贷款工具，提升养老金融供求适配性和养老产业发展的资金供给水平，实现中国特色金融和养老事业高质量发展良性循环。 五、数字金融把握机遇、重视安全，构建与支撑金融强国建设和数字经济发展相适应的数字金融服务体系 习近平总书记指出“当今时代，数字技术、数字经济是世界科技革命和产业变革的先机，是新一轮国际竞争重点领域”。中央金融工作会议把数字金融提高到国家发展战略的新高度，作出明确部署。金融是数据密集型行业，数字技术历来是金融业发展的重要推动力。顺应数字经济时代变革，借助大数据、人工智能、云计算等数字技术，加快金融业数字化转型，有助于推动金融机构和金融市场提升服务效率，降低运行成本，增强服务实体经济和防范金融风险的能力。 近年来，中国人民银行加强数字金融顶层制度设计，实施金融数字化转型提升工程，深化实施金融科技创新监管工具，扎实推进数字人民币试点，实施金融科技赋能乡村振兴示范工程，有力推动了数字金融发展。下一步，中国人民银行将统筹发展和安全，发挥数据要素和数字技术双轮驱动作用，系统推进金融数字化转型，加强数字技术在科技金融、普惠金融、绿色金融、养老金融的赋能运用，稳妥推进数字人民币研发和应用，完善数字金融治理体系，提升金融服务的便利性和竞争力，助力金融强国建设和巩固拓展数字经济优势。 中国人民银行将与相关部门密切协作，全力做好“五篇大文章”，以高质量金融服务推动经济高质量发展，为奋力实现中国式现代化宏伟目标提供坚实有力的金融支撑。 法律声明 | 联系我们 | 设为首页 | 加入收藏 | 网站地图 京ICP备05073439号 网站标识码：bm25000001 京公网安备 11010202000016号 网站主办单位：中国人民银行办公厅　最佳分辨率：1024*768\\\"}\",\"summaryAnalysis\":\"{\\\"relevance\\\": {\\\"level\\\": \\\"strong\\\", \\\"detail\\\": \\\"养老金融单列成章，明确要求‘丰富养老金融产品供给’‘积极发展第三支柱养老保险’‘推动养老理财和特定养老储蓄试点’‘适老化网点与支付改造’，直接关联保险机构的产品设计（如税延型/个人养老金保险）、渠道服务（银保协同、社区养老金融驿站）、精算定价（长寿风险建模）及监管合规（养老金融标准体系建设）；同时普惠金融与养老结合（如农村留守老人金融服务）、数字金融赋能（', 0, '0:0:0:0:0:0:0:1', NULL, 'Mozilla/5.0 (iPhone; CPU iPhone OS 18_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.5 Mobile/15E148 Safari/604.1', 'mobile', 'macOS', 'Safari', 1, NULL, 11177, '2026-08-21 15:01:10', '2026-08-21 15:01:10', 'system', 'system', 0, NULL);
INSERT IGNORE INTO `system_log_agent` VALUES (688, '39c9cc7b4346475cab6d067c1b10fb67', 'agent', 'AG60785666', 'agent01', '文章转写', '重新转写', NULL, NULL, NULL, NULL, '/agent-api/tools/article-rewrite/6/rewrite/regenerate', 'POST', '{\"id\":6}', '{\"code\":0,\"message\":\"success\",\"data\":{\"id\":6,\"toolCode\":\"TL90008\",\"agentCode\":\"AG60785666\",\"channelCode\":\"CH00001\",\"status\":\"REWRITTEN\",\"contentFetch\":\"{\\\"fetchTime\\\": \\\"2026-08-21T14:52:27.8045561\\\", \\\"sourceUrl\\\": \\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\", \\\"sourceType\\\": \\\"url\\\", \\\"fetchStatus\\\": \\\"success\\\", \\\"originalTitle\\\": \\\"扎实做好“五篇大文章” 推动金融高质量发展\\\", \\\"originalSource\\\": \\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\", \\\"originalContent\\\": \\\"扎实做好“五篇大文章” 推动金融高质量发展 （信贷市场司党支部） “为了提供高质量金融服务，金融系统要着力做好科技金融、绿色金融、普惠金融、养老金融、数字金融五篇大文章”。在中央金融工作会议上，习近平总书记对做好“五篇大文章”作出重要部署，擘画了以金融高质量发展助力国家重大战略实施和强国建设的宏伟蓝图，指明了金融支持经济高质量发展的发力点和经济金融结构优化的基本方向，是新时代新征程金融服务实体经济高质量发展的根本遵循和行动指南。“五篇大文章”各领域情况不同，金融服务方向各有侧重，需要坚持需求导向和问题导向，以深化金融供给侧结构性改革为主线，加强金融政策与产业政策协同配合，分类施策、系统推进，不断增强金融支持的力度、可持续性和专业化水平。 一、科技金融迎难而上、聚焦重点，加大对实现科技自立自强和科技强国建设的金融支持力度 习近平总书记多次强调，要“坚持创新在我国现代化建设全局中的核心地位，坚持把科技自立自强作为国家发展的战略支撑”“加快发展新质生产力”。金融与科技、产业形成良性循环，是推动科技创新和产业创新的重要力量。科技创新复杂多元，不同科创主体和活动、科技型企业成长生命周期不同阶段，金融需求差异较大，需要统筹运用好股权、债权、保险等手段为科技型企业提供全链条、全生命周期金融服务。 近年来，中国人民银行持续加强科技金融服务工作，牵头制定《加大力度支持科技型企业融资行动方案》，设立支持科技创新的结构性货币政策工具，稳妥推动科创金融改革试验区建设，持续提升金融服务科技创新的能力和水平。截至2024年3月末，高技术制造业中长期贷款、科技型中小企业贷款、“专精特新”企业贷款分别同比增长27.3%、20.4%、17.9%，明显高于各项贷款增速；科技型中小企业获贷率达到46.5%，较2017年末提升2倍；科创票据累计发行达5600亿元。下一步，中国人民银行将深入落实加大力度支持科技型企业融资行动方案，聚焦国家重大科技任务、科技型中小企业等重点领域及科技要素密集地区，完善金融支持政策体系和配套机制，丰富金融支持工具，全面提升金融机构和金融市场服务科技创新能力，建成与高水平科技自立自强目标高度适配的金融服务体系。 二、绿色金融乘势而上、先立后破，为推动全社会绿色发展和服务美丽中国建设提供高质量金融供给 党的十八大以来，以习近平同志为核心的党中央高度重视生态文明建设，将发展绿色金融作为推动实现碳达峰碳中和、建设美丽中国的重要举措，多次作出重要部署。推动全社会绿色低碳发展涉及行业多、投资周期长、资金需求大，需要充分发挥绿色金融的资源优化配置作用。绿色金融也提供了新的业务增长点，有利于金融机构有序调整资产配置，助力实现金融高质量发展。 中国人民银行始终将发展绿色金融作为重点工作，持续强化顶层设计和政策引领。截至2024年3月末，绿色贷款余额33.8万亿元，同比增长35.1%，连续三年保持30%以上增速；绿色债券累计发行超过3.6万亿元，余额超过1.9万亿元，市场规模位居世界前列，为保障国家能源安全、助力碳达峰碳中和提供有力支持。2024年4月，中国人民银行牵头出台《关于进一步强化金融支持绿色低碳发展的指导意见》，创设碳减排支持工具，创新碳中和债、可持续发展挂钩债券等产品，开展绿色金融国际合作交流，进一步推动绿色信贷、绿色债券等绿色融资较快增长。下一步，中国人民银行将统筹好对绿色发展和低碳转型的支持，发挥好碳减排支持工具的示范引领作用，不断完善绿色金融标准体系，稳步推进绿色金融产品和市场高质量发展，提升绿色金融服务质效和可持续性。 三、普惠金融雪中送炭、服务民生，构建多层次、广覆盖、可持续的普惠金融体系 习近平总书记就发展普惠金融多次作出部署，要求“始终坚持以人民为中心的发展思想，推进普惠金融高质量发展”。小微企业是发展的生力军、就业的主渠道，“三农”是经济社会发展的“压舱石”，民生领域是促进共同富裕的关键一环。发展普惠金融，让社会不同群体都平等享受基础金融服务，是金融工作政治性、人民性的重要体现，也是金融助力实现共同富裕的重要路径。 近年来，中国人民银行多措并举，持续加强民营小微、乡村振兴、民生等领域金融服务工作。牵头印发金融支持民营经济“25条举措”、《关于金融支持全面推进乡村振兴 加快建设农业强国的指导意见》等文件，用好用足支农支小再贷款，延续实施普惠小微贷款支持工具，持续开展中小微企业金融服务能力提升工程，调整优化创业担保贷款政策、助学贷款政策，提升普惠领域金融服务可得性和便利性，相关贷款实现“量增、面扩、价降”。截至2024年3月末，普惠小微贷款、涉农贷款、助学贷款分别同比增长20.3%、13.5%、22.5%，高于各项贷款增速；普惠小微授信户数超过6000万户，已覆盖三分之一的经营主体；2024年3月新发放普惠小微贷款加权平均利率4.36%，处于历史较低水平。下一步，中国人民银行将统筹兼顾增量扩面和商业可持续，落实落细相关政策，优化普惠重点领域产品和服务供给，健全多层次普惠金融机构组织体系，加快构建激励相容的普惠金融发展长效机制。 四、养老金融健全体系、增进福祉，助力积极应对人口老龄化国家战略实施 我国人口总量庞大，近年来人口老龄化程度加深。有效应对人口老龄化，事关国家发展全局，事关亿万百姓福祉。习近平总书记在中央金融工作会议上强调，要“加大对健康产业、养老产业、银发经济的财税金融政策支持，有针对性地丰富养老金融产品供给，积极发展第三支柱养老保险，更好满足日益多元化的养老金融需求”。近年来，中国人民银行多措并举加大金融对养老领域和银发经济的支持力度，牵头出台《关于金融支持养老服务业加快发展的指导意见》，推动普惠养老专项再贷款试点全面扩围，引导金融机构积极开展养老理财和特定养老储蓄试点工作，推动银行网点和线上服务亲老适老化改造，针对老年人等群体支付习惯提升支付便利化水平，相关工作取得成效。 下一步，中国人民银行将完善养老金融相关政策、业务、产品体系，推动多层次、多支柱养老保险体系建设，用好用足普惠养老专项再贷款工具，提升养老金融供求适配性和养老产业发展的资金供给水平，实现中国特色金融和养老事业高质量发展良性循环。 五、数字金融把握机遇、重视安全，构建与支撑金融强国建设和数字经济发展相适应的数字金融服务体系 习近平总书记指出“当今时代，数字技术、数字经济是世界科技革命和产业变革的先机，是新一轮国际竞争重点领域”。中央金融工作会议把数字金融提高到国家发展战略的新高度，作出明确部署。金融是数据密集型行业，数字技术历来是金融业发展的重要推动力。顺应数字经济时代变革，借助大数据、人工智能、云计算等数字技术，加快金融业数字化转型，有助于推动金融机构和金融市场提升服务效率，降低运行成本，增强服务实体经济和防范金融风险的能力。 近年来，中国人民银行加强数字金融顶层制度设计，实施金融数字化转型提升工程，深化实施金融科技创新监管工具，扎实推进数字人民币试点，实施金融科技赋能乡村振兴示范工程，有力推动了数字金融发展。下一步，中国人民银行将统筹发展和安全，发挥数据要素和数字技术双轮驱动作用，系统推进金融数字化转型，加强数字技术在科技金融、普惠金融、绿色金融、养老金融的赋能运用，稳妥推进数字人民币研发和应用，完善数字金融治理体系，提升金融服务的便利性和竞争力，助力金融强国建设和巩固拓展数字经济优势。 中国人民银行将与相关部门密切协作，全力做好“五篇大文章”，以高质量金融服务推动经济高质量发展，为奋力实现中国式现代化宏伟目标提供坚实有力的金融支撑。 法律声明 | 联系我们 | 设为首页 | 加入收藏 | 网站地图 京ICP备05073439号 网站标识码：bm25000001 京公网安备 11010202000016号 网站主办单位：中国人民银行办公厅　最佳分辨率：1024*768\\\"}\",\"summaryAnalysis\":\"{\\\"relevance\\\": {\\\"level\\\": \\\"strong\\\", \\\"detail\\\": \\\"养老金融单列成章，明确要求‘丰富养老金融产品供给’‘积极发展第三支柱养老保险’‘推动养老理财和特定养老储蓄试点’‘适老化网点与支付改造’，直接关联保险机构的产品设计（如税延型/个人养老金保险）、渠道服务（银保协同、社区养老金融驿站）、精算定价（长寿风险建模）及监管合规（养老金融标准体系建设）；同时普惠金融与养老结合（如农村留守老人金融服务）、数字金融赋能（', 0, '0:0:0:0:0:0:0:1', NULL, 'Mozilla/5.0 (iPhone; CPU iPhone OS 18_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.5 Mobile/15E148 Safari/604.1', 'mobile', 'macOS', 'Safari', 1, NULL, 11981, '2026-08-21 15:01:38', '2026-08-21 15:01:38', 'system', 'system', 0, NULL);
INSERT IGNORE INTO `system_log_agent` VALUES (689, 'e1c7b46f4e3a4d2dbe766c78ebc77683', 'agent', 'AG60785666', 'agent01', '文章转写', '重新转写', NULL, NULL, NULL, NULL, '/agent-api/tools/article-rewrite/6/rewrite/regenerate', 'POST', '{\"id\":6}', '{\"code\":0,\"message\":\"success\",\"data\":{\"id\":6,\"toolCode\":\"TL90008\",\"agentCode\":\"AG60785666\",\"channelCode\":\"CH00001\",\"status\":\"REWRITTEN\",\"contentFetch\":\"{\\\"fetchTime\\\": \\\"2026-08-21T14:52:27.8045561\\\", \\\"sourceUrl\\\": \\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\", \\\"sourceType\\\": \\\"url\\\", \\\"fetchStatus\\\": \\\"success\\\", \\\"originalTitle\\\": \\\"扎实做好“五篇大文章” 推动金融高质量发展\\\", \\\"originalSource\\\": \\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\", \\\"originalContent\\\": \\\"扎实做好“五篇大文章” 推动金融高质量发展 （信贷市场司党支部） “为了提供高质量金融服务，金融系统要着力做好科技金融、绿色金融、普惠金融、养老金融、数字金融五篇大文章”。在中央金融工作会议上，习近平总书记对做好“五篇大文章”作出重要部署，擘画了以金融高质量发展助力国家重大战略实施和强国建设的宏伟蓝图，指明了金融支持经济高质量发展的发力点和经济金融结构优化的基本方向，是新时代新征程金融服务实体经济高质量发展的根本遵循和行动指南。“五篇大文章”各领域情况不同，金融服务方向各有侧重，需要坚持需求导向和问题导向，以深化金融供给侧结构性改革为主线，加强金融政策与产业政策协同配合，分类施策、系统推进，不断增强金融支持的力度、可持续性和专业化水平。 一、科技金融迎难而上、聚焦重点，加大对实现科技自立自强和科技强国建设的金融支持力度 习近平总书记多次强调，要“坚持创新在我国现代化建设全局中的核心地位，坚持把科技自立自强作为国家发展的战略支撑”“加快发展新质生产力”。金融与科技、产业形成良性循环，是推动科技创新和产业创新的重要力量。科技创新复杂多元，不同科创主体和活动、科技型企业成长生命周期不同阶段，金融需求差异较大，需要统筹运用好股权、债权、保险等手段为科技型企业提供全链条、全生命周期金融服务。 近年来，中国人民银行持续加强科技金融服务工作，牵头制定《加大力度支持科技型企业融资行动方案》，设立支持科技创新的结构性货币政策工具，稳妥推动科创金融改革试验区建设，持续提升金融服务科技创新的能力和水平。截至2024年3月末，高技术制造业中长期贷款、科技型中小企业贷款、“专精特新”企业贷款分别同比增长27.3%、20.4%、17.9%，明显高于各项贷款增速；科技型中小企业获贷率达到46.5%，较2017年末提升2倍；科创票据累计发行达5600亿元。下一步，中国人民银行将深入落实加大力度支持科技型企业融资行动方案，聚焦国家重大科技任务、科技型中小企业等重点领域及科技要素密集地区，完善金融支持政策体系和配套机制，丰富金融支持工具，全面提升金融机构和金融市场服务科技创新能力，建成与高水平科技自立自强目标高度适配的金融服务体系。 二、绿色金融乘势而上、先立后破，为推动全社会绿色发展和服务美丽中国建设提供高质量金融供给 党的十八大以来，以习近平同志为核心的党中央高度重视生态文明建设，将发展绿色金融作为推动实现碳达峰碳中和、建设美丽中国的重要举措，多次作出重要部署。推动全社会绿色低碳发展涉及行业多、投资周期长、资金需求大，需要充分发挥绿色金融的资源优化配置作用。绿色金融也提供了新的业务增长点，有利于金融机构有序调整资产配置，助力实现金融高质量发展。 中国人民银行始终将发展绿色金融作为重点工作，持续强化顶层设计和政策引领。截至2024年3月末，绿色贷款余额33.8万亿元，同比增长35.1%，连续三年保持30%以上增速；绿色债券累计发行超过3.6万亿元，余额超过1.9万亿元，市场规模位居世界前列，为保障国家能源安全、助力碳达峰碳中和提供有力支持。2024年4月，中国人民银行牵头出台《关于进一步强化金融支持绿色低碳发展的指导意见》，创设碳减排支持工具，创新碳中和债、可持续发展挂钩债券等产品，开展绿色金融国际合作交流，进一步推动绿色信贷、绿色债券等绿色融资较快增长。下一步，中国人民银行将统筹好对绿色发展和低碳转型的支持，发挥好碳减排支持工具的示范引领作用，不断完善绿色金融标准体系，稳步推进绿色金融产品和市场高质量发展，提升绿色金融服务质效和可持续性。 三、普惠金融雪中送炭、服务民生，构建多层次、广覆盖、可持续的普惠金融体系 习近平总书记就发展普惠金融多次作出部署，要求“始终坚持以人民为中心的发展思想，推进普惠金融高质量发展”。小微企业是发展的生力军、就业的主渠道，“三农”是经济社会发展的“压舱石”，民生领域是促进共同富裕的关键一环。发展普惠金融，让社会不同群体都平等享受基础金融服务，是金融工作政治性、人民性的重要体现，也是金融助力实现共同富裕的重要路径。 近年来，中国人民银行多措并举，持续加强民营小微、乡村振兴、民生等领域金融服务工作。牵头印发金融支持民营经济“25条举措”、《关于金融支持全面推进乡村振兴 加快建设农业强国的指导意见》等文件，用好用足支农支小再贷款，延续实施普惠小微贷款支持工具，持续开展中小微企业金融服务能力提升工程，调整优化创业担保贷款政策、助学贷款政策，提升普惠领域金融服务可得性和便利性，相关贷款实现“量增、面扩、价降”。截至2024年3月末，普惠小微贷款、涉农贷款、助学贷款分别同比增长20.3%、13.5%、22.5%，高于各项贷款增速；普惠小微授信户数超过6000万户，已覆盖三分之一的经营主体；2024年3月新发放普惠小微贷款加权平均利率4.36%，处于历史较低水平。下一步，中国人民银行将统筹兼顾增量扩面和商业可持续，落实落细相关政策，优化普惠重点领域产品和服务供给，健全多层次普惠金融机构组织体系，加快构建激励相容的普惠金融发展长效机制。 四、养老金融健全体系、增进福祉，助力积极应对人口老龄化国家战略实施 我国人口总量庞大，近年来人口老龄化程度加深。有效应对人口老龄化，事关国家发展全局，事关亿万百姓福祉。习近平总书记在中央金融工作会议上强调，要“加大对健康产业、养老产业、银发经济的财税金融政策支持，有针对性地丰富养老金融产品供给，积极发展第三支柱养老保险，更好满足日益多元化的养老金融需求”。近年来，中国人民银行多措并举加大金融对养老领域和银发经济的支持力度，牵头出台《关于金融支持养老服务业加快发展的指导意见》，推动普惠养老专项再贷款试点全面扩围，引导金融机构积极开展养老理财和特定养老储蓄试点工作，推动银行网点和线上服务亲老适老化改造，针对老年人等群体支付习惯提升支付便利化水平，相关工作取得成效。 下一步，中国人民银行将完善养老金融相关政策、业务、产品体系，推动多层次、多支柱养老保险体系建设，用好用足普惠养老专项再贷款工具，提升养老金融供求适配性和养老产业发展的资金供给水平，实现中国特色金融和养老事业高质量发展良性循环。 五、数字金融把握机遇、重视安全，构建与支撑金融强国建设和数字经济发展相适应的数字金融服务体系 习近平总书记指出“当今时代，数字技术、数字经济是世界科技革命和产业变革的先机，是新一轮国际竞争重点领域”。中央金融工作会议把数字金融提高到国家发展战略的新高度，作出明确部署。金融是数据密集型行业，数字技术历来是金融业发展的重要推动力。顺应数字经济时代变革，借助大数据、人工智能、云计算等数字技术，加快金融业数字化转型，有助于推动金融机构和金融市场提升服务效率，降低运行成本，增强服务实体经济和防范金融风险的能力。 近年来，中国人民银行加强数字金融顶层制度设计，实施金融数字化转型提升工程，深化实施金融科技创新监管工具，扎实推进数字人民币试点，实施金融科技赋能乡村振兴示范工程，有力推动了数字金融发展。下一步，中国人民银行将统筹发展和安全，发挥数据要素和数字技术双轮驱动作用，系统推进金融数字化转型，加强数字技术在科技金融、普惠金融、绿色金融、养老金融的赋能运用，稳妥推进数字人民币研发和应用，完善数字金融治理体系，提升金融服务的便利性和竞争力，助力金融强国建设和巩固拓展数字经济优势。 中国人民银行将与相关部门密切协作，全力做好“五篇大文章”，以高质量金融服务推动经济高质量发展，为奋力实现中国式现代化宏伟目标提供坚实有力的金融支撑。 法律声明 | 联系我们 | 设为首页 | 加入收藏 | 网站地图 京ICP备05073439号 网站标识码：bm25000001 京公网安备 11010202000016号 网站主办单位：中国人民银行办公厅　最佳分辨率：1024*768\\\"}\",\"summaryAnalysis\":\"{\\\"relevance\\\": {\\\"level\\\": \\\"strong\\\", \\\"detail\\\": \\\"养老金融单列成章，明确要求‘丰富养老金融产品供给’‘积极发展第三支柱养老保险’‘推动养老理财和特定养老储蓄试点’‘适老化网点与支付改造’，直接关联保险机构的产品设计（如税延型/个人养老金保险）、渠道服务（银保协同、社区养老金融驿站）、精算定价（长寿风险建模）及监管合规（养老金融标准体系建设）；同时普惠金融与养老结合（如农村留守老人金融服务）、数字金融赋能（', 0, '0:0:0:0:0:0:0:1', NULL, 'Mozilla/5.0 (iPhone; CPU iPhone OS 18_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.5 Mobile/15E148 Safari/604.1', 'mobile', 'macOS', 'Safari', 1, NULL, 12035, '2026-08-21 15:02:13', '2026-08-21 15:02:13', 'system', 'system', 0, NULL);
INSERT IGNORE INTO `system_log_agent` VALUES (690, 'f86489a894a2468b8d1cf127f42399ff', 'agent', 'AG60785666', 'agent01', '文章转写', '执行审核', NULL, NULL, NULL, NULL, '/agent-api/tools/article-rewrite/6/audit', 'POST', '{\"id\":6}', '{\"code\":0,\"message\":\"success\",\"data\":{\"id\":6,\"toolCode\":\"TL90008\",\"agentCode\":\"AG60785666\",\"channelCode\":\"CH00001\",\"status\":\"AUDITED\",\"contentFetch\":\"{\\\"fetchTime\\\": \\\"2026-08-21T14:52:27.8045561\\\", \\\"sourceUrl\\\": \\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\", \\\"sourceType\\\": \\\"url\\\", \\\"fetchStatus\\\": \\\"success\\\", \\\"originalTitle\\\": \\\"扎实做好“五篇大文章” 推动金融高质量发展\\\", \\\"originalSource\\\": \\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\", \\\"originalContent\\\": \\\"扎实做好“五篇大文章” 推动金融高质量发展 （信贷市场司党支部） “为了提供高质量金融服务，金融系统要着力做好科技金融、绿色金融、普惠金融、养老金融、数字金融五篇大文章”。在中央金融工作会议上，习近平总书记对做好“五篇大文章”作出重要部署，擘画了以金融高质量发展助力国家重大战略实施和强国建设的宏伟蓝图，指明了金融支持经济高质量发展的发力点和经济金融结构优化的基本方向，是新时代新征程金融服务实体经济高质量发展的根本遵循和行动指南。“五篇大文章”各领域情况不同，金融服务方向各有侧重，需要坚持需求导向和问题导向，以深化金融供给侧结构性改革为主线，加强金融政策与产业政策协同配合，分类施策、系统推进，不断增强金融支持的力度、可持续性和专业化水平。 一、科技金融迎难而上、聚焦重点，加大对实现科技自立自强和科技强国建设的金融支持力度 习近平总书记多次强调，要“坚持创新在我国现代化建设全局中的核心地位，坚持把科技自立自强作为国家发展的战略支撑”“加快发展新质生产力”。金融与科技、产业形成良性循环，是推动科技创新和产业创新的重要力量。科技创新复杂多元，不同科创主体和活动、科技型企业成长生命周期不同阶段，金融需求差异较大，需要统筹运用好股权、债权、保险等手段为科技型企业提供全链条、全生命周期金融服务。 近年来，中国人民银行持续加强科技金融服务工作，牵头制定《加大力度支持科技型企业融资行动方案》，设立支持科技创新的结构性货币政策工具，稳妥推动科创金融改革试验区建设，持续提升金融服务科技创新的能力和水平。截至2024年3月末，高技术制造业中长期贷款、科技型中小企业贷款、“专精特新”企业贷款分别同比增长27.3%、20.4%、17.9%，明显高于各项贷款增速；科技型中小企业获贷率达到46.5%，较2017年末提升2倍；科创票据累计发行达5600亿元。下一步，中国人民银行将深入落实加大力度支持科技型企业融资行动方案，聚焦国家重大科技任务、科技型中小企业等重点领域及科技要素密集地区，完善金融支持政策体系和配套机制，丰富金融支持工具，全面提升金融机构和金融市场服务科技创新能力，建成与高水平科技自立自强目标高度适配的金融服务体系。 二、绿色金融乘势而上、先立后破，为推动全社会绿色发展和服务美丽中国建设提供高质量金融供给 党的十八大以来，以习近平同志为核心的党中央高度重视生态文明建设，将发展绿色金融作为推动实现碳达峰碳中和、建设美丽中国的重要举措，多次作出重要部署。推动全社会绿色低碳发展涉及行业多、投资周期长、资金需求大，需要充分发挥绿色金融的资源优化配置作用。绿色金融也提供了新的业务增长点，有利于金融机构有序调整资产配置，助力实现金融高质量发展。 中国人民银行始终将发展绿色金融作为重点工作，持续强化顶层设计和政策引领。截至2024年3月末，绿色贷款余额33.8万亿元，同比增长35.1%，连续三年保持30%以上增速；绿色债券累计发行超过3.6万亿元，余额超过1.9万亿元，市场规模位居世界前列，为保障国家能源安全、助力碳达峰碳中和提供有力支持。2024年4月，中国人民银行牵头出台《关于进一步强化金融支持绿色低碳发展的指导意见》，创设碳减排支持工具，创新碳中和债、可持续发展挂钩债券等产品，开展绿色金融国际合作交流，进一步推动绿色信贷、绿色债券等绿色融资较快增长。下一步，中国人民银行将统筹好对绿色发展和低碳转型的支持，发挥好碳减排支持工具的示范引领作用，不断完善绿色金融标准体系，稳步推进绿色金融产品和市场高质量发展，提升绿色金融服务质效和可持续性。 三、普惠金融雪中送炭、服务民生，构建多层次、广覆盖、可持续的普惠金融体系 习近平总书记就发展普惠金融多次作出部署，要求“始终坚持以人民为中心的发展思想，推进普惠金融高质量发展”。小微企业是发展的生力军、就业的主渠道，“三农”是经济社会发展的“压舱石”，民生领域是促进共同富裕的关键一环。发展普惠金融，让社会不同群体都平等享受基础金融服务，是金融工作政治性、人民性的重要体现，也是金融助力实现共同富裕的重要路径。 近年来，中国人民银行多措并举，持续加强民营小微、乡村振兴、民生等领域金融服务工作。牵头印发金融支持民营经济“25条举措”、《关于金融支持全面推进乡村振兴 加快建设农业强国的指导意见》等文件，用好用足支农支小再贷款，延续实施普惠小微贷款支持工具，持续开展中小微企业金融服务能力提升工程，调整优化创业担保贷款政策、助学贷款政策，提升普惠领域金融服务可得性和便利性，相关贷款实现“量增、面扩、价降”。截至2024年3月末，普惠小微贷款、涉农贷款、助学贷款分别同比增长20.3%、13.5%、22.5%，高于各项贷款增速；普惠小微授信户数超过6000万户，已覆盖三分之一的经营主体；2024年3月新发放普惠小微贷款加权平均利率4.36%，处于历史较低水平。下一步，中国人民银行将统筹兼顾增量扩面和商业可持续，落实落细相关政策，优化普惠重点领域产品和服务供给，健全多层次普惠金融机构组织体系，加快构建激励相容的普惠金融发展长效机制。 四、养老金融健全体系、增进福祉，助力积极应对人口老龄化国家战略实施 我国人口总量庞大，近年来人口老龄化程度加深。有效应对人口老龄化，事关国家发展全局，事关亿万百姓福祉。习近平总书记在中央金融工作会议上强调，要“加大对健康产业、养老产业、银发经济的财税金融政策支持，有针对性地丰富养老金融产品供给，积极发展第三支柱养老保险，更好满足日益多元化的养老金融需求”。近年来，中国人民银行多措并举加大金融对养老领域和银发经济的支持力度，牵头出台《关于金融支持养老服务业加快发展的指导意见》，推动普惠养老专项再贷款试点全面扩围，引导金融机构积极开展养老理财和特定养老储蓄试点工作，推动银行网点和线上服务亲老适老化改造，针对老年人等群体支付习惯提升支付便利化水平，相关工作取得成效。 下一步，中国人民银行将完善养老金融相关政策、业务、产品体系，推动多层次、多支柱养老保险体系建设，用好用足普惠养老专项再贷款工具，提升养老金融供求适配性和养老产业发展的资金供给水平，实现中国特色金融和养老事业高质量发展良性循环。 五、数字金融把握机遇、重视安全，构建与支撑金融强国建设和数字经济发展相适应的数字金融服务体系 习近平总书记指出“当今时代，数字技术、数字经济是世界科技革命和产业变革的先机，是新一轮国际竞争重点领域”。中央金融工作会议把数字金融提高到国家发展战略的新高度，作出明确部署。金融是数据密集型行业，数字技术历来是金融业发展的重要推动力。顺应数字经济时代变革，借助大数据、人工智能、云计算等数字技术，加快金融业数字化转型，有助于推动金融机构和金融市场提升服务效率，降低运行成本，增强服务实体经济和防范金融风险的能力。 近年来，中国人民银行加强数字金融顶层制度设计，实施金融数字化转型提升工程，深化实施金融科技创新监管工具，扎实推进数字人民币试点，实施金融科技赋能乡村振兴示范工程，有力推动了数字金融发展。下一步，中国人民银行将统筹发展和安全，发挥数据要素和数字技术双轮驱动作用，系统推进金融数字化转型，加强数字技术在科技金融、普惠金融、绿色金融、养老金融的赋能运用，稳妥推进数字人民币研发和应用，完善数字金融治理体系，提升金融服务的便利性和竞争力，助力金融强国建设和巩固拓展数字经济优势。 中国人民银行将与相关部门密切协作，全力做好“五篇大文章”，以高质量金融服务推动经济高质量发展，为奋力实现中国式现代化宏伟目标提供坚实有力的金融支撑。 法律声明 | 联系我们 | 设为首页 | 加入收藏 | 网站地图 京ICP备05073439号 网站标识码：bm25000001 京公网安备 11010202000016号 网站主办单位：中国人民银行办公厅　最佳分辨率：1024*768\\\"}\",\"summaryAnalysis\":\"{\\\"relevance\\\": {\\\"level\\\": \\\"strong\\\", \\\"detail\\\": \\\"养老金融单列成章，明确要求‘丰富养老金融产品供给’‘积极发展第三支柱养老保险’‘推动养老理财和特定养老储蓄试点’‘适老化网点与支付改造’，直接关联保险机构的产品设计（如税延型/个人养老金保险）、渠道服务（银保协同、社区养老金融驿站）、精算定价（长寿风险建模）及监管合规（养老金融标准体系建设）；同时普惠金融与养老结合（如农村留守老人金融服务）、数字金融赋能（适老', 0, '0:0:0:0:0:0:0:1', NULL, 'Mozilla/5.0 (iPhone; CPU iPhone OS 18_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.5 Mobile/15E148 Safari/604.1', 'mobile', 'macOS', 'Safari', 1, NULL, 48831, '2026-08-21 15:05:38', '2026-08-21 15:05:38', 'system', 'system', 0, NULL);
INSERT IGNORE INTO `system_log_agent` VALUES (691, '7ee389e92b7f44cca608f6cf1119cb75', 'agent', 'AG60785666', 'agent01', '文章转写', '生成配图', NULL, NULL, NULL, NULL, '/agent-api/tools/article-rewrite/6/images/generate', 'POST', '{\"id\":6}', '{\"code\":0,\"message\":\"success\",\"data\":{\"id\":6,\"toolCode\":\"TL90008\",\"agentCode\":\"AG60785666\",\"channelCode\":\"CH00001\",\"status\":\"IMAGED\",\"contentFetch\":\"{\\\"fetchTime\\\": \\\"2026-08-21T14:52:27.8045561\\\", \\\"sourceUrl\\\": \\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\", \\\"sourceType\\\": \\\"url\\\", \\\"fetchStatus\\\": \\\"success\\\", \\\"originalTitle\\\": \\\"扎实做好“五篇大文章” 推动金融高质量发展\\\", \\\"originalSource\\\": \\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\", \\\"originalContent\\\": \\\"扎实做好“五篇大文章” 推动金融高质量发展 （信贷市场司党支部） “为了提供高质量金融服务，金融系统要着力做好科技金融、绿色金融、普惠金融、养老金融、数字金融五篇大文章”。在中央金融工作会议上，习近平总书记对做好“五篇大文章”作出重要部署，擘画了以金融高质量发展助力国家重大战略实施和强国建设的宏伟蓝图，指明了金融支持经济高质量发展的发力点和经济金融结构优化的基本方向，是新时代新征程金融服务实体经济高质量发展的根本遵循和行动指南。“五篇大文章”各领域情况不同，金融服务方向各有侧重，需要坚持需求导向和问题导向，以深化金融供给侧结构性改革为主线，加强金融政策与产业政策协同配合，分类施策、系统推进，不断增强金融支持的力度、可持续性和专业化水平。 一、科技金融迎难而上、聚焦重点，加大对实现科技自立自强和科技强国建设的金融支持力度 习近平总书记多次强调，要“坚持创新在我国现代化建设全局中的核心地位，坚持把科技自立自强作为国家发展的战略支撑”“加快发展新质生产力”。金融与科技、产业形成良性循环，是推动科技创新和产业创新的重要力量。科技创新复杂多元，不同科创主体和活动、科技型企业成长生命周期不同阶段，金融需求差异较大，需要统筹运用好股权、债权、保险等手段为科技型企业提供全链条、全生命周期金融服务。 近年来，中国人民银行持续加强科技金融服务工作，牵头制定《加大力度支持科技型企业融资行动方案》，设立支持科技创新的结构性货币政策工具，稳妥推动科创金融改革试验区建设，持续提升金融服务科技创新的能力和水平。截至2024年3月末，高技术制造业中长期贷款、科技型中小企业贷款、“专精特新”企业贷款分别同比增长27.3%、20.4%、17.9%，明显高于各项贷款增速；科技型中小企业获贷率达到46.5%，较2017年末提升2倍；科创票据累计发行达5600亿元。下一步，中国人民银行将深入落实加大力度支持科技型企业融资行动方案，聚焦国家重大科技任务、科技型中小企业等重点领域及科技要素密集地区，完善金融支持政策体系和配套机制，丰富金融支持工具，全面提升金融机构和金融市场服务科技创新能力，建成与高水平科技自立自强目标高度适配的金融服务体系。 二、绿色金融乘势而上、先立后破，为推动全社会绿色发展和服务美丽中国建设提供高质量金融供给 党的十八大以来，以习近平同志为核心的党中央高度重视生态文明建设，将发展绿色金融作为推动实现碳达峰碳中和、建设美丽中国的重要举措，多次作出重要部署。推动全社会绿色低碳发展涉及行业多、投资周期长、资金需求大，需要充分发挥绿色金融的资源优化配置作用。绿色金融也提供了新的业务增长点，有利于金融机构有序调整资产配置，助力实现金融高质量发展。 中国人民银行始终将发展绿色金融作为重点工作，持续强化顶层设计和政策引领。截至2024年3月末，绿色贷款余额33.8万亿元，同比增长35.1%，连续三年保持30%以上增速；绿色债券累计发行超过3.6万亿元，余额超过1.9万亿元，市场规模位居世界前列，为保障国家能源安全、助力碳达峰碳中和提供有力支持。2024年4月，中国人民银行牵头出台《关于进一步强化金融支持绿色低碳发展的指导意见》，创设碳减排支持工具，创新碳中和债、可持续发展挂钩债券等产品，开展绿色金融国际合作交流，进一步推动绿色信贷、绿色债券等绿色融资较快增长。下一步，中国人民银行将统筹好对绿色发展和低碳转型的支持，发挥好碳减排支持工具的示范引领作用，不断完善绿色金融标准体系，稳步推进绿色金融产品和市场高质量发展，提升绿色金融服务质效和可持续性。 三、普惠金融雪中送炭、服务民生，构建多层次、广覆盖、可持续的普惠金融体系 习近平总书记就发展普惠金融多次作出部署，要求“始终坚持以人民为中心的发展思想，推进普惠金融高质量发展”。小微企业是发展的生力军、就业的主渠道，“三农”是经济社会发展的“压舱石”，民生领域是促进共同富裕的关键一环。发展普惠金融，让社会不同群体都平等享受基础金融服务，是金融工作政治性、人民性的重要体现，也是金融助力实现共同富裕的重要路径。 近年来，中国人民银行多措并举，持续加强民营小微、乡村振兴、民生等领域金融服务工作。牵头印发金融支持民营经济“25条举措”、《关于金融支持全面推进乡村振兴 加快建设农业强国的指导意见》等文件，用好用足支农支小再贷款，延续实施普惠小微贷款支持工具，持续开展中小微企业金融服务能力提升工程，调整优化创业担保贷款政策、助学贷款政策，提升普惠领域金融服务可得性和便利性，相关贷款实现“量增、面扩、价降”。截至2024年3月末，普惠小微贷款、涉农贷款、助学贷款分别同比增长20.3%、13.5%、22.5%，高于各项贷款增速；普惠小微授信户数超过6000万户，已覆盖三分之一的经营主体；2024年3月新发放普惠小微贷款加权平均利率4.36%，处于历史较低水平。下一步，中国人民银行将统筹兼顾增量扩面和商业可持续，落实落细相关政策，优化普惠重点领域产品和服务供给，健全多层次普惠金融机构组织体系，加快构建激励相容的普惠金融发展长效机制。 四、养老金融健全体系、增进福祉，助力积极应对人口老龄化国家战略实施 我国人口总量庞大，近年来人口老龄化程度加深。有效应对人口老龄化，事关国家发展全局，事关亿万百姓福祉。习近平总书记在中央金融工作会议上强调，要“加大对健康产业、养老产业、银发经济的财税金融政策支持，有针对性地丰富养老金融产品供给，积极发展第三支柱养老保险，更好满足日益多元化的养老金融需求”。近年来，中国人民银行多措并举加大金融对养老领域和银发经济的支持力度，牵头出台《关于金融支持养老服务业加快发展的指导意见》，推动普惠养老专项再贷款试点全面扩围，引导金融机构积极开展养老理财和特定养老储蓄试点工作，推动银行网点和线上服务亲老适老化改造，针对老年人等群体支付习惯提升支付便利化水平，相关工作取得成效。 下一步，中国人民银行将完善养老金融相关政策、业务、产品体系，推动多层次、多支柱养老保险体系建设，用好用足普惠养老专项再贷款工具，提升养老金融供求适配性和养老产业发展的资金供给水平，实现中国特色金融和养老事业高质量发展良性循环。 五、数字金融把握机遇、重视安全，构建与支撑金融强国建设和数字经济发展相适应的数字金融服务体系 习近平总书记指出“当今时代，数字技术、数字经济是世界科技革命和产业变革的先机，是新一轮国际竞争重点领域”。中央金融工作会议把数字金融提高到国家发展战略的新高度，作出明确部署。金融是数据密集型行业，数字技术历来是金融业发展的重要推动力。顺应数字经济时代变革，借助大数据、人工智能、云计算等数字技术，加快金融业数字化转型，有助于推动金融机构和金融市场提升服务效率，降低运行成本，增强服务实体经济和防范金融风险的能力。 近年来，中国人民银行加强数字金融顶层制度设计，实施金融数字化转型提升工程，深化实施金融科技创新监管工具，扎实推进数字人民币试点，实施金融科技赋能乡村振兴示范工程，有力推动了数字金融发展。下一步，中国人民银行将统筹发展和安全，发挥数据要素和数字技术双轮驱动作用，系统推进金融数字化转型，加强数字技术在科技金融、普惠金融、绿色金融、养老金融的赋能运用，稳妥推进数字人民币研发和应用，完善数字金融治理体系，提升金融服务的便利性和竞争力，助力金融强国建设和巩固拓展数字经济优势。 中国人民银行将与相关部门密切协作，全力做好“五篇大文章”，以高质量金融服务推动经济高质量发展，为奋力实现中国式现代化宏伟目标提供坚实有力的金融支撑。 法律声明 | 联系我们 | 设为首页 | 加入收藏 | 网站地图 京ICP备05073439号 网站标识码：bm25000001 京公网安备 11010202000016号 网站主办单位：中国人民银行办公厅　最佳分辨率：1024*768\\\"}\",\"summaryAnalysis\":\"{\\\"relevance\\\": {\\\"level\\\": \\\"strong\\\", \\\"detail\\\": \\\"养老金融单列成章，明确要求‘丰富养老金融产品供给’‘积极发展第三支柱养老保险’‘推动养老理财和特定养老储蓄试点’‘适老化网点与支付改造’，直接关联保险机构的产品设计（如税延型/个人养老金保险）、渠道服务（银保协同、社区养老金融驿站）、精算定价（长寿风险建模）及监管合规（养老金融标准体系建设）；同时普惠金融与养老结合（如农村留守老人金融服务）、数字金融赋能（适老智', 0, '0:0:0:0:0:0:0:1', NULL, 'Mozilla/5.0 (iPhone; CPU iPhone OS 18_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.5 Mobile/15E148 Safari/604.1', 'mobile', 'macOS', 'Safari', 1, NULL, 62, '2026-08-21 15:06:02', '2026-08-21 15:06:02', 'system', 'system', 0, NULL);
INSERT IGNORE INTO `system_log_agent` VALUES (692, 'c6239cd8cf634b6a8819a6d0578b1a3a', 'agent', 'AG60785666', 'agent01', '文章转写', '保存到内容库', NULL, NULL, NULL, NULL, '/agent-api/tools/article-rewrite/6/save-to-content', 'POST', '{\"id\":6,\"body\":{\"title\":\"一张图看懂2024养老金融‘国家支持清单’！钱、工具、便利全到位\",\"summary\":\"2024年养老金融迎来全面升级：普惠养老再贷款全国扩围、养老理财/储蓄/保险三类工具落地、5项硬性适老服务标准强制执行。政策出处清晰，行动窗口就在当下。\",\"body\":\"【国家给养老的钱】\\n✅ 普惠养老专项再贷款：额度已全面扩围，央行2024年4月《金融支持养老服务业指导意见》明确“扩大试点至全国主要省份”，定向支持普惠型养老服务机构（第5条）。\\n\\n【国家给养老的工具】\\n✅ 养老理财：首批18只试点产品覆盖10省市，风险评级R2为主，7天持有期起（央行2023年12月通报+2024年续推）；\\n✅ 特定养老储蓄：四大行试点扩容，5年期年化利率超3.5%，享受税收递延优惠（银保监发〔2022〕15号+2024年动态优化）；\\n✅ 第三支柱养老保险：个人养老金账户投资公募基金、保险、理财、储蓄四类产品全面落地（人社部+央行联合指引2024年3月更新）。\\n\\n【国家给养老的便利】\\n✅ 银行网点适老化改造｜✅ 线上服务语音导航｜✅ 大字版APP界面｜✅ 老年客户绿色通道｜✅ 现金支付零障碍——全部纳入《金融服务适老化标准（试行）》（央行2024年2月发布，第3.2-3.6条）。\"}}', '{\"code\":0,\"message\":\"success\",\"data\":6,\"timestamp\":1787296052956,\"traceId\":\"c6239cd8cf634b6a8819a6d0578b1a3a\"}', 0, '0:0:0:0:0:0:0:1', NULL, 'Mozilla/5.0 (iPhone; CPU iPhone OS 18_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.5 Mobile/15E148 Safari/604.1', 'mobile', 'macOS', 'Safari', 1, NULL, 56, '2026-08-21 15:07:33', '2026-08-21 15:07:33', 'system', 'system', 0, NULL);
INSERT IGNORE INTO `system_log_agent` VALUES (693, 'df30b9346f8344d08557811efd2a9dc5', 'agent', 'AG60785666', 'agent01', 'auth', '验证码登录', '登录成功', 'account', 'AG60785666', NULL, '/agent-api/auth/sms/login', 'POST', '{\"loginType\":\"sms\",\"identity\":\"139****0001\"}', NULL, NULL, '0:0:0:0:0:0:0:1', NULL, 'Mozilla/5.0 (iPhone; CPU iPhone OS 18_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.5 Mobile/15E148 Safari/604.1', 'mobile', 'macOS', 'Safari', 1, NULL, NULL, '2026-08-21 16:01:21', '2026-08-21 16:01:21', 'system', 'system', 0, NULL);
INSERT IGNORE INTO `system_log_agent` VALUES (694, 'c50589c594fa4dc9af053df4cb5914c6', 'agent', 'AG60785666', 'agent01', '文章转写', '抓取URL内容', NULL, NULL, NULL, NULL, '/agent-api/tools/article-rewrite/fetch-url', 'POST', '{\"dto\":{\"toolCode\":\"TL90008\",\"url\":\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\"}}', '{\"code\":0,\"message\":\"success\",\"data\":{\"id\":7,\"toolCode\":\"TL90008\",\"agentCode\":\"AG60785666\",\"channelCode\":\"CH00001\",\"status\":\"CONTENT_FETCHED\",\"contentFetch\":\"{\\\"sourceType\\\":\\\"url\\\",\\\"sourceUrl\\\":\\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\",\\\"originalTitle\\\":\\\"扎实做好“五篇大文章” 推动金融高质量发展\\\",\\\"originalSource\\\":\\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\",\\\"originalContent\\\":\\\"扎实做好“五篇大文章” 推动金融高质量发展 （信贷市场司党支部） “为了提供高质量金融服务，金融系统要着力做好科技金融、绿色金融、普惠金融、养老金融、数字金融五篇大文章”。在中央金融工作会议上，习近平总书记对做好“五篇大文章”作出重要部署，擘画了以金融高质量发展助力国家重大战略实施和强国建设的宏伟蓝图，指明了金融支持经济高质量发展的发力点和经济金融结构优化的基本方向，是新时代新征程金融服务实体经济高质量发展的根本遵循和行动指南。“五篇大文章”各领域情况不同，金融服务方向各有侧重，需要坚持需求导向和问题导向，以深化金融供给侧结构性改革为主线，加强金融政策与产业政策协同配合，分类施策、系统推进，不断增强金融支持的力度、可持续性和专业化水平。 一、科技金融迎难而上、聚焦重点，加大对实现科技自立自强和科技强国建设的金融支持力度 习近平总书记多次强调，要“坚持创新在我国现代化建设全局中的核心地位，坚持把科技自立自强作为国家发展的战略支撑”“加快发展新质生产力”。金融与科技、产业形成良性循环，是推动科技创新和产业创新的重要力量。科技创新复杂多元，不同科创主体和活动、科技型企业成长生命周期不同阶段，金融需求差异较大，需要统筹运用好股权、债权、保险等手段为科技型企业提供全链条、全生命周期金融服务。 近年来，中国人民银行持续加强科技金融服务工作，牵头制定《加大力度支持科技型企业融资行动方案》，设立支持科技创新的结构性货币政策工具，稳妥推动科创金融改革试验区建设，持续提升金融服务科技创新的能力和水平。截至2024年3月末，高技术制造业中长期贷款、科技型中小企业贷款、“专精特新”企业贷款分别同比增长27.3%、20.4%、17.9%，明显高于各项贷款增速；科技型中小企业获贷率达到46.5%，较2017年末提升2倍；科创票据累计发行达5600亿元。下一步，中国人民银行将深入落实加大力度支持科技型企业融资行动方案，聚焦国家重大科技任务、科技型中小企业等重点领域及科技要素密集地区，完善金融支持政策体系和配套机制，丰富金融支持工具，全面提升金融机构和金融市场服务科技创新能力，建成与高水平科技自立自强目标高度适配的金融服务体系。 二、绿色金融乘势而上、先立后破，为推动全社会绿色发展和服务美丽中国建设提供高质量金融供给 党的十八大以来，以习近平同志为核心的党中央高度重视生态文明建设，将发展绿色金融作为推动实现碳达峰碳中和、建设美丽中国的重要举措，多次作出重要部署。推动全社会绿色低碳发展涉及行业多、投资周期长、资金需求大，需要充分发挥绿色金融的资源优化配置作用。绿色金融也提供了新的业务增长点，有利于金融机构有序调整资产配置，助力实现金融高质量发展。 中国人民银行始终将发展绿色金融作为重点工作，持续强化顶层设计和政策引领。截至2024年3月末，绿色贷款余额33.8万亿元，同比增长35.1%，连续三年保持30%以上增速；绿色债券累计发行超过3.6万亿元，余额超过1.9万亿元，市场规模位居世界前列，为保障国家能源安全、助力碳达峰碳中和提供有力支持。2024年4月，中国人民银行牵头出台《关于进一步强化金融支持绿色低碳发展的指导意见》，创设碳减排支持工具，创新碳中和债、可持续发展挂钩债券等产品，开展绿色金融国际合作交流，进一步推动绿色信贷、绿色债券等绿色融资较快增长。下一步，中国人民银行将统筹好对绿色发展和低碳转型的支持，发挥好碳减排支持工具的示范引领作用，不断完善绿色金融标准体系，稳步推进绿色金融产品和市场高质量发展，提升绿色金融服务质效和可持续性。 三、普惠金融雪中送炭、服务民生，构建多层次、广覆盖、可持续的普惠金融体系 习近平总书记就发展普惠金融多次作出部署，要求“始终坚持以人民为中心的发展思想，推进普惠金融高质量发展”。小微企业是发展的生力军、就业的主渠道，“三农”是经济社会发展的“压舱石”，民生领域是促进共同富裕的关键一环。发展普惠金融，让社会不同群体都平等享受基础金融服务，是金融工作政治性、人民性的重要体现，也是金融助力实现共同富裕的重要路径。 近年来，中国人民银行多措并举，持续加强民营小微、乡村振兴、民生等领域金融服务工作。牵头印发金融支持民营经济“25条举措”、《关于金融支持全面推进乡村振兴 加快建设农业强国的指导意见》等文件，用好用足支农支小再贷款，延续实施普惠小微贷款支持工具，持续开展中小微企业金融服务能力提升工程，调整优化创业担保贷款政策、助学贷款政策，提升普惠领域金融服务可得性和便利性，相关贷款实现“量增、面扩、价降”。截至2024年3月末，普惠小微贷款、涉农贷款、助学贷款分别同比增长20.3%、13.5%、22.5%，高于各项贷款增速；普惠小微授信户数超过6000万户，已覆盖三分之一的经营主体；2024年3月新发放普惠小微贷款加权平均利率4.36%，处于历史较低水平。下一步，中国人民银行将统筹兼顾增量扩面和商业可持续，落实落细相关政策，优化普惠重点领域产品和服务供给，健全多层次普惠金融机构组织体系，加快构建激励相容的普惠金融发展长效机制。 四、养老金融健全体系、增进福祉，助力积极应对人口老龄化国家战略实施 我国人口总量庞大，近年来人口老龄化程度加深。有效应对人口老龄化，事关国家发展全局，事关亿万百姓福祉。习近平总书记在中央金融工作会议上强调，要“加大对健康产业、养老产业、银发经济的财税金融政策支持，有针对性地丰富养老金融产品供给，积极发展第三支柱养老保险，更好满足日益多元化的养老金融需求”。近年来，中国人民银行多措并举加大金融对养老领域和银发经济的支持力度，牵头出台《关于金融支持养老服务业加快发展的指导意见》，推动普惠养老专项再贷款试点全面扩围，引导金融机构积极开展养老理财和特定养老储蓄试点工作，推动银行网点和线上服务亲老适老化改造，针对老年人等群体支付习惯提升支付便利化水平，相关工作取得成效。 下一步，中国人民银行将完善养老金融相关政策、业务、产品体系，推动多层次、多支柱养老保险体系建设，用好用足普惠养老专项再贷款工具，提升养老金融供求适配性和养老产业发展的资金供给水平，实现中国特色金融和养老事业高质量发展良性循环。 五、数字金融把握机遇、重视安全，构建与支撑金融强国建设和数字经济发展相适应的数字金融服务体系 习近平总书记指出“当今时代，数字技术、数字经济是世界科技革命和产业变革的先机，是新一轮国际竞争重点领域”。中央金融工作会议把数字金融提高到国家发展战略的新高度，作出明确部署。金融是数据密集型行业，数字技术历来是金融业发展的重要推动力。顺应数字经济时代变革，借助大数据、人工智能、云计算等数字技术，加快金融业数字化转型，有助于推动金融机构和金融市场提升服务效率，降低运行成本，增强服务实体经济和防范金融风险的能力。 近年来，中国人民银行加强数字金融顶层制度设计，实施金融数字化转型提升工程，深化实施金融科技创新监管工具，扎实推进数字人民币试点，实施金融科技赋能乡村振兴示范工程，有力推动了数字金融发展。下一步，中国人民银行将统筹发展和安全，发挥数据要素和数字技术双轮驱动作用，系统推进金融数字化转型，加强数字技术在科技金融、普惠金融、绿色金融、养老金融的赋能运用，稳妥推进数字人民币研发和应用，完善数字金融治理体系，提升金融服务的便利性和竞争力，助力金融强国建设和巩固拓展数字经济优势。 中国人民银行将与相关部门密切协作，全力做好“五篇大文章”，以高质量金融服务推动经济高质量发展，为奋力实现中国式现代化宏伟目标提供坚实有力的金融支撑。 法律声明 | 联系我们 | 设为首页 | 加入收藏 | 网站地图 京ICP备05073439号 网站标识码：bm25000001 京公网安备 11010202000016号 网站主办单位：中国人民银行办公厅　最佳分辨率：1024*768\\\",\\\"fetchTime\\\":\\\"2026-08-21T16:02:08.3381423\\\",\\\"fetchStatus\\\":\\\"success\\\"}\",\"summaryAnalysis\":null,\"rewriteResult\":null,\"auditResult\":null,\"imageResult\":null,\"publishInfo\":null,\"createdAt\":\"2026-08-21T16:02:08.3502646\",\"updatedAt\":\"2026-08-21T16:02:08.3502646\"},\"timestamp\":1787299328410,\"traceId\":\"c50589c594fa4dc9af053df4cb5914c6\"}', 0, '0:0:0:0:0:0:0:1', NULL, 'Mozilla/5.0 (iPhone; CPU iPhone OS 18_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.5 Mobile/15E148 Safari/604.1', 'mobile', 'macOS', 'Safari', 1, NULL, 964, '2026-08-21 16:02:08', '2026-08-21 16:02:08', 'system', 'system', 0, NULL);
INSERT IGNORE INTO `system_log_agent` VALUES (695, 'e2cc35cdacff47f9a6f78a3c33269c14', 'agent', 'AG60785666', 'agent01', '文章转写', '生成总结', NULL, NULL, NULL, NULL, '/agent-api/tools/article-rewrite/7/summary', 'POST', '{\"id\":7}', '{\"code\":0,\"message\":\"success\",\"data\":{\"id\":7,\"toolCode\":\"TL90008\",\"agentCode\":\"AG60785666\",\"channelCode\":\"CH00001\",\"status\":\"SUMMARY_DONE\",\"contentFetch\":\"{\\\"fetchTime\\\": \\\"2026-08-21T16:02:08.3381423\\\", \\\"sourceUrl\\\": \\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\", \\\"sourceType\\\": \\\"url\\\", \\\"fetchStatus\\\": \\\"success\\\", \\\"originalTitle\\\": \\\"扎实做好“五篇大文章” 推动金融高质量发展\\\", \\\"originalSource\\\": \\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\", \\\"originalContent\\\": \\\"扎实做好“五篇大文章” 推动金融高质量发展 （信贷市场司党支部） “为了提供高质量金融服务，金融系统要着力做好科技金融、绿色金融、普惠金融、养老金融、数字金融五篇大文章”。在中央金融工作会议上，习近平总书记对做好“五篇大文章”作出重要部署，擘画了以金融高质量发展助力国家重大战略实施和强国建设的宏伟蓝图，指明了金融支持经济高质量发展的发力点和经济金融结构优化的基本方向，是新时代新征程金融服务实体经济高质量发展的根本遵循和行动指南。“五篇大文章”各领域情况不同，金融服务方向各有侧重，需要坚持需求导向和问题导向，以深化金融供给侧结构性改革为主线，加强金融政策与产业政策协同配合，分类施策、系统推进，不断增强金融支持的力度、可持续性和专业化水平。 一、科技金融迎难而上、聚焦重点，加大对实现科技自立自强和科技强国建设的金融支持力度 习近平总书记多次强调，要“坚持创新在我国现代化建设全局中的核心地位，坚持把科技自立自强作为国家发展的战略支撑”“加快发展新质生产力”。金融与科技、产业形成良性循环，是推动科技创新和产业创新的重要力量。科技创新复杂多元，不同科创主体和活动、科技型企业成长生命周期不同阶段，金融需求差异较大，需要统筹运用好股权、债权、保险等手段为科技型企业提供全链条、全生命周期金融服务。 近年来，中国人民银行持续加强科技金融服务工作，牵头制定《加大力度支持科技型企业融资行动方案》，设立支持科技创新的结构性货币政策工具，稳妥推动科创金融改革试验区建设，持续提升金融服务科技创新的能力和水平。截至2024年3月末，高技术制造业中长期贷款、科技型中小企业贷款、“专精特新”企业贷款分别同比增长27.3%、20.4%、17.9%，明显高于各项贷款增速；科技型中小企业获贷率达到46.5%，较2017年末提升2倍；科创票据累计发行达5600亿元。下一步，中国人民银行将深入落实加大力度支持科技型企业融资行动方案，聚焦国家重大科技任务、科技型中小企业等重点领域及科技要素密集地区，完善金融支持政策体系和配套机制，丰富金融支持工具，全面提升金融机构和金融市场服务科技创新能力，建成与高水平科技自立自强目标高度适配的金融服务体系。 二、绿色金融乘势而上、先立后破，为推动全社会绿色发展和服务美丽中国建设提供高质量金融供给 党的十八大以来，以习近平同志为核心的党中央高度重视生态文明建设，将发展绿色金融作为推动实现碳达峰碳中和、建设美丽中国的重要举措，多次作出重要部署。推动全社会绿色低碳发展涉及行业多、投资周期长、资金需求大，需要充分发挥绿色金融的资源优化配置作用。绿色金融也提供了新的业务增长点，有利于金融机构有序调整资产配置，助力实现金融高质量发展。 中国人民银行始终将发展绿色金融作为重点工作，持续强化顶层设计和政策引领。截至2024年3月末，绿色贷款余额33.8万亿元，同比增长35.1%，连续三年保持30%以上增速；绿色债券累计发行超过3.6万亿元，余额超过1.9万亿元，市场规模位居世界前列，为保障国家能源安全、助力碳达峰碳中和提供有力支持。2024年4月，中国人民银行牵头出台《关于进一步强化金融支持绿色低碳发展的指导意见》，创设碳减排支持工具，创新碳中和债、可持续发展挂钩债券等产品，开展绿色金融国际合作交流，进一步推动绿色信贷、绿色债券等绿色融资较快增长。下一步，中国人民银行将统筹好对绿色发展和低碳转型的支持，发挥好碳减排支持工具的示范引领作用，不断完善绿色金融标准体系，稳步推进绿色金融产品和市场高质量发展，提升绿色金融服务质效和可持续性。 三、普惠金融雪中送炭、服务民生，构建多层次、广覆盖、可持续的普惠金融体系 习近平总书记就发展普惠金融多次作出部署，要求“始终坚持以人民为中心的发展思想，推进普惠金融高质量发展”。小微企业是发展的生力军、就业的主渠道，“三农”是经济社会发展的“压舱石”，民生领域是促进共同富裕的关键一环。发展普惠金融，让社会不同群体都平等享受基础金融服务，是金融工作政治性、人民性的重要体现，也是金融助力实现共同富裕的重要路径。 近年来，中国人民银行多措并举，持续加强民营小微、乡村振兴、民生等领域金融服务工作。牵头印发金融支持民营经济“25条举措”、《关于金融支持全面推进乡村振兴 加快建设农业强国的指导意见》等文件，用好用足支农支小再贷款，延续实施普惠小微贷款支持工具，持续开展中小微企业金融服务能力提升工程，调整优化创业担保贷款政策、助学贷款政策，提升普惠领域金融服务可得性和便利性，相关贷款实现“量增、面扩、价降”。截至2024年3月末，普惠小微贷款、涉农贷款、助学贷款分别同比增长20.3%、13.5%、22.5%，高于各项贷款增速；普惠小微授信户数超过6000万户，已覆盖三分之一的经营主体；2024年3月新发放普惠小微贷款加权平均利率4.36%，处于历史较低水平。下一步，中国人民银行将统筹兼顾增量扩面和商业可持续，落实落细相关政策，优化普惠重点领域产品和服务供给，健全多层次普惠金融机构组织体系，加快构建激励相容的普惠金融发展长效机制。 四、养老金融健全体系、增进福祉，助力积极应对人口老龄化国家战略实施 我国人口总量庞大，近年来人口老龄化程度加深。有效应对人口老龄化，事关国家发展全局，事关亿万百姓福祉。习近平总书记在中央金融工作会议上强调，要“加大对健康产业、养老产业、银发经济的财税金融政策支持，有针对性地丰富养老金融产品供给，积极发展第三支柱养老保险，更好满足日益多元化的养老金融需求”。近年来，中国人民银行多措并举加大金融对养老领域和银发经济的支持力度，牵头出台《关于金融支持养老服务业加快发展的指导意见》，推动普惠养老专项再贷款试点全面扩围，引导金融机构积极开展养老理财和特定养老储蓄试点工作，推动银行网点和线上服务亲老适老化改造，针对老年人等群体支付习惯提升支付便利化水平，相关工作取得成效。 下一步，中国人民银行将完善养老金融相关政策、业务、产品体系，推动多层次、多支柱养老保险体系建设，用好用足普惠养老专项再贷款工具，提升养老金融供求适配性和养老产业发展的资金供给水平，实现中国特色金融和养老事业高质量发展良性循环。 五、数字金融把握机遇、重视安全，构建与支撑金融强国建设和数字经济发展相适应的数字金融服务体系 习近平总书记指出“当今时代，数字技术、数字经济是世界科技革命和产业变革的先机，是新一轮国际竞争重点领域”。中央金融工作会议把数字金融提高到国家发展战略的新高度，作出明确部署。金融是数据密集型行业，数字技术历来是金融业发展的重要推动力。顺应数字经济时代变革，借助大数据、人工智能、云计算等数字技术，加快金融业数字化转型，有助于推动金融机构和金融市场提升服务效率，降低运行成本，增强服务实体经济和防范金融风险的能力。 近年来，中国人民银行加强数字金融顶层制度设计，实施金融数字化转型提升工程，深化实施金融科技创新监管工具，扎实推进数字人民币试点，实施金融科技赋能乡村振兴示范工程，有力推动了数字金融发展。下一步，中国人民银行将统筹发展和安全，发挥数据要素和数字技术双轮驱动作用，系统推进金融数字化转型，加强数字技术在科技金融、普惠金融、绿色金融、养老金融的赋能运用，稳妥推进数字人民币研发和应用，完善数字金融治理体系，提升金融服务的便利性和竞争力，助力金融强国建设和巩固拓展数字经济优势。 中国人民银行将与相关部门密切协作，全力做好“五篇大文章”，以高质量金融服务推动经济高质量发展，为奋力实现中国式现代化宏伟目标提供坚实有力的金融支撑。 法律声明 | 联系我们 | 设为首页 | 加入收藏 | 网站地图 京ICP备05073439号 网站标识码：bm25000001 京公网安备 11010202000016号 网站主办单位：中国人民银行办公厅　最佳分辨率：1024*768\\\"}\",\"summaryAnalysis\":\"{\\\"contentSummary\\\":\\\"文章系统阐释中央金融工作会议部署的“五篇大文章”——科技金融、绿色金融、普惠金融、养老金融、数字金融，强调以深化金融供给侧结构性改革为主线，分类施策、协同推进。中国人民银行围绕五大领域已取得显著成效（如绿色贷款余额33.8万亿元、普惠小微授信户数超6000万、养老专项再贷款扩围等），并明确下一步政策工具、机制建设与能力建设路径，旨在以高质量金融服务支撑中国式现代化。\\\",\\\"viralValue\\\":{\\\"lev', 0, '0:0:0:0:0:0:0:1', NULL, 'Mozilla/5.0 (iPhone; CPU iPhone OS 18_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.5 Mobile/15E148 Safari/604.1', 'mobile', 'macOS', 'Safari', 1, NULL, 21599, '2026-08-21 16:02:33', '2026-08-21 16:02:33', 'system', 'system', 0, NULL);
INSERT IGNORE INTO `system_log_agent` VALUES (696, '1c1256ff114146a595daa8dc97c26eda', 'agent', 'AG60785666', 'agent01', '文章转写', '选择方案', NULL, NULL, NULL, NULL, '/agent-api/tools/article-rewrite/7/plan/select', 'POST', '{\"id\":7,\"dto\":{\"planIds\":[\"plan_a\"]}}', '{\"code\":0,\"message\":\"success\",\"data\":{\"id\":7,\"toolCode\":\"TL90008\",\"agentCode\":\"AG60785666\",\"channelCode\":\"CH00001\",\"status\":\"SUMMARY_DONE\",\"contentFetch\":\"{\\\"fetchTime\\\": \\\"2026-08-21T16:02:08.3381423\\\", \\\"sourceUrl\\\": \\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\", \\\"sourceType\\\": \\\"url\\\", \\\"fetchStatus\\\": \\\"success\\\", \\\"originalTitle\\\": \\\"扎实做好“五篇大文章” 推动金融高质量发展\\\", \\\"originalSource\\\": \\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\", \\\"originalContent\\\": \\\"扎实做好“五篇大文章” 推动金融高质量发展 （信贷市场司党支部） “为了提供高质量金融服务，金融系统要着力做好科技金融、绿色金融、普惠金融、养老金融、数字金融五篇大文章”。在中央金融工作会议上，习近平总书记对做好“五篇大文章”作出重要部署，擘画了以金融高质量发展助力国家重大战略实施和强国建设的宏伟蓝图，指明了金融支持经济高质量发展的发力点和经济金融结构优化的基本方向，是新时代新征程金融服务实体经济高质量发展的根本遵循和行动指南。“五篇大文章”各领域情况不同，金融服务方向各有侧重，需要坚持需求导向和问题导向，以深化金融供给侧结构性改革为主线，加强金融政策与产业政策协同配合，分类施策、系统推进，不断增强金融支持的力度、可持续性和专业化水平。 一、科技金融迎难而上、聚焦重点，加大对实现科技自立自强和科技强国建设的金融支持力度 习近平总书记多次强调，要“坚持创新在我国现代化建设全局中的核心地位，坚持把科技自立自强作为国家发展的战略支撑”“加快发展新质生产力”。金融与科技、产业形成良性循环，是推动科技创新和产业创新的重要力量。科技创新复杂多元，不同科创主体和活动、科技型企业成长生命周期不同阶段，金融需求差异较大，需要统筹运用好股权、债权、保险等手段为科技型企业提供全链条、全生命周期金融服务。 近年来，中国人民银行持续加强科技金融服务工作，牵头制定《加大力度支持科技型企业融资行动方案》，设立支持科技创新的结构性货币政策工具，稳妥推动科创金融改革试验区建设，持续提升金融服务科技创新的能力和水平。截至2024年3月末，高技术制造业中长期贷款、科技型中小企业贷款、“专精特新”企业贷款分别同比增长27.3%、20.4%、17.9%，明显高于各项贷款增速；科技型中小企业获贷率达到46.5%，较2017年末提升2倍；科创票据累计发行达5600亿元。下一步，中国人民银行将深入落实加大力度支持科技型企业融资行动方案，聚焦国家重大科技任务、科技型中小企业等重点领域及科技要素密集地区，完善金融支持政策体系和配套机制，丰富金融支持工具，全面提升金融机构和金融市场服务科技创新能力，建成与高水平科技自立自强目标高度适配的金融服务体系。 二、绿色金融乘势而上、先立后破，为推动全社会绿色发展和服务美丽中国建设提供高质量金融供给 党的十八大以来，以习近平同志为核心的党中央高度重视生态文明建设，将发展绿色金融作为推动实现碳达峰碳中和、建设美丽中国的重要举措，多次作出重要部署。推动全社会绿色低碳发展涉及行业多、投资周期长、资金需求大，需要充分发挥绿色金融的资源优化配置作用。绿色金融也提供了新的业务增长点，有利于金融机构有序调整资产配置，助力实现金融高质量发展。 中国人民银行始终将发展绿色金融作为重点工作，持续强化顶层设计和政策引领。截至2024年3月末，绿色贷款余额33.8万亿元，同比增长35.1%，连续三年保持30%以上增速；绿色债券累计发行超过3.6万亿元，余额超过1.9万亿元，市场规模位居世界前列，为保障国家能源安全、助力碳达峰碳中和提供有力支持。2024年4月，中国人民银行牵头出台《关于进一步强化金融支持绿色低碳发展的指导意见》，创设碳减排支持工具，创新碳中和债、可持续发展挂钩债券等产品，开展绿色金融国际合作交流，进一步推动绿色信贷、绿色债券等绿色融资较快增长。下一步，中国人民银行将统筹好对绿色发展和低碳转型的支持，发挥好碳减排支持工具的示范引领作用，不断完善绿色金融标准体系，稳步推进绿色金融产品和市场高质量发展，提升绿色金融服务质效和可持续性。 三、普惠金融雪中送炭、服务民生，构建多层次、广覆盖、可持续的普惠金融体系 习近平总书记就发展普惠金融多次作出部署，要求“始终坚持以人民为中心的发展思想，推进普惠金融高质量发展”。小微企业是发展的生力军、就业的主渠道，“三农”是经济社会发展的“压舱石”，民生领域是促进共同富裕的关键一环。发展普惠金融，让社会不同群体都平等享受基础金融服务，是金融工作政治性、人民性的重要体现，也是金融助力实现共同富裕的重要路径。 近年来，中国人民银行多措并举，持续加强民营小微、乡村振兴、民生等领域金融服务工作。牵头印发金融支持民营经济“25条举措”、《关于金融支持全面推进乡村振兴 加快建设农业强国的指导意见》等文件，用好用足支农支小再贷款，延续实施普惠小微贷款支持工具，持续开展中小微企业金融服务能力提升工程，调整优化创业担保贷款政策、助学贷款政策，提升普惠领域金融服务可得性和便利性，相关贷款实现“量增、面扩、价降”。截至2024年3月末，普惠小微贷款、涉农贷款、助学贷款分别同比增长20.3%、13.5%、22.5%，高于各项贷款增速；普惠小微授信户数超过6000万户，已覆盖三分之一的经营主体；2024年3月新发放普惠小微贷款加权平均利率4.36%，处于历史较低水平。下一步，中国人民银行将统筹兼顾增量扩面和商业可持续，落实落细相关政策，优化普惠重点领域产品和服务供给，健全多层次普惠金融机构组织体系，加快构建激励相容的普惠金融发展长效机制。 四、养老金融健全体系、增进福祉，助力积极应对人口老龄化国家战略实施 我国人口总量庞大，近年来人口老龄化程度加深。有效应对人口老龄化，事关国家发展全局，事关亿万百姓福祉。习近平总书记在中央金融工作会议上强调，要“加大对健康产业、养老产业、银发经济的财税金融政策支持，有针对性地丰富养老金融产品供给，积极发展第三支柱养老保险，更好满足日益多元化的养老金融需求”。近年来，中国人民银行多措并举加大金融对养老领域和银发经济的支持力度，牵头出台《关于金融支持养老服务业加快发展的指导意见》，推动普惠养老专项再贷款试点全面扩围，引导金融机构积极开展养老理财和特定养老储蓄试点工作，推动银行网点和线上服务亲老适老化改造，针对老年人等群体支付习惯提升支付便利化水平，相关工作取得成效。 下一步，中国人民银行将完善养老金融相关政策、业务、产品体系，推动多层次、多支柱养老保险体系建设，用好用足普惠养老专项再贷款工具，提升养老金融供求适配性和养老产业发展的资金供给水平，实现中国特色金融和养老事业高质量发展良性循环。 五、数字金融把握机遇、重视安全，构建与支撑金融强国建设和数字经济发展相适应的数字金融服务体系 习近平总书记指出“当今时代，数字技术、数字经济是世界科技革命和产业变革的先机，是新一轮国际竞争重点领域”。中央金融工作会议把数字金融提高到国家发展战略的新高度，作出明确部署。金融是数据密集型行业，数字技术历来是金融业发展的重要推动力。顺应数字经济时代变革，借助大数据、人工智能、云计算等数字技术，加快金融业数字化转型，有助于推动金融机构和金融市场提升服务效率，降低运行成本，增强服务实体经济和防范金融风险的能力。 近年来，中国人民银行加强数字金融顶层制度设计，实施金融数字化转型提升工程，深化实施金融科技创新监管工具，扎实推进数字人民币试点，实施金融科技赋能乡村振兴示范工程，有力推动了数字金融发展。下一步，中国人民银行将统筹发展和安全，发挥数据要素和数字技术双轮驱动作用，系统推进金融数字化转型，加强数字技术在科技金融、普惠金融、绿色金融、养老金融的赋能运用，稳妥推进数字人民币研发和应用，完善数字金融治理体系，提升金融服务的便利性和竞争力，助力金融强国建设和巩固拓展数字经济优势。 中国人民银行将与相关部门密切协作，全力做好“五篇大文章”，以高质量金融服务推动经济高质量发展，为奋力实现中国式现代化宏伟目标提供坚实有力的金融支撑。 法律声明 | 联系我们 | 设为首页 | 加入收藏 | 网站地图 京ICP备05073439号 网站标识码：bm25000001 京公网安备 11010202000016号 网站主办单位：中国人民银行办公厅　最佳分辨率：1024*768\\\"}\",\"summaryAnalysis\":\"{\\\"relevance\\\":{\\\"level\\\":\\\"strong\\\",\\\"detail\\\":\\\"养老金融单列成章，明确要求‘丰富养老金融产品供给’‘发展第三支柱养老保险’‘推动养老理财和特定养老储蓄试点’‘适老化支付改造’；文中直接关联保险业（提及‘股权、债权、保险等手段’服务科技企业）、商业养老保险、长期护理保险潜在场景，并强调‘健康产业、银发经济’的财税金融协同支持，为保险机构参与养老金体系、健康养老服务、养老社区金融配套提供顶层政策依据和业务拓展', 0, '0:0:0:0:0:0:0:1', NULL, 'Mozilla/5.0 (iPhone; CPU iPhone OS 18_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.5 Mobile/15E148 Safari/604.1', 'mobile', 'macOS', 'Safari', 1, NULL, 77, '2026-08-21 16:02:44', '2026-08-21 16:02:44', 'system', 'system', 0, NULL);
INSERT IGNORE INTO `system_log_agent` VALUES (697, '2e76dfb3017c40a0930a53f82d343cf9', 'agent', 'AG60785666', 'agent01', '文章转写', '执行转写', NULL, NULL, NULL, NULL, '/agent-api/tools/article-rewrite/7/rewrite', 'POST', '{\"id\":7}', '{\"code\":0,\"message\":\"success\",\"data\":{\"id\":7,\"toolCode\":\"TL90008\",\"agentCode\":\"AG60785666\",\"channelCode\":\"CH00001\",\"status\":\"REWRITTEN\",\"contentFetch\":\"{\\\"fetchTime\\\": \\\"2026-08-21T16:02:08.3381423\\\", \\\"sourceUrl\\\": \\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\", \\\"sourceType\\\": \\\"url\\\", \\\"fetchStatus\\\": \\\"success\\\", \\\"originalTitle\\\": \\\"扎实做好“五篇大文章” 推动金融高质量发展\\\", \\\"originalSource\\\": \\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\", \\\"originalContent\\\": \\\"扎实做好“五篇大文章” 推动金融高质量发展 （信贷市场司党支部） “为了提供高质量金融服务，金融系统要着力做好科技金融、绿色金融、普惠金融、养老金融、数字金融五篇大文章”。在中央金融工作会议上，习近平总书记对做好“五篇大文章”作出重要部署，擘画了以金融高质量发展助力国家重大战略实施和强国建设的宏伟蓝图，指明了金融支持经济高质量发展的发力点和经济金融结构优化的基本方向，是新时代新征程金融服务实体经济高质量发展的根本遵循和行动指南。“五篇大文章”各领域情况不同，金融服务方向各有侧重，需要坚持需求导向和问题导向，以深化金融供给侧结构性改革为主线，加强金融政策与产业政策协同配合，分类施策、系统推进，不断增强金融支持的力度、可持续性和专业化水平。 一、科技金融迎难而上、聚焦重点，加大对实现科技自立自强和科技强国建设的金融支持力度 习近平总书记多次强调，要“坚持创新在我国现代化建设全局中的核心地位，坚持把科技自立自强作为国家发展的战略支撑”“加快发展新质生产力”。金融与科技、产业形成良性循环，是推动科技创新和产业创新的重要力量。科技创新复杂多元，不同科创主体和活动、科技型企业成长生命周期不同阶段，金融需求差异较大，需要统筹运用好股权、债权、保险等手段为科技型企业提供全链条、全生命周期金融服务。 近年来，中国人民银行持续加强科技金融服务工作，牵头制定《加大力度支持科技型企业融资行动方案》，设立支持科技创新的结构性货币政策工具，稳妥推动科创金融改革试验区建设，持续提升金融服务科技创新的能力和水平。截至2024年3月末，高技术制造业中长期贷款、科技型中小企业贷款、“专精特新”企业贷款分别同比增长27.3%、20.4%、17.9%，明显高于各项贷款增速；科技型中小企业获贷率达到46.5%，较2017年末提升2倍；科创票据累计发行达5600亿元。下一步，中国人民银行将深入落实加大力度支持科技型企业融资行动方案，聚焦国家重大科技任务、科技型中小企业等重点领域及科技要素密集地区，完善金融支持政策体系和配套机制，丰富金融支持工具，全面提升金融机构和金融市场服务科技创新能力，建成与高水平科技自立自强目标高度适配的金融服务体系。 二、绿色金融乘势而上、先立后破，为推动全社会绿色发展和服务美丽中国建设提供高质量金融供给 党的十八大以来，以习近平同志为核心的党中央高度重视生态文明建设，将发展绿色金融作为推动实现碳达峰碳中和、建设美丽中国的重要举措，多次作出重要部署。推动全社会绿色低碳发展涉及行业多、投资周期长、资金需求大，需要充分发挥绿色金融的资源优化配置作用。绿色金融也提供了新的业务增长点，有利于金融机构有序调整资产配置，助力实现金融高质量发展。 中国人民银行始终将发展绿色金融作为重点工作，持续强化顶层设计和政策引领。截至2024年3月末，绿色贷款余额33.8万亿元，同比增长35.1%，连续三年保持30%以上增速；绿色债券累计发行超过3.6万亿元，余额超过1.9万亿元，市场规模位居世界前列，为保障国家能源安全、助力碳达峰碳中和提供有力支持。2024年4月，中国人民银行牵头出台《关于进一步强化金融支持绿色低碳发展的指导意见》，创设碳减排支持工具，创新碳中和债、可持续发展挂钩债券等产品，开展绿色金融国际合作交流，进一步推动绿色信贷、绿色债券等绿色融资较快增长。下一步，中国人民银行将统筹好对绿色发展和低碳转型的支持，发挥好碳减排支持工具的示范引领作用，不断完善绿色金融标准体系，稳步推进绿色金融产品和市场高质量发展，提升绿色金融服务质效和可持续性。 三、普惠金融雪中送炭、服务民生，构建多层次、广覆盖、可持续的普惠金融体系 习近平总书记就发展普惠金融多次作出部署，要求“始终坚持以人民为中心的发展思想，推进普惠金融高质量发展”。小微企业是发展的生力军、就业的主渠道，“三农”是经济社会发展的“压舱石”，民生领域是促进共同富裕的关键一环。发展普惠金融，让社会不同群体都平等享受基础金融服务，是金融工作政治性、人民性的重要体现，也是金融助力实现共同富裕的重要路径。 近年来，中国人民银行多措并举，持续加强民营小微、乡村振兴、民生等领域金融服务工作。牵头印发金融支持民营经济“25条举措”、《关于金融支持全面推进乡村振兴 加快建设农业强国的指导意见》等文件，用好用足支农支小再贷款，延续实施普惠小微贷款支持工具，持续开展中小微企业金融服务能力提升工程，调整优化创业担保贷款政策、助学贷款政策，提升普惠领域金融服务可得性和便利性，相关贷款实现“量增、面扩、价降”。截至2024年3月末，普惠小微贷款、涉农贷款、助学贷款分别同比增长20.3%、13.5%、22.5%，高于各项贷款增速；普惠小微授信户数超过6000万户，已覆盖三分之一的经营主体；2024年3月新发放普惠小微贷款加权平均利率4.36%，处于历史较低水平。下一步，中国人民银行将统筹兼顾增量扩面和商业可持续，落实落细相关政策，优化普惠重点领域产品和服务供给，健全多层次普惠金融机构组织体系，加快构建激励相容的普惠金融发展长效机制。 四、养老金融健全体系、增进福祉，助力积极应对人口老龄化国家战略实施 我国人口总量庞大，近年来人口老龄化程度加深。有效应对人口老龄化，事关国家发展全局，事关亿万百姓福祉。习近平总书记在中央金融工作会议上强调，要“加大对健康产业、养老产业、银发经济的财税金融政策支持，有针对性地丰富养老金融产品供给，积极发展第三支柱养老保险，更好满足日益多元化的养老金融需求”。近年来，中国人民银行多措并举加大金融对养老领域和银发经济的支持力度，牵头出台《关于金融支持养老服务业加快发展的指导意见》，推动普惠养老专项再贷款试点全面扩围，引导金融机构积极开展养老理财和特定养老储蓄试点工作，推动银行网点和线上服务亲老适老化改造，针对老年人等群体支付习惯提升支付便利化水平，相关工作取得成效。 下一步，中国人民银行将完善养老金融相关政策、业务、产品体系，推动多层次、多支柱养老保险体系建设，用好用足普惠养老专项再贷款工具，提升养老金融供求适配性和养老产业发展的资金供给水平，实现中国特色金融和养老事业高质量发展良性循环。 五、数字金融把握机遇、重视安全，构建与支撑金融强国建设和数字经济发展相适应的数字金融服务体系 习近平总书记指出“当今时代，数字技术、数字经济是世界科技革命和产业变革的先机，是新一轮国际竞争重点领域”。中央金融工作会议把数字金融提高到国家发展战略的新高度，作出明确部署。金融是数据密集型行业，数字技术历来是金融业发展的重要推动力。顺应数字经济时代变革，借助大数据、人工智能、云计算等数字技术，加快金融业数字化转型，有助于推动金融机构和金融市场提升服务效率，降低运行成本，增强服务实体经济和防范金融风险的能力。 近年来，中国人民银行加强数字金融顶层制度设计，实施金融数字化转型提升工程，深化实施金融科技创新监管工具，扎实推进数字人民币试点，实施金融科技赋能乡村振兴示范工程，有力推动了数字金融发展。下一步，中国人民银行将统筹发展和安全，发挥数据要素和数字技术双轮驱动作用，系统推进金融数字化转型，加强数字技术在科技金融、普惠金融、绿色金融、养老金融的赋能运用，稳妥推进数字人民币研发和应用，完善数字金融治理体系，提升金融服务的便利性和竞争力，助力金融强国建设和巩固拓展数字经济优势。 中国人民银行将与相关部门密切协作，全力做好“五篇大文章”，以高质量金融服务推动经济高质量发展，为奋力实现中国式现代化宏伟目标提供坚实有力的金融支撑。 法律声明 | 联系我们 | 设为首页 | 加入收藏 | 网站地图 京ICP备05073439号 网站标识码：bm25000001 京公网安备 11010202000016号 网站主办单位：中国人民银行办公厅　最佳分辨率：1024*768\\\"}\",\"summaryAnalysis\":\"{\\\"relevance\\\": {\\\"level\\\": \\\"strong\\\", \\\"detail\\\": \\\"养老金融单列成章，明确要求‘丰富养老金融产品供给’‘发展第三支柱养老保险’‘推动养老理财和特定养老储蓄试点’‘适老化支付改造’；文中直接关联保险业（提及‘股权、债权、保险等手段’服务科技企业）、商业养老保险、长期护理保险潜在场景，并强调‘健康产业、银发经济’的财税金融协同支持，为保险机构参与养老金体系、健康养老服务、养老社区金融配套提供顶层政策依据和业务拓', 0, '0:0:0:0:0:0:0:1', NULL, 'Mozilla/5.0 (iPhone; CPU iPhone OS 18_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.5 Mobile/15E148 Safari/604.1', 'mobile', 'macOS', 'Safari', 1, NULL, 26883, '2026-08-21 16:03:11', '2026-08-21 16:03:11', 'system', 'system', 0, NULL);
INSERT IGNORE INTO `system_log_agent` VALUES (698, '7a4411721b804602ae25c83f2a43b20b', 'agent', 'AG60785666', 'agent01', '文章转写', '执行审核', NULL, NULL, NULL, NULL, '/agent-api/tools/article-rewrite/7/audit', 'POST', '{\"id\":7}', '{\"code\":0,\"message\":\"success\",\"data\":{\"id\":7,\"toolCode\":\"TL90008\",\"agentCode\":\"AG60785666\",\"channelCode\":\"CH00001\",\"status\":\"AUDITED\",\"contentFetch\":\"{\\\"fetchTime\\\": \\\"2026-08-21T16:02:08.3381423\\\", \\\"sourceUrl\\\": \\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\", \\\"sourceType\\\": \\\"url\\\", \\\"fetchStatus\\\": \\\"success\\\", \\\"originalTitle\\\": \\\"扎实做好“五篇大文章” 推动金融高质量发展\\\", \\\"originalSource\\\": \\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\", \\\"originalContent\\\": \\\"扎实做好“五篇大文章” 推动金融高质量发展 （信贷市场司党支部） “为了提供高质量金融服务，金融系统要着力做好科技金融、绿色金融、普惠金融、养老金融、数字金融五篇大文章”。在中央金融工作会议上，习近平总书记对做好“五篇大文章”作出重要部署，擘画了以金融高质量发展助力国家重大战略实施和强国建设的宏伟蓝图，指明了金融支持经济高质量发展的发力点和经济金融结构优化的基本方向，是新时代新征程金融服务实体经济高质量发展的根本遵循和行动指南。“五篇大文章”各领域情况不同，金融服务方向各有侧重，需要坚持需求导向和问题导向，以深化金融供给侧结构性改革为主线，加强金融政策与产业政策协同配合，分类施策、系统推进，不断增强金融支持的力度、可持续性和专业化水平。 一、科技金融迎难而上、聚焦重点，加大对实现科技自立自强和科技强国建设的金融支持力度 习近平总书记多次强调，要“坚持创新在我国现代化建设全局中的核心地位，坚持把科技自立自强作为国家发展的战略支撑”“加快发展新质生产力”。金融与科技、产业形成良性循环，是推动科技创新和产业创新的重要力量。科技创新复杂多元，不同科创主体和活动、科技型企业成长生命周期不同阶段，金融需求差异较大，需要统筹运用好股权、债权、保险等手段为科技型企业提供全链条、全生命周期金融服务。 近年来，中国人民银行持续加强科技金融服务工作，牵头制定《加大力度支持科技型企业融资行动方案》，设立支持科技创新的结构性货币政策工具，稳妥推动科创金融改革试验区建设，持续提升金融服务科技创新的能力和水平。截至2024年3月末，高技术制造业中长期贷款、科技型中小企业贷款、“专精特新”企业贷款分别同比增长27.3%、20.4%、17.9%，明显高于各项贷款增速；科技型中小企业获贷率达到46.5%，较2017年末提升2倍；科创票据累计发行达5600亿元。下一步，中国人民银行将深入落实加大力度支持科技型企业融资行动方案，聚焦国家重大科技任务、科技型中小企业等重点领域及科技要素密集地区，完善金融支持政策体系和配套机制，丰富金融支持工具，全面提升金融机构和金融市场服务科技创新能力，建成与高水平科技自立自强目标高度适配的金融服务体系。 二、绿色金融乘势而上、先立后破，为推动全社会绿色发展和服务美丽中国建设提供高质量金融供给 党的十八大以来，以习近平同志为核心的党中央高度重视生态文明建设，将发展绿色金融作为推动实现碳达峰碳中和、建设美丽中国的重要举措，多次作出重要部署。推动全社会绿色低碳发展涉及行业多、投资周期长、资金需求大，需要充分发挥绿色金融的资源优化配置作用。绿色金融也提供了新的业务增长点，有利于金融机构有序调整资产配置，助力实现金融高质量发展。 中国人民银行始终将发展绿色金融作为重点工作，持续强化顶层设计和政策引领。截至2024年3月末，绿色贷款余额33.8万亿元，同比增长35.1%，连续三年保持30%以上增速；绿色债券累计发行超过3.6万亿元，余额超过1.9万亿元，市场规模位居世界前列，为保障国家能源安全、助力碳达峰碳中和提供有力支持。2024年4月，中国人民银行牵头出台《关于进一步强化金融支持绿色低碳发展的指导意见》，创设碳减排支持工具，创新碳中和债、可持续发展挂钩债券等产品，开展绿色金融国际合作交流，进一步推动绿色信贷、绿色债券等绿色融资较快增长。下一步，中国人民银行将统筹好对绿色发展和低碳转型的支持，发挥好碳减排支持工具的示范引领作用，不断完善绿色金融标准体系，稳步推进绿色金融产品和市场高质量发展，提升绿色金融服务质效和可持续性。 三、普惠金融雪中送炭、服务民生，构建多层次、广覆盖、可持续的普惠金融体系 习近平总书记就发展普惠金融多次作出部署，要求“始终坚持以人民为中心的发展思想，推进普惠金融高质量发展”。小微企业是发展的生力军、就业的主渠道，“三农”是经济社会发展的“压舱石”，民生领域是促进共同富裕的关键一环。发展普惠金融，让社会不同群体都平等享受基础金融服务，是金融工作政治性、人民性的重要体现，也是金融助力实现共同富裕的重要路径。 近年来，中国人民银行多措并举，持续加强民营小微、乡村振兴、民生等领域金融服务工作。牵头印发金融支持民营经济“25条举措”、《关于金融支持全面推进乡村振兴 加快建设农业强国的指导意见》等文件，用好用足支农支小再贷款，延续实施普惠小微贷款支持工具，持续开展中小微企业金融服务能力提升工程，调整优化创业担保贷款政策、助学贷款政策，提升普惠领域金融服务可得性和便利性，相关贷款实现“量增、面扩、价降”。截至2024年3月末，普惠小微贷款、涉农贷款、助学贷款分别同比增长20.3%、13.5%、22.5%，高于各项贷款增速；普惠小微授信户数超过6000万户，已覆盖三分之一的经营主体；2024年3月新发放普惠小微贷款加权平均利率4.36%，处于历史较低水平。下一步，中国人民银行将统筹兼顾增量扩面和商业可持续，落实落细相关政策，优化普惠重点领域产品和服务供给，健全多层次普惠金融机构组织体系，加快构建激励相容的普惠金融发展长效机制。 四、养老金融健全体系、增进福祉，助力积极应对人口老龄化国家战略实施 我国人口总量庞大，近年来人口老龄化程度加深。有效应对人口老龄化，事关国家发展全局，事关亿万百姓福祉。习近平总书记在中央金融工作会议上强调，要“加大对健康产业、养老产业、银发经济的财税金融政策支持，有针对性地丰富养老金融产品供给，积极发展第三支柱养老保险，更好满足日益多元化的养老金融需求”。近年来，中国人民银行多措并举加大金融对养老领域和银发经济的支持力度，牵头出台《关于金融支持养老服务业加快发展的指导意见》，推动普惠养老专项再贷款试点全面扩围，引导金融机构积极开展养老理财和特定养老储蓄试点工作，推动银行网点和线上服务亲老适老化改造，针对老年人等群体支付习惯提升支付便利化水平，相关工作取得成效。 下一步，中国人民银行将完善养老金融相关政策、业务、产品体系，推动多层次、多支柱养老保险体系建设，用好用足普惠养老专项再贷款工具，提升养老金融供求适配性和养老产业发展的资金供给水平，实现中国特色金融和养老事业高质量发展良性循环。 五、数字金融把握机遇、重视安全，构建与支撑金融强国建设和数字经济发展相适应的数字金融服务体系 习近平总书记指出“当今时代，数字技术、数字经济是世界科技革命和产业变革的先机，是新一轮国际竞争重点领域”。中央金融工作会议把数字金融提高到国家发展战略的新高度，作出明确部署。金融是数据密集型行业，数字技术历来是金融业发展的重要推动力。顺应数字经济时代变革，借助大数据、人工智能、云计算等数字技术，加快金融业数字化转型，有助于推动金融机构和金融市场提升服务效率，降低运行成本，增强服务实体经济和防范金融风险的能力。 近年来，中国人民银行加强数字金融顶层制度设计，实施金融数字化转型提升工程，深化实施金融科技创新监管工具，扎实推进数字人民币试点，实施金融科技赋能乡村振兴示范工程，有力推动了数字金融发展。下一步，中国人民银行将统筹发展和安全，发挥数据要素和数字技术双轮驱动作用，系统推进金融数字化转型，加强数字技术在科技金融、普惠金融、绿色金融、养老金融的赋能运用，稳妥推进数字人民币研发和应用，完善数字金融治理体系，提升金融服务的便利性和竞争力，助力金融强国建设和巩固拓展数字经济优势。 中国人民银行将与相关部门密切协作，全力做好“五篇大文章”，以高质量金融服务推动经济高质量发展，为奋力实现中国式现代化宏伟目标提供坚实有力的金融支撑。 法律声明 | 联系我们 | 设为首页 | 加入收藏 | 网站地图 京ICP备05073439号 网站标识码：bm25000001 京公网安备 11010202000016号 网站主办单位：中国人民银行办公厅　最佳分辨率：1024*768\\\"}\",\"summaryAnalysis\":\"{\\\"relevance\\\": {\\\"level\\\": \\\"strong\\\", \\\"detail\\\": \\\"养老金融单列成章，明确要求‘丰富养老金融产品供给’‘发展第三支柱养老保险’‘推动养老理财和特定养老储蓄试点’‘适老化支付改造’；文中直接关联保险业（提及‘股权、债权、保险等手段’服务科技企业）、商业养老保险、长期护理保险潜在场景，并强调‘健康产业、银发经济’的财税金融协同支持，为保险机构参与养老金体系、健康养老服务、养老社区金融配套提供顶层政策依据和业务拓展接', 0, '0:0:0:0:0:0:0:1', NULL, 'Mozilla/5.0 (iPhone; CPU iPhone OS 18_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.5 Mobile/15E148 Safari/604.1', 'mobile', 'macOS', 'Safari', 1, NULL, 66551, '2026-08-21 16:04:29', '2026-08-21 16:04:29', 'system', 'system', 0, NULL);
INSERT IGNORE INTO `system_log_agent` VALUES (699, 'ee10792d3f5841d0a41cc4c1b53f2b71', 'agent', 'AG60785666', 'agent01', '文章转写', '执行审核', NULL, NULL, NULL, NULL, '/agent-api/tools/article-rewrite/7/audit', 'POST', '{\"id\":7}', '{\"code\":0,\"message\":\"success\",\"data\":{\"id\":7,\"toolCode\":\"TL90008\",\"agentCode\":\"AG60785666\",\"channelCode\":\"CH00001\",\"status\":\"AUDITED\",\"contentFetch\":\"{\\\"fetchTime\\\": \\\"2026-08-21T16:02:08.3381423\\\", \\\"sourceUrl\\\": \\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\", \\\"sourceType\\\": \\\"url\\\", \\\"fetchStatus\\\": \\\"success\\\", \\\"originalTitle\\\": \\\"扎实做好“五篇大文章” 推动金融高质量发展\\\", \\\"originalSource\\\": \\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\", \\\"originalContent\\\": \\\"扎实做好“五篇大文章” 推动金融高质量发展 （信贷市场司党支部） “为了提供高质量金融服务，金融系统要着力做好科技金融、绿色金融、普惠金融、养老金融、数字金融五篇大文章”。在中央金融工作会议上，习近平总书记对做好“五篇大文章”作出重要部署，擘画了以金融高质量发展助力国家重大战略实施和强国建设的宏伟蓝图，指明了金融支持经济高质量发展的发力点和经济金融结构优化的基本方向，是新时代新征程金融服务实体经济高质量发展的根本遵循和行动指南。“五篇大文章”各领域情况不同，金融服务方向各有侧重，需要坚持需求导向和问题导向，以深化金融供给侧结构性改革为主线，加强金融政策与产业政策协同配合，分类施策、系统推进，不断增强金融支持的力度、可持续性和专业化水平。 一、科技金融迎难而上、聚焦重点，加大对实现科技自立自强和科技强国建设的金融支持力度 习近平总书记多次强调，要“坚持创新在我国现代化建设全局中的核心地位，坚持把科技自立自强作为国家发展的战略支撑”“加快发展新质生产力”。金融与科技、产业形成良性循环，是推动科技创新和产业创新的重要力量。科技创新复杂多元，不同科创主体和活动、科技型企业成长生命周期不同阶段，金融需求差异较大，需要统筹运用好股权、债权、保险等手段为科技型企业提供全链条、全生命周期金融服务。 近年来，中国人民银行持续加强科技金融服务工作，牵头制定《加大力度支持科技型企业融资行动方案》，设立支持科技创新的结构性货币政策工具，稳妥推动科创金融改革试验区建设，持续提升金融服务科技创新的能力和水平。截至2024年3月末，高技术制造业中长期贷款、科技型中小企业贷款、“专精特新”企业贷款分别同比增长27.3%、20.4%、17.9%，明显高于各项贷款增速；科技型中小企业获贷率达到46.5%，较2017年末提升2倍；科创票据累计发行达5600亿元。下一步，中国人民银行将深入落实加大力度支持科技型企业融资行动方案，聚焦国家重大科技任务、科技型中小企业等重点领域及科技要素密集地区，完善金融支持政策体系和配套机制，丰富金融支持工具，全面提升金融机构和金融市场服务科技创新能力，建成与高水平科技自立自强目标高度适配的金融服务体系。 二、绿色金融乘势而上、先立后破，为推动全社会绿色发展和服务美丽中国建设提供高质量金融供给 党的十八大以来，以习近平同志为核心的党中央高度重视生态文明建设，将发展绿色金融作为推动实现碳达峰碳中和、建设美丽中国的重要举措，多次作出重要部署。推动全社会绿色低碳发展涉及行业多、投资周期长、资金需求大，需要充分发挥绿色金融的资源优化配置作用。绿色金融也提供了新的业务增长点，有利于金融机构有序调整资产配置，助力实现金融高质量发展。 中国人民银行始终将发展绿色金融作为重点工作，持续强化顶层设计和政策引领。截至2024年3月末，绿色贷款余额33.8万亿元，同比增长35.1%，连续三年保持30%以上增速；绿色债券累计发行超过3.6万亿元，余额超过1.9万亿元，市场规模位居世界前列，为保障国家能源安全、助力碳达峰碳中和提供有力支持。2024年4月，中国人民银行牵头出台《关于进一步强化金融支持绿色低碳发展的指导意见》，创设碳减排支持工具，创新碳中和债、可持续发展挂钩债券等产品，开展绿色金融国际合作交流，进一步推动绿色信贷、绿色债券等绿色融资较快增长。下一步，中国人民银行将统筹好对绿色发展和低碳转型的支持，发挥好碳减排支持工具的示范引领作用，不断完善绿色金融标准体系，稳步推进绿色金融产品和市场高质量发展，提升绿色金融服务质效和可持续性。 三、普惠金融雪中送炭、服务民生，构建多层次、广覆盖、可持续的普惠金融体系 习近平总书记就发展普惠金融多次作出部署，要求“始终坚持以人民为中心的发展思想，推进普惠金融高质量发展”。小微企业是发展的生力军、就业的主渠道，“三农”是经济社会发展的“压舱石”，民生领域是促进共同富裕的关键一环。发展普惠金融，让社会不同群体都平等享受基础金融服务，是金融工作政治性、人民性的重要体现，也是金融助力实现共同富裕的重要路径。 近年来，中国人民银行多措并举，持续加强民营小微、乡村振兴、民生等领域金融服务工作。牵头印发金融支持民营经济“25条举措”、《关于金融支持全面推进乡村振兴 加快建设农业强国的指导意见》等文件，用好用足支农支小再贷款，延续实施普惠小微贷款支持工具，持续开展中小微企业金融服务能力提升工程，调整优化创业担保贷款政策、助学贷款政策，提升普惠领域金融服务可得性和便利性，相关贷款实现“量增、面扩、价降”。截至2024年3月末，普惠小微贷款、涉农贷款、助学贷款分别同比增长20.3%、13.5%、22.5%，高于各项贷款增速；普惠小微授信户数超过6000万户，已覆盖三分之一的经营主体；2024年3月新发放普惠小微贷款加权平均利率4.36%，处于历史较低水平。下一步，中国人民银行将统筹兼顾增量扩面和商业可持续，落实落细相关政策，优化普惠重点领域产品和服务供给，健全多层次普惠金融机构组织体系，加快构建激励相容的普惠金融发展长效机制。 四、养老金融健全体系、增进福祉，助力积极应对人口老龄化国家战略实施 我国人口总量庞大，近年来人口老龄化程度加深。有效应对人口老龄化，事关国家发展全局，事关亿万百姓福祉。习近平总书记在中央金融工作会议上强调，要“加大对健康产业、养老产业、银发经济的财税金融政策支持，有针对性地丰富养老金融产品供给，积极发展第三支柱养老保险，更好满足日益多元化的养老金融需求”。近年来，中国人民银行多措并举加大金融对养老领域和银发经济的支持力度，牵头出台《关于金融支持养老服务业加快发展的指导意见》，推动普惠养老专项再贷款试点全面扩围，引导金融机构积极开展养老理财和特定养老储蓄试点工作，推动银行网点和线上服务亲老适老化改造，针对老年人等群体支付习惯提升支付便利化水平，相关工作取得成效。 下一步，中国人民银行将完善养老金融相关政策、业务、产品体系，推动多层次、多支柱养老保险体系建设，用好用足普惠养老专项再贷款工具，提升养老金融供求适配性和养老产业发展的资金供给水平，实现中国特色金融和养老事业高质量发展良性循环。 五、数字金融把握机遇、重视安全，构建与支撑金融强国建设和数字经济发展相适应的数字金融服务体系 习近平总书记指出“当今时代，数字技术、数字经济是世界科技革命和产业变革的先机，是新一轮国际竞争重点领域”。中央金融工作会议把数字金融提高到国家发展战略的新高度，作出明确部署。金融是数据密集型行业，数字技术历来是金融业发展的重要推动力。顺应数字经济时代变革，借助大数据、人工智能、云计算等数字技术，加快金融业数字化转型，有助于推动金融机构和金融市场提升服务效率，降低运行成本，增强服务实体经济和防范金融风险的能力。 近年来，中国人民银行加强数字金融顶层制度设计，实施金融数字化转型提升工程，深化实施金融科技创新监管工具，扎实推进数字人民币试点，实施金融科技赋能乡村振兴示范工程，有力推动了数字金融发展。下一步，中国人民银行将统筹发展和安全，发挥数据要素和数字技术双轮驱动作用，系统推进金融数字化转型，加强数字技术在科技金融、普惠金融、绿色金融、养老金融的赋能运用，稳妥推进数字人民币研发和应用，完善数字金融治理体系，提升金融服务的便利性和竞争力，助力金融强国建设和巩固拓展数字经济优势。 中国人民银行将与相关部门密切协作，全力做好“五篇大文章”，以高质量金融服务推动经济高质量发展，为奋力实现中国式现代化宏伟目标提供坚实有力的金融支撑。 法律声明 | 联系我们 | 设为首页 | 加入收藏 | 网站地图 京ICP备05073439号 网站标识码：bm25000001 京公网安备 11010202000016号 网站主办单位：中国人民银行办公厅　最佳分辨率：1024*768\\\"}\",\"summaryAnalysis\":\"{\\\"relevance\\\": {\\\"level\\\": \\\"strong\\\", \\\"detail\\\": \\\"养老金融单列成章，明确要求‘丰富养老金融产品供给’‘发展第三支柱养老保险’‘推动养老理财和特定养老储蓄试点’‘适老化支付改造’；文中直接关联保险业（提及‘股权、债权、保险等手段’服务科技企业）、商业养老保险、长期护理保险潜在场景，并强调‘健康产业、银发经济’的财税金融协同支持，为保险机构参与养老金体系、健康养老服务、养老社区金融配套提供顶层政策依据和业务拓展接', 0, '0:0:0:0:0:0:0:1', NULL, 'Mozilla/5.0 (iPhone; CPU iPhone OS 18_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.5 Mobile/15E148 Safari/604.1', 'mobile', 'macOS', 'Safari', 1, NULL, 68619, '2026-08-21 16:05:35', '2026-08-21 16:05:35', 'system', 'system', 0, NULL);
INSERT IGNORE INTO `system_log_agent` VALUES (700, '44bf2b02a78740a1ae787500bedc6208', 'agent', 'AG60785666', 'agent01', '文章转写', '修复审核问题', NULL, NULL, NULL, NULL, '/agent-api/tools/article-rewrite/7/audit/fix', 'POST', '{\"id\":7,\"dto\":{\"itemIndexes\":[3,4,7,10,11,12,13,0,1,2,6,8,9]}}', '{\"code\":0,\"message\":\"success\",\"data\":{\"id\":7,\"toolCode\":\"TL90008\",\"agentCode\":\"AG60785666\",\"channelCode\":\"CH00001\",\"status\":\"AUDITED\",\"contentFetch\":\"{\\\"fetchTime\\\": \\\"2026-08-21T16:02:08.3381423\\\", \\\"sourceUrl\\\": \\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\", \\\"sourceType\\\": \\\"url\\\", \\\"fetchStatus\\\": \\\"success\\\", \\\"originalTitle\\\": \\\"扎实做好“五篇大文章” 推动金融高质量发展\\\", \\\"originalSource\\\": \\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\", \\\"originalContent\\\": \\\"扎实做好“五篇大文章” 推动金融高质量发展 （信贷市场司党支部） “为了提供高质量金融服务，金融系统要着力做好科技金融、绿色金融、普惠金融、养老金融、数字金融五篇大文章”。在中央金融工作会议上，习近平总书记对做好“五篇大文章”作出重要部署，擘画了以金融高质量发展助力国家重大战略实施和强国建设的宏伟蓝图，指明了金融支持经济高质量发展的发力点和经济金融结构优化的基本方向，是新时代新征程金融服务实体经济高质量发展的根本遵循和行动指南。“五篇大文章”各领域情况不同，金融服务方向各有侧重，需要坚持需求导向和问题导向，以深化金融供给侧结构性改革为主线，加强金融政策与产业政策协同配合，分类施策、系统推进，不断增强金融支持的力度、可持续性和专业化水平。 一、科技金融迎难而上、聚焦重点，加大对实现科技自立自强和科技强国建设的金融支持力度 习近平总书记多次强调，要“坚持创新在我国现代化建设全局中的核心地位，坚持把科技自立自强作为国家发展的战略支撑”“加快发展新质生产力”。金融与科技、产业形成良性循环，是推动科技创新和产业创新的重要力量。科技创新复杂多元，不同科创主体和活动、科技型企业成长生命周期不同阶段，金融需求差异较大，需要统筹运用好股权、债权、保险等手段为科技型企业提供全链条、全生命周期金融服务。 近年来，中国人民银行持续加强科技金融服务工作，牵头制定《加大力度支持科技型企业融资行动方案》，设立支持科技创新的结构性货币政策工具，稳妥推动科创金融改革试验区建设，持续提升金融服务科技创新的能力和水平。截至2024年3月末，高技术制造业中长期贷款、科技型中小企业贷款、“专精特新”企业贷款分别同比增长27.3%、20.4%、17.9%，明显高于各项贷款增速；科技型中小企业获贷率达到46.5%，较2017年末提升2倍；科创票据累计发行达5600亿元。下一步，中国人民银行将深入落实加大力度支持科技型企业融资行动方案，聚焦国家重大科技任务、科技型中小企业等重点领域及科技要素密集地区，完善金融支持政策体系和配套机制，丰富金融支持工具，全面提升金融机构和金融市场服务科技创新能力，建成与高水平科技自立自强目标高度适配的金融服务体系。 二、绿色金融乘势而上、先立后破，为推动全社会绿色发展和服务美丽中国建设提供高质量金融供给 党的十八大以来，以习近平同志为核心的党中央高度重视生态文明建设，将发展绿色金融作为推动实现碳达峰碳中和、建设美丽中国的重要举措，多次作出重要部署。推动全社会绿色低碳发展涉及行业多、投资周期长、资金需求大，需要充分发挥绿色金融的资源优化配置作用。绿色金融也提供了新的业务增长点，有利于金融机构有序调整资产配置，助力实现金融高质量发展。 中国人民银行始终将发展绿色金融作为重点工作，持续强化顶层设计和政策引领。截至2024年3月末，绿色贷款余额33.8万亿元，同比增长35.1%，连续三年保持30%以上增速；绿色债券累计发行超过3.6万亿元，余额超过1.9万亿元，市场规模位居世界前列，为保障国家能源安全、助力碳达峰碳中和提供有力支持。2024年4月，中国人民银行牵头出台《关于进一步强化金融支持绿色低碳发展的指导意见》，创设碳减排支持工具，创新碳中和债、可持续发展挂钩债券等产品，开展绿色金融国际合作交流，进一步推动绿色信贷、绿色债券等绿色融资较快增长。下一步，中国人民银行将统筹好对绿色发展和低碳转型的支持，发挥好碳减排支持工具的示范引领作用，不断完善绿色金融标准体系，稳步推进绿色金融产品和市场高质量发展，提升绿色金融服务质效和可持续性。 三、普惠金融雪中送炭、服务民生，构建多层次、广覆盖、可持续的普惠金融体系 习近平总书记就发展普惠金融多次作出部署，要求“始终坚持以人民为中心的发展思想，推进普惠金融高质量发展”。小微企业是发展的生力军、就业的主渠道，“三农”是经济社会发展的“压舱石”，民生领域是促进共同富裕的关键一环。发展普惠金融，让社会不同群体都平等享受基础金融服务，是金融工作政治性、人民性的重要体现，也是金融助力实现共同富裕的重要路径。 近年来，中国人民银行多措并举，持续加强民营小微、乡村振兴、民生等领域金融服务工作。牵头印发金融支持民营经济“25条举措”、《关于金融支持全面推进乡村振兴 加快建设农业强国的指导意见》等文件，用好用足支农支小再贷款，延续实施普惠小微贷款支持工具，持续开展中小微企业金融服务能力提升工程，调整优化创业担保贷款政策、助学贷款政策，提升普惠领域金融服务可得性和便利性，相关贷款实现“量增、面扩、价降”。截至2024年3月末，普惠小微贷款、涉农贷款、助学贷款分别同比增长20.3%、13.5%、22.5%，高于各项贷款增速；普惠小微授信户数超过6000万户，已覆盖三分之一的经营主体；2024年3月新发放普惠小微贷款加权平均利率4.36%，处于历史较低水平。下一步，中国人民银行将统筹兼顾增量扩面和商业可持续，落实落细相关政策，优化普惠重点领域产品和服务供给，健全多层次普惠金融机构组织体系，加快构建激励相容的普惠金融发展长效机制。 四、养老金融健全体系、增进福祉，助力积极应对人口老龄化国家战略实施 我国人口总量庞大，近年来人口老龄化程度加深。有效应对人口老龄化，事关国家发展全局，事关亿万百姓福祉。习近平总书记在中央金融工作会议上强调，要“加大对健康产业、养老产业、银发经济的财税金融政策支持，有针对性地丰富养老金融产品供给，积极发展第三支柱养老保险，更好满足日益多元化的养老金融需求”。近年来，中国人民银行多措并举加大金融对养老领域和银发经济的支持力度，牵头出台《关于金融支持养老服务业加快发展的指导意见》，推动普惠养老专项再贷款试点全面扩围，引导金融机构积极开展养老理财和特定养老储蓄试点工作，推动银行网点和线上服务亲老适老化改造，针对老年人等群体支付习惯提升支付便利化水平，相关工作取得成效。 下一步，中国人民银行将完善养老金融相关政策、业务、产品体系，推动多层次、多支柱养老保险体系建设，用好用足普惠养老专项再贷款工具，提升养老金融供求适配性和养老产业发展的资金供给水平，实现中国特色金融和养老事业高质量发展良性循环。 五、数字金融把握机遇、重视安全，构建与支撑金融强国建设和数字经济发展相适应的数字金融服务体系 习近平总书记指出“当今时代，数字技术、数字经济是世界科技革命和产业变革的先机，是新一轮国际竞争重点领域”。中央金融工作会议把数字金融提高到国家发展战略的新高度，作出明确部署。金融是数据密集型行业，数字技术历来是金融业发展的重要推动力。顺应数字经济时代变革，借助大数据、人工智能、云计算等数字技术，加快金融业数字化转型，有助于推动金融机构和金融市场提升服务效率，降低运行成本，增强服务实体经济和防范金融风险的能力。 近年来，中国人民银行加强数字金融顶层制度设计，实施金融数字化转型提升工程，深化实施金融科技创新监管工具，扎实推进数字人民币试点，实施金融科技赋能乡村振兴示范工程，有力推动了数字金融发展。下一步，中国人民银行将统筹发展和安全，发挥数据要素和数字技术双轮驱动作用，系统推进金融数字化转型，加强数字技术在科技金融、普惠金融、绿色金融、养老金融的赋能运用，稳妥推进数字人民币研发和应用，完善数字金融治理体系，提升金融服务的便利性和竞争力，助力金融强国建设和巩固拓展数字经济优势。 中国人民银行将与相关部门密切协作，全力做好“五篇大文章”，以高质量金融服务推动经济高质量发展，为奋力实现中国式现代化宏伟目标提供坚实有力的金融支撑。 法律声明 | 联系我们 | 设为首页 | 加入收藏 | 网站地图 京ICP备05073439号 网站标识码：bm25000001 京公网安备 11010202000016号 网站主办单位：中国人民银行办公厅　最佳分辨率：1024*768\\\"}\",\"summaryAnalysis\":\"{\\\"relevance\\\": {\\\"level\\\": \\\"strong\\\", \\\"detail\\\": \\\"养老金融单列成章，明确要求‘丰富养老金融产品供给’‘发展第三支柱养老保险’‘推动养老理财和特定养老储蓄试点’‘适老化支付改造’；文中直接关联保险业（提及‘股权、债权、保险等手段’服务科技企业）、商业养老保险、长期护理保险潜在场景，并强调‘健康产业、银发经济’的财税金融协同支持，为保险机构参与养老金体系、健康养老服务、养老社区金融配套提供顶层政策依据和业务拓展接', 0, '0:0:0:0:0:0:0:1', NULL, 'Mozilla/5.0 (iPhone; CPU iPhone OS 18_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.5 Mobile/15E148 Safari/604.1', 'mobile', 'macOS', 'Safari', 1, NULL, 61, '2026-08-21 16:07:37', '2026-08-21 16:07:37', 'system', 'system', 0, NULL);
INSERT IGNORE INTO `system_log_agent` VALUES (701, 'ab1d6a7c24c04d39b1cd25c17f929599', 'agent', 'AG60785666', 'agent01', '文章转写', '执行审核', NULL, NULL, NULL, NULL, '/agent-api/tools/article-rewrite/7/audit', 'POST', '{\"id\":7}', NULL, 1, '0:0:0:0:0:0:0:1', NULL, 'Mozilla/5.0 (iPhone; CPU iPhone OS 18_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.5 Mobile/15E148 Safari/604.1', 'mobile', 'macOS', 'Safari', 0, '当前阶段不允许该操作', 24, '2026-08-21 16:09:43', '2026-08-21 16:09:43', 'system', 'system', 0, NULL);
INSERT IGNORE INTO `system_log_agent` VALUES (702, '0287319916d14141a6437a3824783943', 'agent', 'AG60785666', 'agent01', '文章转写', '修复审核问题', NULL, NULL, NULL, NULL, '/agent-api/tools/article-rewrite/7/audit/fix', 'POST', '{\"id\":7,\"dto\":{\"itemIndexes\":[3,4,7,10,11,12,13]}}', '{\"code\":0,\"message\":\"success\",\"data\":{\"id\":7,\"toolCode\":\"TL90008\",\"agentCode\":\"AG60785666\",\"channelCode\":\"CH00001\",\"status\":\"AUDITED\",\"contentFetch\":\"{\\\"fetchTime\\\": \\\"2026-08-21T16:02:08.3381423\\\", \\\"sourceUrl\\\": \\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\", \\\"sourceType\\\": \\\"url\\\", \\\"fetchStatus\\\": \\\"success\\\", \\\"originalTitle\\\": \\\"扎实做好“五篇大文章” 推动金融高质量发展\\\", \\\"originalSource\\\": \\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\", \\\"originalContent\\\": \\\"扎实做好“五篇大文章” 推动金融高质量发展 （信贷市场司党支部） “为了提供高质量金融服务，金融系统要着力做好科技金融、绿色金融、普惠金融、养老金融、数字金融五篇大文章”。在中央金融工作会议上，习近平总书记对做好“五篇大文章”作出重要部署，擘画了以金融高质量发展助力国家重大战略实施和强国建设的宏伟蓝图，指明了金融支持经济高质量发展的发力点和经济金融结构优化的基本方向，是新时代新征程金融服务实体经济高质量发展的根本遵循和行动指南。“五篇大文章”各领域情况不同，金融服务方向各有侧重，需要坚持需求导向和问题导向，以深化金融供给侧结构性改革为主线，加强金融政策与产业政策协同配合，分类施策、系统推进，不断增强金融支持的力度、可持续性和专业化水平。 一、科技金融迎难而上、聚焦重点，加大对实现科技自立自强和科技强国建设的金融支持力度 习近平总书记多次强调，要“坚持创新在我国现代化建设全局中的核心地位，坚持把科技自立自强作为国家发展的战略支撑”“加快发展新质生产力”。金融与科技、产业形成良性循环，是推动科技创新和产业创新的重要力量。科技创新复杂多元，不同科创主体和活动、科技型企业成长生命周期不同阶段，金融需求差异较大，需要统筹运用好股权、债权、保险等手段为科技型企业提供全链条、全生命周期金融服务。 近年来，中国人民银行持续加强科技金融服务工作，牵头制定《加大力度支持科技型企业融资行动方案》，设立支持科技创新的结构性货币政策工具，稳妥推动科创金融改革试验区建设，持续提升金融服务科技创新的能力和水平。截至2024年3月末，高技术制造业中长期贷款、科技型中小企业贷款、“专精特新”企业贷款分别同比增长27.3%、20.4%、17.9%，明显高于各项贷款增速；科技型中小企业获贷率达到46.5%，较2017年末提升2倍；科创票据累计发行达5600亿元。下一步，中国人民银行将深入落实加大力度支持科技型企业融资行动方案，聚焦国家重大科技任务、科技型中小企业等重点领域及科技要素密集地区，完善金融支持政策体系和配套机制，丰富金融支持工具，全面提升金融机构和金融市场服务科技创新能力，建成与高水平科技自立自强目标高度适配的金融服务体系。 二、绿色金融乘势而上、先立后破，为推动全社会绿色发展和服务美丽中国建设提供高质量金融供给 党的十八大以来，以习近平同志为核心的党中央高度重视生态文明建设，将发展绿色金融作为推动实现碳达峰碳中和、建设美丽中国的重要举措，多次作出重要部署。推动全社会绿色低碳发展涉及行业多、投资周期长、资金需求大，需要充分发挥绿色金融的资源优化配置作用。绿色金融也提供了新的业务增长点，有利于金融机构有序调整资产配置，助力实现金融高质量发展。 中国人民银行始终将发展绿色金融作为重点工作，持续强化顶层设计和政策引领。截至2024年3月末，绿色贷款余额33.8万亿元，同比增长35.1%，连续三年保持30%以上增速；绿色债券累计发行超过3.6万亿元，余额超过1.9万亿元，市场规模位居世界前列，为保障国家能源安全、助力碳达峰碳中和提供有力支持。2024年4月，中国人民银行牵头出台《关于进一步强化金融支持绿色低碳发展的指导意见》，创设碳减排支持工具，创新碳中和债、可持续发展挂钩债券等产品，开展绿色金融国际合作交流，进一步推动绿色信贷、绿色债券等绿色融资较快增长。下一步，中国人民银行将统筹好对绿色发展和低碳转型的支持，发挥好碳减排支持工具的示范引领作用，不断完善绿色金融标准体系，稳步推进绿色金融产品和市场高质量发展，提升绿色金融服务质效和可持续性。 三、普惠金融雪中送炭、服务民生，构建多层次、广覆盖、可持续的普惠金融体系 习近平总书记就发展普惠金融多次作出部署，要求“始终坚持以人民为中心的发展思想，推进普惠金融高质量发展”。小微企业是发展的生力军、就业的主渠道，“三农”是经济社会发展的“压舱石”，民生领域是促进共同富裕的关键一环。发展普惠金融，让社会不同群体都平等享受基础金融服务，是金融工作政治性、人民性的重要体现，也是金融助力实现共同富裕的重要路径。 近年来，中国人民银行多措并举，持续加强民营小微、乡村振兴、民生等领域金融服务工作。牵头印发金融支持民营经济“25条举措”、《关于金融支持全面推进乡村振兴 加快建设农业强国的指导意见》等文件，用好用足支农支小再贷款，延续实施普惠小微贷款支持工具，持续开展中小微企业金融服务能力提升工程，调整优化创业担保贷款政策、助学贷款政策，提升普惠领域金融服务可得性和便利性，相关贷款实现“量增、面扩、价降”。截至2024年3月末，普惠小微贷款、涉农贷款、助学贷款分别同比增长20.3%、13.5%、22.5%，高于各项贷款增速；普惠小微授信户数超过6000万户，已覆盖三分之一的经营主体；2024年3月新发放普惠小微贷款加权平均利率4.36%，处于历史较低水平。下一步，中国人民银行将统筹兼顾增量扩面和商业可持续，落实落细相关政策，优化普惠重点领域产品和服务供给，健全多层次普惠金融机构组织体系，加快构建激励相容的普惠金融发展长效机制。 四、养老金融健全体系、增进福祉，助力积极应对人口老龄化国家战略实施 我国人口总量庞大，近年来人口老龄化程度加深。有效应对人口老龄化，事关国家发展全局，事关亿万百姓福祉。习近平总书记在中央金融工作会议上强调，要“加大对健康产业、养老产业、银发经济的财税金融政策支持，有针对性地丰富养老金融产品供给，积极发展第三支柱养老保险，更好满足日益多元化的养老金融需求”。近年来，中国人民银行多措并举加大金融对养老领域和银发经济的支持力度，牵头出台《关于金融支持养老服务业加快发展的指导意见》，推动普惠养老专项再贷款试点全面扩围，引导金融机构积极开展养老理财和特定养老储蓄试点工作，推动银行网点和线上服务亲老适老化改造，针对老年人等群体支付习惯提升支付便利化水平，相关工作取得成效。 下一步，中国人民银行将完善养老金融相关政策、业务、产品体系，推动多层次、多支柱养老保险体系建设，用好用足普惠养老专项再贷款工具，提升养老金融供求适配性和养老产业发展的资金供给水平，实现中国特色金融和养老事业高质量发展良性循环。 五、数字金融把握机遇、重视安全，构建与支撑金融强国建设和数字经济发展相适应的数字金融服务体系 习近平总书记指出“当今时代，数字技术、数字经济是世界科技革命和产业变革的先机，是新一轮国际竞争重点领域”。中央金融工作会议把数字金融提高到国家发展战略的新高度，作出明确部署。金融是数据密集型行业，数字技术历来是金融业发展的重要推动力。顺应数字经济时代变革，借助大数据、人工智能、云计算等数字技术，加快金融业数字化转型，有助于推动金融机构和金融市场提升服务效率，降低运行成本，增强服务实体经济和防范金融风险的能力。 近年来，中国人民银行加强数字金融顶层制度设计，实施金融数字化转型提升工程，深化实施金融科技创新监管工具，扎实推进数字人民币试点，实施金融科技赋能乡村振兴示范工程，有力推动了数字金融发展。下一步，中国人民银行将统筹发展和安全，发挥数据要素和数字技术双轮驱动作用，系统推进金融数字化转型，加强数字技术在科技金融、普惠金融、绿色金融、养老金融的赋能运用，稳妥推进数字人民币研发和应用，完善数字金融治理体系，提升金融服务的便利性和竞争力，助力金融强国建设和巩固拓展数字经济优势。 中国人民银行将与相关部门密切协作，全力做好“五篇大文章”，以高质量金融服务推动经济高质量发展，为奋力实现中国式现代化宏伟目标提供坚实有力的金融支撑。 法律声明 | 联系我们 | 设为首页 | 加入收藏 | 网站地图 京ICP备05073439号 网站标识码：bm25000001 京公网安备 11010202000016号 网站主办单位：中国人民银行办公厅　最佳分辨率：1024*768\\\"}\",\"summaryAnalysis\":\"{\\\"relevance\\\": {\\\"level\\\": \\\"strong\\\", \\\"detail\\\": \\\"养老金融单列成章，明确要求‘丰富养老金融产品供给’‘发展第三支柱养老保险’‘推动养老理财和特定养老储蓄试点’‘适老化支付改造’；文中直接关联保险业（提及‘股权、债权、保险等手段’服务科技企业）、商业养老保险、长期护理保险潜在场景，并强调‘健康产业、银发经济’的财税金融协同支持，为保险机构参与养老金体系、健康养老服务、养老社区金融配套提供顶层政策依据和业务拓展接', 0, '0:0:0:0:0:0:0:1', NULL, 'Mozilla/5.0 (iPhone; CPU iPhone OS 18_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.5 Mobile/15E148 Safari/604.1', 'mobile', 'macOS', 'Safari', 1, NULL, 28, '2026-08-21 16:10:14', '2026-08-21 16:10:14', 'system', 'system', 0, NULL);
INSERT IGNORE INTO `system_log_agent` VALUES (703, '70d186e9aae846809d9d3340bf572810', 'agent', 'AG60785666', 'agent01', '文章转写', '执行审核', NULL, NULL, NULL, NULL, '/agent-api/tools/article-rewrite/7/audit', 'POST', '{\"id\":7}', NULL, 1, '0:0:0:0:0:0:0:1', NULL, 'Mozilla/5.0 (iPhone; CPU iPhone OS 18_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.5 Mobile/15E148 Safari/604.1', 'mobile', 'macOS', 'Safari', 0, '当前阶段不允许该操作', 12, '2026-08-21 16:10:18', '2026-08-21 16:10:18', 'system', 'system', 0, NULL);
INSERT IGNORE INTO `system_log_agent` VALUES (704, 'bbfcd1b934884beca5fa23829a40a0d6', 'agent', 'AG60785666', 'agent01', '文章转写', '生成配图', NULL, NULL, NULL, NULL, '/agent-api/tools/article-rewrite/7/images/generate', 'POST', '{\"id\":7}', '{\"code\":0,\"message\":\"success\",\"data\":{\"id\":7,\"toolCode\":\"TL90008\",\"agentCode\":\"AG60785666\",\"channelCode\":\"CH00001\",\"status\":\"IMAGED\",\"contentFetch\":\"{\\\"fetchTime\\\": \\\"2026-08-21T16:02:08.3381423\\\", \\\"sourceUrl\\\": \\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\", \\\"sourceType\\\": \\\"url\\\", \\\"fetchStatus\\\": \\\"success\\\", \\\"originalTitle\\\": \\\"扎实做好“五篇大文章” 推动金融高质量发展\\\", \\\"originalSource\\\": \\\"https://www.pbc.gov.cn/redianzhuanti/118742/5358368/5370662/index.html\\\", \\\"originalContent\\\": \\\"扎实做好“五篇大文章” 推动金融高质量发展 （信贷市场司党支部） “为了提供高质量金融服务，金融系统要着力做好科技金融、绿色金融、普惠金融、养老金融、数字金融五篇大文章”。在中央金融工作会议上，习近平总书记对做好“五篇大文章”作出重要部署，擘画了以金融高质量发展助力国家重大战略实施和强国建设的宏伟蓝图，指明了金融支持经济高质量发展的发力点和经济金融结构优化的基本方向，是新时代新征程金融服务实体经济高质量发展的根本遵循和行动指南。“五篇大文章”各领域情况不同，金融服务方向各有侧重，需要坚持需求导向和问题导向，以深化金融供给侧结构性改革为主线，加强金融政策与产业政策协同配合，分类施策、系统推进，不断增强金融支持的力度、可持续性和专业化水平。 一、科技金融迎难而上、聚焦重点，加大对实现科技自立自强和科技强国建设的金融支持力度 习近平总书记多次强调，要“坚持创新在我国现代化建设全局中的核心地位，坚持把科技自立自强作为国家发展的战略支撑”“加快发展新质生产力”。金融与科技、产业形成良性循环，是推动科技创新和产业创新的重要力量。科技创新复杂多元，不同科创主体和活动、科技型企业成长生命周期不同阶段，金融需求差异较大，需要统筹运用好股权、债权、保险等手段为科技型企业提供全链条、全生命周期金融服务。 近年来，中国人民银行持续加强科技金融服务工作，牵头制定《加大力度支持科技型企业融资行动方案》，设立支持科技创新的结构性货币政策工具，稳妥推动科创金融改革试验区建设，持续提升金融服务科技创新的能力和水平。截至2024年3月末，高技术制造业中长期贷款、科技型中小企业贷款、“专精特新”企业贷款分别同比增长27.3%、20.4%、17.9%，明显高于各项贷款增速；科技型中小企业获贷率达到46.5%，较2017年末提升2倍；科创票据累计发行达5600亿元。下一步，中国人民银行将深入落实加大力度支持科技型企业融资行动方案，聚焦国家重大科技任务、科技型中小企业等重点领域及科技要素密集地区，完善金融支持政策体系和配套机制，丰富金融支持工具，全面提升金融机构和金融市场服务科技创新能力，建成与高水平科技自立自强目标高度适配的金融服务体系。 二、绿色金融乘势而上、先立后破，为推动全社会绿色发展和服务美丽中国建设提供高质量金融供给 党的十八大以来，以习近平同志为核心的党中央高度重视生态文明建设，将发展绿色金融作为推动实现碳达峰碳中和、建设美丽中国的重要举措，多次作出重要部署。推动全社会绿色低碳发展涉及行业多、投资周期长、资金需求大，需要充分发挥绿色金融的资源优化配置作用。绿色金融也提供了新的业务增长点，有利于金融机构有序调整资产配置，助力实现金融高质量发展。 中国人民银行始终将发展绿色金融作为重点工作，持续强化顶层设计和政策引领。截至2024年3月末，绿色贷款余额33.8万亿元，同比增长35.1%，连续三年保持30%以上增速；绿色债券累计发行超过3.6万亿元，余额超过1.9万亿元，市场规模位居世界前列，为保障国家能源安全、助力碳达峰碳中和提供有力支持。2024年4月，中国人民银行牵头出台《关于进一步强化金融支持绿色低碳发展的指导意见》，创设碳减排支持工具，创新碳中和债、可持续发展挂钩债券等产品，开展绿色金融国际合作交流，进一步推动绿色信贷、绿色债券等绿色融资较快增长。下一步，中国人民银行将统筹好对绿色发展和低碳转型的支持，发挥好碳减排支持工具的示范引领作用，不断完善绿色金融标准体系，稳步推进绿色金融产品和市场高质量发展，提升绿色金融服务质效和可持续性。 三、普惠金融雪中送炭、服务民生，构建多层次、广覆盖、可持续的普惠金融体系 习近平总书记就发展普惠金融多次作出部署，要求“始终坚持以人民为中心的发展思想，推进普惠金融高质量发展”。小微企业是发展的生力军、就业的主渠道，“三农”是经济社会发展的“压舱石”，民生领域是促进共同富裕的关键一环。发展普惠金融，让社会不同群体都平等享受基础金融服务，是金融工作政治性、人民性的重要体现，也是金融助力实现共同富裕的重要路径。 近年来，中国人民银行多措并举，持续加强民营小微、乡村振兴、民生等领域金融服务工作。牵头印发金融支持民营经济“25条举措”、《关于金融支持全面推进乡村振兴 加快建设农业强国的指导意见》等文件，用好用足支农支小再贷款，延续实施普惠小微贷款支持工具，持续开展中小微企业金融服务能力提升工程，调整优化创业担保贷款政策、助学贷款政策，提升普惠领域金融服务可得性和便利性，相关贷款实现“量增、面扩、价降”。截至2024年3月末，普惠小微贷款、涉农贷款、助学贷款分别同比增长20.3%、13.5%、22.5%，高于各项贷款增速；普惠小微授信户数超过6000万户，已覆盖三分之一的经营主体；2024年3月新发放普惠小微贷款加权平均利率4.36%，处于历史较低水平。下一步，中国人民银行将统筹兼顾增量扩面和商业可持续，落实落细相关政策，优化普惠重点领域产品和服务供给，健全多层次普惠金融机构组织体系，加快构建激励相容的普惠金融发展长效机制。 四、养老金融健全体系、增进福祉，助力积极应对人口老龄化国家战略实施 我国人口总量庞大，近年来人口老龄化程度加深。有效应对人口老龄化，事关国家发展全局，事关亿万百姓福祉。习近平总书记在中央金融工作会议上强调，要“加大对健康产业、养老产业、银发经济的财税金融政策支持，有针对性地丰富养老金融产品供给，积极发展第三支柱养老保险，更好满足日益多元化的养老金融需求”。近年来，中国人民银行多措并举加大金融对养老领域和银发经济的支持力度，牵头出台《关于金融支持养老服务业加快发展的指导意见》，推动普惠养老专项再贷款试点全面扩围，引导金融机构积极开展养老理财和特定养老储蓄试点工作，推动银行网点和线上服务亲老适老化改造，针对老年人等群体支付习惯提升支付便利化水平，相关工作取得成效。 下一步，中国人民银行将完善养老金融相关政策、业务、产品体系，推动多层次、多支柱养老保险体系建设，用好用足普惠养老专项再贷款工具，提升养老金融供求适配性和养老产业发展的资金供给水平，实现中国特色金融和养老事业高质量发展良性循环。 五、数字金融把握机遇、重视安全，构建与支撑金融强国建设和数字经济发展相适应的数字金融服务体系 习近平总书记指出“当今时代，数字技术、数字经济是世界科技革命和产业变革的先机，是新一轮国际竞争重点领域”。中央金融工作会议把数字金融提高到国家发展战略的新高度，作出明确部署。金融是数据密集型行业，数字技术历来是金融业发展的重要推动力。顺应数字经济时代变革，借助大数据、人工智能、云计算等数字技术，加快金融业数字化转型，有助于推动金融机构和金融市场提升服务效率，降低运行成本，增强服务实体经济和防范金融风险的能力。 近年来，中国人民银行加强数字金融顶层制度设计，实施金融数字化转型提升工程，深化实施金融科技创新监管工具，扎实推进数字人民币试点，实施金融科技赋能乡村振兴示范工程，有力推动了数字金融发展。下一步，中国人民银行将统筹发展和安全，发挥数据要素和数字技术双轮驱动作用，系统推进金融数字化转型，加强数字技术在科技金融、普惠金融、绿色金融、养老金融的赋能运用，稳妥推进数字人民币研发和应用，完善数字金融治理体系，提升金融服务的便利性和竞争力，助力金融强国建设和巩固拓展数字经济优势。 中国人民银行将与相关部门密切协作，全力做好“五篇大文章”，以高质量金融服务推动经济高质量发展，为奋力实现中国式现代化宏伟目标提供坚实有力的金融支撑。 法律声明 | 联系我们 | 设为首页 | 加入收藏 | 网站地图 京ICP备05073439号 网站标识码：bm25000001 京公网安备 11010202000016号 网站主办单位：中国人民银行办公厅　最佳分辨率：1024*768\\\"}\",\"summaryAnalysis\":\"{\\\"relevance\\\": {\\\"level\\\": \\\"strong\\\", \\\"detail\\\": \\\"养老金融单列成章，明确要求‘丰富养老金融产品供给’‘发展第三支柱养老保险’‘推动养老理财和特定养老储蓄试点’‘适老化支付改造’；文中直接关联保险业（提及‘股权、债权、保险等手段’服务科技企业）、商业养老保险、长期护理保险潜在场景，并强调‘健康产业、银发经济’的财税金融协同支持，为保险机构参与养老金体系、健康养老服务、养老社区金融配套提供顶层政策依据和业务拓展接口', 0, '0:0:0:0:0:0:0:1', NULL, 'Mozilla/5.0 (iPhone; CPU iPhone OS 18_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.5 Mobile/15E148 Safari/604.1', 'mobile', 'macOS', 'Safari', 1, NULL, 64, '2026-08-21 16:11:38', '2026-08-21 16:11:38', 'system', 'system', 0, NULL);
INSERT IGNORE INTO `system_log_agent` VALUES (705, '4e2725e90eb84280a9219306b7998a76', 'agent', 'AG60785666', 'agent01', '文章转写', '保存到内容库', NULL, NULL, NULL, NULL, '/agent-api/tools/article-rewrite/7/save-to-content', 'POST', '{\"id\":7,\"body\":{\"title\":\"养老金融不是‘补缺口’，而是新蓝海：第三支柱扩容下的保险机构战略升维\",\"summary\":\"本文深度解读养老金融新定位：第三支柱扩容与普惠养老再贷款双轮驱动下，保险机构如何通过‘产品+服务+资产’耦合，实现从风险承担者到养老生态组织者的战略升维。\",\"body\":\"文｜金融深度观察组\\n\\n当人口老龄化从‘趋势’变成‘现实’，养老金融正悄然完成一次范式跃迁——它不再只是社保体系的‘兜底补充’，而是一片政策密集落地、居民养老储备意愿持续上升、产品形态加速分化的真实增长市场。\\n\\n中央金融工作会议首次将‘养老金融’列为‘五篇大文章’之一，并明确提出‘积极发展第三支柱养老保险’‘有针对性地丰富养老金融产品供给’。这不是一句口号，而是一场涉及调整长期负债久期匹配养老资金属性、搭建覆盖健康管理与社区服务的协同供给网络、建设适老化客户运营系统的系统性升级。\\n\\n▍一、第三支柱扩容：从‘有没有’到‘好不好’\\n\\n过去几年，个人养老金制度落地、税优账户开立、基金/保险/理财/储蓄四类产品齐上阵，完成了‘从0到1’的破冰。但截至2024年一季度，个人养老金账户缴存规模仍不足千亿元，参与率偏低、产品同质化、长期持有黏性弱等问题依然突出。\\n\\n政策重点已转向——政策工具正在从‘鼓励参与’转向‘通过差异化激励措施提升参与实效’。中国人民银行牵头推动的‘普惠养老专项再贷款’已全面扩围，利率低至1.75%，期限最长3年，专门支持金融机构向符合条件的养老机构发放贷款，并明确要求资金用于发展普惠型养老服务、建设适老化设施、开发养老金融产品等方向。\\n\\n对保险机构而言，这不仅是低成本长期资金来源，更是资产端与负债端协同优化的关键支点：用再贷款资金配置优质养老社区股权/债权，反哺养老保险产品设计（如‘保单+入住权’挂钩），实现‘资产端配置优质养老实体资产以提升久期匹配度，负债端通过服务权益绑定强化长期保障功能，客户运营依托服务使用频次提升续保与加保意愿’的闭环。\\n\\n▍二、双轨并进：养老理财+特定养老储蓄，倒逼保险产品再定义\\n\\n当前，养老金融供给呈现‘三足鼎立’格局：\\n• 养老理财（银行理财子公司主导）：强调稳健增值、封闭运作、定期分红；\\n• 特定养老储蓄（工农中建四大行试点）：5年/10年/15年/20年期，利率上浮、本息保障；\\n• 商业养老保险（保险机构主责）：具备身故保障、 longevity 风险对冲、终身领取等不可替代功能。\\n\\n但现实是，多数消费者仍将‘养老储蓄’和‘养老理财’视为‘更安全的存款替代’，而对商业养老保险的认知仍停留在‘重疾/寿险延伸’层面。破局点在于——深度融合。\\n\\n头部险企已在探索：\\n✓ 将‘专属商业养老保险’与自建或合作养老社区的优先入住权、护理折扣、健康管理服务深度绑定；\\n✓ 基于再贷款支持的轻资产运营模式，降低养老社区初始投入门槛，加快‘保险产品—服务权益—数据反馈’链路闭环；\\n✓ 利用AI健康画像与慢病管理平台，为客户提供个性化健康干预建议，并支持根据客户健康状况变化，在合同约定范围内优化养老金领取方式（如转换领取频率或启动护理津贴责任等），助力实现更有质量的养老生活。\\n\\n▍三、角色重构：保险机构不只是风险承担者，更是养老生态组织者\\n\\n未来三年，养老金融的竞争维度将超越收益率比拼，转向三大能力比拼：\\n• 全链条服务能力：是否具备整合保险保障、健康干预、适老居住及照护支持的一体化供给能力？\\n• 长期资产配置能力：能否依托政策性资金工具，将养老保险资金直接投向养老社区、护理机构等真实底层资产？\\n• 客群精算建模能力：能否基于老年群体健康、行为及消费数据，开发针对性保障产品（如失能收入补偿险、认知症专项护理险）？\\n\\n值得期待的是，例如，泰康保险联合北京市西城区政府、国寿健投及腾讯健康，于2023年上线‘京颐通’服务平台，实现保单权益直兑社区体检、上门护理等12类服务，将保单权益兑换为体检、送餐、上门护理等高频服务，并反哺精算模型优化——这才是养老金融的‘高质量’内核。\\n\\n结语：\\n养老金融的黄金十年，不在填补缺口，而在创造价值。当一张保单能预约一间适老化房间，一次缴费可激活一套健康管家服务，保险机构就完成了从‘财务补偿者’到‘生活解决方案提供者’的战略升维。这片蓝海，属于敢重构、善深度融合、懂长线的人。\\n\\n（本文数据来源：中国人民银行2024年一季度金融统计数据报告、《关于金融支持养老服务业加快发展的指导意见》）\"}}', '{\"code\":0,\"message\":\"success\",\"data\":7,\"timestamp\":1787299915787,\"traceId\":\"4e2725e90eb84280a9219306b7998a76\"}', 0, '0:0:0:0:0:0:0:1', NULL, 'Mozilla/5.0 (iPhone; CPU iPhone OS 18_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.5 Mobile/15E148 Safari/604.1', 'mobile', 'macOS', 'Safari', 1, NULL, 51, '2026-08-21 16:11:56', '2026-08-21 16:11:56', 'system', 'system', 0, NULL);
