INSERT IGNORE INTO `system_log_agent` VALUES (752, 'a6c74fb570b24960b0462c9dfc6c80ad', 'agent', 'AG60785666', 'agent01', '文章转写', '抓取URL内容', NULL, NULL, NULL, NULL, '/agent-api/tools/article-rewrite/fetch-url', 'POST', '{\"dto\":{\"toolCode\":\"TL90008\",\"url\":\"https://baijiahao.baidu.com/s?id=1874131049966219395&wfr=spider&for=pc\"}}', '{\"code\":0,\"message\":\"success\",\"data\":{\"id\":14,\"toolCode\":\"TL90008\",\"agentCode\":\"AG60785666\",\"channelCode\":\"CH00001\",\"status\":\"CONTENT_FETCHED\",\"contentFetch\":\"{\\\"sourceType\\\":\\\"url\\\",\\\"sourceUrl\\\":\\\"https://baijiahao.baidu.com/s?id=1874131049966219395&wfr=spider&for=pc\\\",\\\"originalTitle\\\":\\\"创历史新高！我国44名专家获“IEC 1906奖”\\\",\\\"originalSource\\\":\\\"https://baijiahao.baidu.com/s?id=1874131049966219395&wfr=spider&for=pc\\\",\\\"originalContent\\\":\\\"百度首页 登录 搜索 复制 创历史新高！我国44名专家获“IEC 1906奖” 央视新闻 2026-08-21 19:10北京中央广播电视总台央视新闻官方账号 关注 记者今天从国家标准委了解到，国际电工委员会（IEC）近日公布“IEC 1906奖”获奖名单。我国共有44名专家荣膺该奖项，获奖人数创历史新高，再次彰显我国在国际电工标准化领域的技术实力与不断攀升的全球影响力。 “IEC 1906奖”设立于2004年，是为纪念IEC成立而设立的年度奖项，旨在表彰在IEC国际标准研制、技术活动及合格评定工作中作出突出贡献的活跃技术专家，是衡量各国专家在IEC技术体系中参与深度与贡献水平的重要标尺。 2026年，全球共有来自26个国家的231名专家获奖，我国获奖人数占获奖总人数的19%。我国的44位获奖专家来自33个领域，这些领域与国家“十五五”规划战略方向高度协同。 新型电力系统与新能源领域占比约32%，覆盖电力系统运行与控制、特高压直流输电、柔性输电与电力电子、太阳能光热发电与光伏、电化学储能、抽水蓄能与水力发电、海洋能发电及并网等关键方向，为我国加快构建新型能源体系、建设新型电力系统发挥了积极的引领作用。 传统产业领域占比约43%，涵盖智能制造与工业过程测量控制、低压电气与保护设备、测量继电器与保护设备、家用电器性能与安全、轨道交通电气牵引与信号通信、核仪器仪表与辐射防护等方向，有力助推传统产业提质增效、迈向中高端。 数智化赋能与信息技术领域占比约14%，涵盖新一代信息技术、音视频与多媒体系统、智慧城市、智慧能源与交通电气化等方向，深度契合“人工智能+”行动和数智技术赋能全局的战略部署。 新材料领域占比约7%，涵盖纳米材料、新型显示材料、磁性材料与电子元器件、电子电路基材等方向，为我国战略性新兴产业集群发展提供标准先导力量。 此外，在氢能燃料电池以及可再生能源合格评定等未来产业方向，亦有我国专家荣获奖项，展现出我国在面向未来的前沿技术标准布局中正在抢占先机。 此次获奖，不仅是对我国专家个人技术贡献的高度认可，更是我国在国际电工标准化领域战略布局、综合实力与持续贡献方面的集中体现。我国将继续深度参与国际标准治理，以更大格局、更强自信，推动中国方案走向世界，引领全球电工技术高质量发展。 （总台央视记者 李晶晶） ©2026中央广播电视总台版权所有。未经许可，请勿转载使用。 举报/反馈 0 0 收藏 分享 微信好友 新浪微博 复制链接 扫码分享至微信 手机看 百度APP扫一扫 手机看更方便 设为首页 关于百度 About Baidu 使用百度前必读 帮助中心 © Baidu 京ICP证030173号 京公网安备11000002000001号 顶部\\\",\\\"fetchTime\\\":\\\"2026-08-21T21:11:29.4253181\\\",\\\"fetchStatus\\\":\\\"success\\\"}\",\"summaryAnalysis\":null,\"rewriteResult\":null,\"auditResult\":null,\"imageResult\":null,\"publishInfo\":null,\"createdAt\":\"2026-08-21T21:11:29.4388398\",\"updatedAt\":\"2026-08-21T21:11:29.4388398\"},\"timestamp\":1787317889503,\"traceId\":\"a6c74fb570b24960b0462c9dfc6c80ad\"}', 0, '0:0:0:0:0:0:0:1', NULL, 'Mozilla/5.0 (iPhone; CPU iPhone OS 18_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.5 Mobile/15E148 Safari/604.1', 'mobile', 'macOS', 'Safari', 1, NULL, 747, '2026-08-21 21:11:30', '2026-08-21 21:11:30', 'system', 'system', 0, NULL);
