INSERT IGNORE INTO `system_log_organ` VALUES (873, '55c8d8d30a1f46e8bc0cb298d61a6faa', 'admin', 'AC00001', '超管员', '工具配置', '修改', NULL, NULL, NULL, NULL, '/admin-api/tool/info/TL00003', 'PUT', '{\"toolCode\":\"TL00003\",\"dto\":{\"toolName\":\"AI创作（主题创作）\",\"toolType\":\"aiartist\",\"toolDesc\":\"选择、上传或粘贴文章，进行内容转写与再创作\",\"configJson\":\"{\\\"purpose\\\":\\\"science\\\",\\\"systemPrompt\\\":\\\"你是大雁养老的资深内容编辑，擅长把给定文章转写为结构清晰、通俗易懂、有传播力的保险行业科普内容。转写须忠于原文事实，不编造资料外信息；用简体中文，先给读者最关心的结论，再分层展开；结尾给出认知引导而非硬推销。\\\",\\\"icon\\\":\\\"主\\\",\\\"pipeline\\\":{\\\"temps\\\":{\\\"body\\\":0.6,\\\"audit\\\":0.2,\\\"digest\\\":0.2,\\\"polish\\\":0.5,\\\"revise\\\":0.3,\\\"titles\\\":0.7,\\\"outline\\\":0.5,\\\"strategy\\\":0.7},\\\"prompts\\\":{},\\\"nodeSize\\\":\\\"1280*720\\\",\\\"scoreRange\\\":[70,99],\\\"materialMax\\\":8888,\\\"titleLimits\\\":{\\\"1\\\":30,\\\"2\\\":20,\\\"3\\\":15,\\\"4\\\":20},\\\"coverSizeXhs\\\":\\\"1080*1440\\\",\\\"bannedPhrases\\\":[\\\"保证收益\\\",\\\"稳赚\\\",\\\"包赚\\\",\\\"最高级\\\",\\\"国家级\\\",\\\"顶级\\\",\\\"100%\\\",\\\"百分百\\\",\\\"绝对\\\",\\\"秒杀\\\",\\\"史上\\\"],\\\"lengthWindows\\\":{\\\"1\\\":[800,2500],\\\"2\\\":[30,400],\\\"3\\\":[400,2500],\\\"4\\\":[350,1500]},\\\"imageCountHints\\\":{\\\"1\\\":\\\"coverImage 1 张（1024*1024）+ 正文节点配图 3-4 张（1280*720）\\\",\\\"3\\\":\\\"仅规划 coverImage 1 张（1024*1024），所有 nodes 的 imageInsertion 必须为 null\\\",\\\"4\\\":\\\"coverImage 1 张（1080*1440）+ 节点配位合计 2-4 张（1280*720）\\\"},\\\"polishKeepRatio\\\":0.95,\\\"titleCountLimit\\\":5,\\\"coverSizeDefault\\\":\\\"1024*1024\\\",\\\"formInstructions\\\":{\\\"1\\\":\\\"微信公众号精品图文（1200-1500 字，HTML 片段 <h2>/<p>，标题 ≤30 字）\\\",\\\"2\\\":\\\"朋友圈文案（≤200 字纯文本 + 1-2 emoji + 1 个 #话题标签，标题=首句钩子 ≤20 字）\\\",\\\"3\\\":\\\"短视频口播脚本（60-90 秒，【画面】【口播】【字幕】分镜，标题 ≤15 字）\\\",\\\"4\\\":\\\"小红书笔记（600-800 字，Emoji 列表 + #标签段，标题 ≤20 字）\\\"},\\\"styleInstructions\\\":{\\\"warm\\\":\\\"温情软文风格：以长辈/家庭的真实生活场景切入，情感细腻、语气温暖，引发共鸣\\\",\\\"colloquial\\\":\\\"口语化风格：短句、亲切、像朋友聊天\\\",\\\"professional\\\":\\\"专业科普风格：用词严谨、逻辑清晰、多用数据与术语，面向对养老品质有要求的家庭决策者\\\",\\\"authoritative\\\":\\\"权威报告风格：结论先行、分点论述、数据化表达，塑造平台专业可信形象\\\"},\\\"imagePollTimeoutMs\\\":90000,\\\"imageFallbackPrompt\\\":\\\"Warm lifestyle photograph, elderly care concept related to: {promptZh}, single subject, shallow depth of field\\\",\\\"audienceInstructions\\\":{\\\"elder\\\":\\\"老人本人（55-75 岁）：直白温暖、短句、从老人自身利益出发，避免术语\\\",\\\"general\\\":\\\"40-70 岁客户及其子女：通俗易懂\\\",\\\"children\\\":\\\"为父母养老做决策的子女（30-50 岁）：理性、数据与家庭责任视角，专业可信赖\\\"},\\\"imageRetryAfterFailures\\\":2}}\",\"status\":1,\"remark\":\"预置：agent 端获客工具\"}}', '{\"code\":0,\"message\":\"success\",\"timestamp\":1787065443165,\"traceId\":\"55c8d8d30a1f46e8bc0cb298d61a6faa\"}', 0, '0:0:0:0:0:0:0:1', NULL, 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) ZCode/3.7.7 Chrome/146.0.7680.80 Electron/41.0.3 Safari/537.36', 'pc', 'Windows', 'Chrome', 1, NULL, 154, '2026-08-18 23:04:03', '2026-08-18 23:04:03', 'system', 'system', 0, NULL);
